    };
    let dense_config = SegmentConfig {
        vector_data: HashMap::from([(
            SPARSE_VECTOR_NAME.to_owned(),
            VectorDataConfig {
                size: dim,
                distance,
                storage_type: VectorStorageType::Memory,
                index: Indexes::Plain {},
                quantization_config: None,
            },
        )]),
        payload_storage_type: Default::default(),
        sparse_vector_data: Default::default(),
    };

    let mut sparse_segment = build_segment(dir.path(), &sparse_config, true).unwrap();
    let mut dense_segment = build_segment(dir.path(), &dense_config, true).unwrap();

    for n in 0..num_vectors {
        let (sparse_vector, dense_vector) = random_named_vector(&mut rnd, dim);

        let idx = n.into();
        sparse_segment
            .upsert_point(n as SeqNumberType, idx, sparse_vector)
            .unwrap();
        dense_segment
            .upsert_point(n as SeqNumberType, idx, dense_vector)
            .unwrap();
    }

    let payload_index_ptr = sparse_segment.payload_index.clone();

    let vector_storage = &sparse_segment.vector_data[SPARSE_VECTOR_NAME].vector_storage;
    let mut sparse_index = SparseVectorIndex::<InvertedIndexRam>::open(
        SparseIndexConfig {
            full_scan_threshold: Some(DEFAULT_SPARSE_FULL_SCAN_THRESHOLD),
            index_type: SparseIndexType::ImmutableRam,
        },
        sparse_segment.id_tracker.clone(),
        vector_storage.clone(),
        payload_index_ptr.clone(),
        index_dir.path(),
    )
    .unwrap();

    sparse_index.build_index(&stopped).unwrap();

    let top = 3;
    let attempts = 100;
    for i in 0..attempts {
        // do discovery search
        let (sparse_query, dense_query) = random_discovery_query(&mut rnd, dim);

        let sparse_discovery_result = sparse_index
            .search(&[&sparse_query], None, top, None, &false.into())
            .unwrap();

        let dense_discovery_result = dense_segment.vector_data[SPARSE_VECTOR_NAME]
            .vector_index
            .borrow()
            .search(&[&dense_query], None, top, None, &false.into())
            .unwrap();

        // check id only because scores can be epsilon-size different
        assert_eq!(
            sparse_discovery_result[0]
                .iter()
                .map(|r| r.idx)
                .collect_vec(),
            dense_discovery_result[0]
                .iter()
                .map(|r| r.idx)
                .collect_vec(),
        );

        // do regular nearest search
        let (sparse_query, dense_query) = random_nearest_query(&mut rnd, dim);
        let sparse_search_result = sparse_index
            .search(&[&sparse_query], None, top, None, &false.into())
            .unwrap();

        let dense_search_result = dense_segment.vector_data[SPARSE_VECTOR_NAME]
            .vector_index
            .borrow()
            .search(&[&dense_query], None, top, None, &false.into())
            .unwrap();

        // check that nearest search uses sparse index
        let telemetry = sparse_index.get_telemetry_data();
        assert_eq!(telemetry.unfiltered_sparse.count, i + 1);

        // check id only because scores can be epsilon-size different
        assert_eq!(
            sparse_search_result[0].iter().map(|r| r.idx).collect_vec(),
            dense_search_result[0].iter().map(|r| r.idx).collect_vec(),
        );
    }
}

fn build_test_segments(path_struct: &Path, path_plain: &Path) -> (Segment, Segment) {
    let mut rnd = StdRng::seed_from_u64(42);

    let config = SegmentConfig {
        vector_data: HashMap::from([(
            DEFAULT_VECTOR_NAME.to_owned(),
            VectorDataConfig {
                size: DIM,
                distance: Distance::Dot,
                storage_type: VectorStorageType::Memory,
                index: Indexes::Plain {},
                quantization_config: None,
            },
        )]),
        sparse_vector_data: Default::default(),
        payload_storage_type: Default::default(),
    };

    let mut plain_segment = build_segment(path_plain, &config, true).unwrap();
    let mut struct_segment = build_segment(path_struct, &config, true).unwrap();

    let num_points = 3000;
    let points_to_delete = 500;
    let points_to_clear = 500;

    let mut opnum = 0;
    struct_segment
        .create_field_index(opnum, INT_KEY_2, Some(&Integer.into()))
        .unwrap();

    opnum += 1;
    for n in 0..num_points {
        let idx = n.into();
        let vector = random_vector(&mut rnd, DIM);
        let payload: Payload = generate_diverse_payload(&mut rnd);

        plain_segment
            .upsert_point(opnum, idx, only_default_vector(&vector))
            .unwrap();
        struct_segment
            .upsert_point(opnum, idx, only_default_vector(&vector))
            .unwrap();
        plain_segment
            .set_full_payload(opnum, idx, &payload)
            .unwrap();
        struct_segment
            .set_full_payload(opnum, idx, &payload)
            .unwrap();

        opnum += 1;
    }

    struct_segment
        .create_field_index(opnum, STR_KEY, Some(&Keyword.into()))
        .unwrap();
    struct_segment
        .create_field_index(opnum, INT_KEY, None)
        .unwrap();
    struct_segment
        .create_field_index(opnum, GEO_KEY, Some(&PayloadSchemaType::Geo.into()))
        .unwrap();
    struct_segment
        .create_field_index(opnum, TEXT_KEY, Some(&PayloadSchemaType::Text.into()))
        .unwrap();
    struct_segment
        .create_field_index(opnum, FLICKING_KEY, Some(&Integer.into()))
        .unwrap();

    for _ in 0..points_to_clear {
        opnum += 1;
        let idx_to_remove = rnd.gen_range(0..num_points);
        plain_segment
            .clear_payload(opnum, idx_to_remove.into())
            .unwrap();
        struct_segment
            .clear_payload(opnum, idx_to_remove.into())
            .unwrap();
    }

    for _ in 0..points_to_delete {
        opnum += 1;
        let idx_to_remove = rnd.gen_range(0..num_points);
        plain_segment
            .delete_point(opnum, idx_to_remove.into())
            .unwrap();
        struct_segment
            .delete_point(opnum, idx_to_remove.into())
            .unwrap();
    }

    for (field, indexes) in struct_segment.payload_index.borrow().field_indexes.iter() {
        for index in indexes {
            assert!(index.count_indexed_points() < num_points as usize);
            if field != FLICKING_KEY {
                assert!(
                    index.count_indexed_points()
                        > (num_points as usize - points_to_delete - points_to_clear)
                );
            }
        }
    }

    (struct_segment, plain_segment)
}

