pub fn max_rayon_threads(max_indexing_threads: usize) -> usize {
    if max_indexing_threads == 0 {
        let num_cpu = crate::common::cpu::get_num_cpus();
        num_cpu.clamp(1, MAX_AUTO_RAYON_THREADS)
    } else {
        max_indexing_threads
    }
}

pub fn new(
    raw_scorer: &'a dyn RawScorer,
    filter_context: Option<&'a dyn FilterContext>,
) -> Self {
    FilteredScorer {
        raw_scorer,
        filter_context,
        points_buffer: Vec::new(),
    }
}

pub fn check_vector(&self, point_id: PointOffsetType) -> bool {
    match self.filter_context {
        None => self.raw_scorer.check_vector(point_id),
        Some(f) => f.check(point_id) && self.raw_scorer.check_vector(point_id),
    }
}

/// Method filters and calculates scores for the given slice of points IDs
///
/// For performance reasons this function mutates input values.
/// For result slice allocation this function mutates self.
///
/// # Arguments
///
/// * `point_ids` - list of points to score. *Warn*: This input will be wrecked during the execution.
/// * `limit` - limits the number of points to process after filtering.
///
pub fn score_points(
    &mut self,
    point_ids: &mut [PointOffsetType],
    limit: usize,
) -> &[ScoredPointOffset] {
    // apply filter and store filtered ids to source slice memory
    let filtered_point_ids = match self.filter_context {
        None => point_ids,
        Some(f) => {
            let len = point_ids.len();
            let mut filtered_len = 0;
            for i in 0..len {
                let point_id = point_ids[i];
                if f.check(point_id) {
                    point_ids[filtered_len] = point_id;
                    filtered_len += 1;
                }
            }
            &point_ids[0..filtered_len]
        }
    };
    if limit == 0 {
        self.points_buffer
            .resize_with(filtered_point_ids.len(), ScoredPointOffset::default);
    } else {
        self.points_buffer
            .resize_with(limit, ScoredPointOffset::default);
    }
    let count = self
        .raw_scorer
        .score_points(filtered_point_ids, &mut self.points_buffer);
    &self.points_buffer[0..count]
}

pub fn score_point(&self, point_id: PointOffsetType) -> ScoreType {
    self.raw_scorer.score_point(point_id)
}

pub fn score_internal(&self, point_a: PointOffsetType, point_b: PointOffsetType) -> ScoreType {
    self.raw_scorer.score_internal(point_a, point_b)
}

fn get_visited_list_from_pool(&self) -> VisitedListHandle {
    self.visited_pool.get(self.links.num_points())
}

fn links_map<F>(&self, point_id: PointOffsetType, level: usize, mut f: F)
where
    F: FnMut(PointOffsetType),
{
    for link in self.links.links(point_id, level) {
        f(*link);
    }
}

fn get_m(&self, level: usize) -> usize {
    if level == 0 {
        self.m0
    } else {
        self.m
    }
}

/// Returns the highest level this point is included in
pub fn point_level(&self, point_id: PointOffsetType) -> usize {
    self.links.point_level(point_id)
}

fn get_entry_point(
    &self,
    points_scorer: &FilteredScorer,
    custom_entry_points: Option<&[PointOffsetType]>,
) -> Option<EntryPoint> {
    // Try to get it from custom entry points
    custom_entry_points
        .and_then(|custom_entry_points| {
            custom_entry_points
                .iter()
                .filter(|&&point_id| points_scorer.check_vector(point_id))
                .map(|&point_id| {
                    let level = self.point_level(point_id);
                    EntryPoint { point_id, level }
                })
                .max_by_key(|ep| ep.level)
        })
        .or_else(|| {
            // Otherwise use normal entry points
            self.entry_points
                .get_entry_point(|point_id| points_scorer.check_vector(point_id))
        })
}

pub fn search(
    &self,
    top: usize,
    ef: usize,
    mut points_scorer: FilteredScorer,
    custom_entry_points: Option<&[PointOffsetType]>,
) -> Vec<ScoredPointOffset> {
    let Some(entry_point) = self.get_entry_point(&points_scorer, custom_entry_points) else {
        return Vec::default();
    };

    let zero_level_entry = self.search_entry(
        entry_point.point_id,
        entry_point.level,
        0,
        &mut points_scorer,
    );
    let nearest = self.search_on_level(zero_level_entry, 0, max(top, ef), &mut points_scorer);
    nearest.into_iter().take(top).collect_vec()
}

