fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
    Some(self.cmp(other))
}

fn cmp(&self, other: &Self) -> Ordering {
    self.level.cmp(&other.level)
}

pub fn new(extra_entry_points: usize) -> Self {
    EntryPoints {
        entry_points: vec![],
        extra_entry_points: FixedLengthPriorityQueue::new(extra_entry_points),
    }
}

pub fn merge_from_other(&mut self, mut other: EntryPoints) {
    self.entry_points.append(&mut other.entry_points);
    // Do not merge `extra_entry_points` to prevent duplications
}

pub fn new_point<F>(
    &mut self,
    new_point: PointOffsetType,
    level: usize,
    checker: F,
) -> Option<EntryPoint>
where
    F: Fn(PointOffsetType) -> bool,
{
    // there are 3 cases:
    // - There is proper entry point for a new point higher or same level - return the point
    // - The new point is higher than any alternative - return the next best thing
    // - There is no point and alternatives - return None

    for i in 0..self.entry_points.len() {
        let candidate = &self.entry_points[i];

        if !checker(candidate.point_id) {
            continue; // Checkpoint does not fulfil filtering conditions. Hence, does not "exists"
        }
        // Found checkpoint candidate
        return if candidate.level >= level {
            // The good checkpoint exists.
            // Return it, and also try to save given if required
            self.extra_entry_points.push(EntryPoint {
                point_id: new_point,
                level,
            });
            Some(candidate.clone())
        } else {
            // The current point is better than existing
            let entry = self.entry_points[i].clone();
            self.entry_points[i] = EntryPoint {
                point_id: new_point,
                level,
            };
            self.extra_entry_points.push(entry.clone());
            Some(entry)
        };
    }
    // No entry points found. Create a new one and return self
    let new_entry = EntryPoint {
        point_id: new_point,
        level,
    };
    self.entry_points.push(new_entry);
    None
}

/// Find the highest `EntryPoint` which satisfies filtering condition of `checker`
pub fn get_entry_point<F>(&self, checker: F) -> Option<EntryPoint>
where
    F: Fn(PointOffsetType) -> bool,
{
    self.entry_points
        .iter()
        .find(|entry| checker(entry.point_id))
        .cloned()
        .or_else(|| {
            // Searching for at least some entry point
            self.extra_entry_points
                .iter()
                .filter(|entry| checker(entry.point_id))
                .cloned()
                .max_by_key(|ep| ep.level)
        })
}

fn check(&self, point_id: PointOffsetType) -> bool {
    if point_id == self.current_point {
        return false; // Do not match current point while inserting it (second time)
    }
    self.filter_list.check(point_id)
}

pub fn new(a: PointOffsetType, b: PointOffsetType) -> Self {
    PointPair {
        a: min(a, b),
        b: max(a, b),
    }
}

fn hasher() -> impl Hasher {
    SeaHasher::new()
}

pub fn new(size: usize) -> Self {
    let mut cache = Vec::with_capacity(size);
    cache.resize(size, None);
    DistanceCache {
        cache,
        hits: 0,
        misses: 0,
    }
}

pub fn get(&self, point_a: PointOffsetType, point_b: PointOffsetType) -> Option<ScoreType> {
    let points = PointPair::new(point_a, point_b);
    let mut s = DistanceCache::hasher();
    points.hash(&mut s);
    let idx = s.finish() as usize % self.cache.len();

    self.cache[idx].as_ref().and_then(|x| {
        if x.points == points {
            Some(x.value)
        } else {
            None
        }
    })
}

pub fn put(&mut self, point_a: PointOffsetType, point_b: PointOffsetType, value: ScoreType) {
    let points = PointPair::new(point_a, point_b);
    let mut s = DistanceCache::hasher();
    points.hash(&mut s);
    let idx = s.finish() as usize % self.cache.len();
    self.cache[idx] = Some(CacheObj { points, value });
}

fn default() -> Self {
    DistanceCache::new(0)
}

pub(crate) fn create_graph_layer_builder_fixture<TMetric: Metric, R>(
    num_vectors: usize,
    m: usize,
    dim: usize,
    use_heuristic: bool,
    rng: &mut R,
) -> (TestRawScorerProducer<TMetric>, GraphLayersBuilder)
where
    R: Rng + ?Sized,
{
    let ef_construct = 16;
    let entry_points_num = 10;

    let vector_holder = TestRawScorerProducer::<TMetric>::new(dim, num_vectors, rng);

    let mut graph_layers_builder = GraphLayersBuilder::new(
        num_vectors,
        m,
        m * 2,
        ef_construct,
        entry_points_num,
        use_heuristic,
    );

    for idx in 0..(num_vectors as PointOffsetType) {
        let fake_filter_context = FakeFilterContext {};
        let added_vector = vector_holder.vectors.get(idx).to_vec();
        let raw_scorer = vector_holder.get_raw_scorer(added_vector.clone()).unwrap();
        let scorer = FilteredScorer::new(raw_scorer.as_ref(), Some(&fake_filter_context));
        let level = graph_layers_builder.get_random_layer(rng);
        graph_layers_builder.set_levels(idx, level);
        graph_layers_builder.link_new_point(idx, scorer);
    }
    (vector_holder, graph_layers_builder)
}

pub(crate) fn create_graph_layer_fixture<TMetric: Metric, R>(
    num_vectors: usize,
    m: usize,
    dim: usize,
    use_heuristic: bool,
    rng: &mut R,
    links_path: Option<&Path>,
) -> (TestRawScorerProducer<TMetric>, GraphLayers<GraphLinksRam>)
where
    R: Rng + ?Sized,
{
    let (vector_holder, graph_layers_builder) =
        create_graph_layer_builder_fixture(num_vectors, m, dim, use_heuristic, rng);

    (
        vector_holder,
        graph_layers_builder.into_graph_layers(links_path).unwrap(),
    )
}

#[test]
fn test_graph_connectivity() {
    let stopped = AtomicBool::new(false);

    let dim = 32;
    let m = 16;
    let num_vectors: u64 = 1_000;
    let ef_construct = 100;
    let distance = Distance::Cosine;
    let full_scan_threshold = 10_000;

    let mut rnd = thread_rng();

    let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
    let hnsw_dir = Builder::new().prefix("hnsw_dir").tempdir().unwrap();

    let config = SegmentConfig {
        vector_data: HashMap::from([(
            DEFAULT_VECTOR_NAME.to_owned(),
            VectorDataConfig {
                size: dim,
                distance,
                storage_type: VectorStorageType::Memory,
                index: Indexes::Plain {},
                quantization_config: None,
            },
        )]),
        payload_storage_type: Default::default(),
        sparse_vector_data: Default::default(),
    };

    let mut segment = build_segment(dir.path(), &config, true).unwrap();
    for n in 0..num_vectors {
        let idx = n.into();
        let vector = random_vector(&mut rnd, dim);

        segment
            .upsert_point(n as SeqNumberType, idx, only_default_vector(&vector))
            .unwrap();
    }

    let payload_index_ptr = segment.payload_index.clone();

    let hnsw_config = HnswConfig {
        m,
        ef_construct,
        full_scan_threshold,
        max_indexing_threads: 4,
        on_disk: Some(false),
        payload_m: None,
    };

    let mut hnsw_index = HNSWIndex::<GraphLinksRam>::open(
        hnsw_dir.path(),
        segment.id_tracker.clone(),
        segment.vector_data[DEFAULT_VECTOR_NAME]
            .vector_storage
            .clone(),
        Default::default(),
        payload_index_ptr.clone(),
        hnsw_config,
    )
    .unwrap();

    hnsw_index.build_index(&stopped).unwrap();

    let graph = hnsw_index.graph().unwrap();

    let mut reverse_links = vec![vec![]; num_vectors as usize];

    for point_id in 0..num_vectors {
        let links = graph.links.links(point_id as PointOffsetType, 0);
        for link in links {
            reverse_links[*link as usize].push(point_id);
        }
    }

    for point_id in 0..num_vectors {
        assert!(
            !reverse_links[point_id as usize].is_empty(),
            "Point {} has no inbound links",
            point_id
        );
    }
}

fn search_in_builder(
    builder: &GraphLayersBuilder,
    top: usize,
    ef: usize,
    mut points_scorer: FilteredScorer,
) -> Vec<ScoredPointOffset> {
    let entry_point = match builder
        .get_entry_points()
        .get_entry_point(|point_id| points_scorer.check_vector(point_id))
    {
        None => return vec![],
        Some(ep) => ep,
    };

    let zero_level_entry = builder.search_entry(
        entry_point.point_id,
        entry_point.level,
        0,
        &mut points_scorer,
    );

    let nearest = builder.search_on_level(zero_level_entry, 0, max(top, ef), &mut points_scorer);
    nearest.into_iter().take(top).collect_vec()
}

#[test]
/// Check that HNSW index with raw and compacted links gives the same results
fn test_compact_graph_layers() {
    let num_vectors = 1000;
    let num_queries = 100;
    let m = 16;
    let dim = 8;
    let top = 5;
    let ef = 100;

    let mut rng = StdRng::seed_from_u64(42);

    let (vector_holder, graph_layers_builder) =
        create_graph_layer_builder_fixture::<CosineMetric, _>(num_vectors, m, dim, false, &mut rng);

    let queries = (0..num_queries)
        .map(|_| random_vector(&mut rng, dim))
        .collect_vec();

    let reference_results = queries
        .iter()
        .map(|query| {
            let raw_scorer = vector_holder.get_raw_scorer(query.clone()).unwrap();
            let scorer = FilteredScorer::new(raw_scorer.as_ref(), None);
            search_in_builder(&graph_layers_builder, top, ef, scorer)
        })
        .collect_vec();

    let graph_layers = graph_layers_builder
        .into_graph_layers::<GraphLinksRam>(None)
        .unwrap();

    let results = queries
        .iter()
        .map(|query| {
            let raw_scorer = vector_holder.get_raw_scorer(query.clone()).unwrap();
            let scorer = FilteredScorer::new(raw_scorer.as_ref(), None);
            graph_layers.search(top, ef, scorer, None)
        })
        .collect_vec();

    assert_eq!(reference_results, results);
}

pub fn open(
    path: &Path,
    id_tracker: Arc<AtomicRefCell<IdTrackerSS>>,
    vector_storage: Arc<AtomicRefCell<VectorStorageEnum>>,
    quantized_vectors: Arc<AtomicRefCell<Option<QuantizedVectors>>>,
    payload_index: Arc<AtomicRefCell<StructPayloadIndex>>,
    hnsw_config: HnswConfig,
) -> OperationResult<Self> {
    create_dir_all(path)?;

    let config_path = HnswGraphConfig::get_config_path(path);
    let config = if config_path.exists() {
        HnswGraphConfig::load(&config_path)?
    } else {
        let vector_storage = vector_storage.borrow();
        let available_vectors = vector_storage.available_vector_count();
        let full_scan_threshold = hnsw_config.full_scan_threshold.saturating_mul(BYTES_IN_KB)
            / (vector_storage.vector_dim() * VECTOR_ELEMENT_SIZE);

        HnswGraphConfig::new(
            hnsw_config.m,
            hnsw_config.ef_construct,
            full_scan_threshold,
            hnsw_config.max_indexing_threads,
            hnsw_config.payload_m,
            available_vectors,
        )
    };

    let graph_path = GraphLayers::<TGraphLinks>::get_path(path);
    let graph_links_path = GraphLayers::<TGraphLinks>::get_links_path(path);
    let graph = if graph_path.exists() {
        Some(GraphLayers::load(&graph_path, &graph_links_path)?)
    } else {
        None
    };
    Ok(HNSWIndex {
        id_tracker,
        vector_storage,
        quantized_vectors,
        payload_index,
        config,
        path: path.to_owned(),
        graph,
        searches_telemetry: HNSWSearchesTelemetry {
            unfiltered_hnsw: OperationDurationsAggregator::new(),
            unfiltered_plain: OperationDurationsAggregator::new(),
            small_cardinality: OperationDurationsAggregator::new(),
            large_cardinality: OperationDurationsAggregator::new(),
            exact_filtered: OperationDurationsAggregator::new(),
            exact_unfiltered: OperationDurationsAggregator::new(),
        },
    })
}

