fn default() -> Self {
    VisitedList {
        current_iter: 1,
        visit_counters: vec![],
    }
}

fn new(num_points: usize) -> Self {
    VisitedList {
        current_iter: 1,
        visit_counters: vec![0; num_points],
    }
}

fn drop(&mut self) {
    self.pool
        .return_back(std::mem::take(&mut self.visited_list));
}

fn new(pool: &'a VisitedPool, data: VisitedList) -> Self {
    VisitedListHandle {
        pool,
        visited_list: data,
    }
}

pub fn get_current_iteration_id(&self) -> usize {
    self.visited_list.current_iter
}

/// Return `true` if visited
pub fn check(&self, point_id: PointOffsetType) -> bool {
    self.visited_list
        .visit_counters
        .get(point_id as usize)
        .map_or(false, |x| *x >= self.visited_list.current_iter)
}

/// Updates visited list
/// return `true` if point was visited before
pub fn check_and_update_visited(&mut self, point_id: PointOffsetType) -> bool {
    let idx = point_id as usize;
    if idx >= self.visited_list.visit_counters.len() {
        self.visited_list.visit_counters.resize(idx + 1, 0);
    }
    let prev_value = self.visited_list.visit_counters[idx];
    self.visited_list.visit_counters[idx] = self.visited_list.current_iter;
    prev_value >= self.visited_list.current_iter
}

pub fn next_iteration(&mut self) {
    self.visited_list.current_iter += 1;
}

pub fn new() -> Self {
    VisitedPool {
        pool: RwLock::new(Vec::with_capacity(*POOL_KEEP_LIMIT)),
    }
}

pub fn get(&self, num_points: usize) -> VisitedListHandle {
    match self.pool.write().pop() {
        None => VisitedListHandle::new(self, VisitedList::new(num_points)),
        Some(mut data) => {
            data.visit_counters.resize(num_points, 0);
            let mut visited_list = VisitedListHandle::new(self, data);
            visited_list.next_iteration();
            visited_list
        }
    }
}

fn return_back(&self, data: VisitedList) {
    let mut pool = self.pool.write();
    if pool.len() < *POOL_KEEP_LIMIT {
        pool.push(data);
    }
}

fn default() -> Self {
    VisitedPool::new()
}

pub fn check_optimized_filter(filter: &OptimizedFilter, point_id: PointOffsetType) -> bool {
    check_should(&filter.should, point_id)
        && check_must(&filter.must, point_id)
        && check_must_not(&filter.must_not, point_id)
}

fn check_condition(condition: &OptimizedCondition, point_id: PointOffsetType) -> bool {
    match condition {
        OptimizedCondition::Filter(filter) => check_optimized_filter(filter, point_id),
        OptimizedCondition::Checker(checker) => checker(point_id),
    }
}

fn check_should(should: &Option<Vec<OptimizedCondition>>, point_id: PointOffsetType) -> bool {
    let check = |condition| check_condition(condition, point_id);
    match should {
        None => true,
        Some(conditions) => conditions.iter().any(check),
    }
}

fn check_must(must: &Option<Vec<OptimizedCondition>>, point_id: PointOffsetType) -> bool {
    let check = |condition| check_condition(condition, point_id);
    match must {
        None => true,
        Some(conditions) => conditions.iter().all(check),
    }
}

fn check_must_not(must: &Option<Vec<OptimizedCondition>>, point_id: PointOffsetType) -> bool {
    let check = |condition| !check_condition(condition, point_id);
    match must {
        None => true,
        Some(conditions) => conditions.iter().all(check),
    }
}

pub fn new(payload_storage: Arc<AtomicRefCell<PayloadStorageEnum>>) -> Self {
    Self {
        payload_storage,
        empty_payload: Default::default(),
    }
}

pub fn with_payload<F, G>(&self, point_id: PointOffsetType, callback: F) -> G
where
    F: FnOnce(OwnedPayloadRef) -> G,
{
    let payload_storage_guard = self.payload_storage.borrow();
    let payload_ptr_opt = match payload_storage_guard.deref() {
        PayloadStorageEnum::InMemoryPayloadStorage(s) => {
            s.payload_ptr(point_id).map(|x| x.into())
        }
        PayloadStorageEnum::SimplePayloadStorage(s) => {
            s.payload_ptr(point_id).map(|x| x.into())
        }
        // Warn: Possible panic here
        // Currently, it is possible that `read_payload` fails with Err,
        // but it seems like a very rare possibility which might only happen
        // if something is wrong with disk or storage is corrupted.
        //
        // In both cases it means that service can't be of use any longer.
        // It is as good as dead. Therefore it is tolerable to just panic here.
        // Downside is - API user won't be notified of the failure.
        // It will just timeout.
        //
        // The alternative:
        // Rewrite condition checking code to support error reporting.
        // Which may lead to slowdown and assumes a lot of changes.
        PayloadStorageEnum::OnDiskPayloadStorage(s) => s
            .read_payload(point_id)
            .unwrap_or_else(|err| panic!("Payload storage is corrupted: {err}"))
            .map(|x| x.into()),
    };

    let payload = if let Some(payload_ptr) = payload_ptr_opt {
        payload_ptr
    } else {
        (&self.empty_payload).into()
    };

    callback(payload)
}

/// Converts user-provided filtering condition into optimized representation
///
/// Optimizations:
///
/// * Convert each condition into a checker function
/// * Use column index, avoid reading Payload, if possible
/// * Re-order operations using estimated cardinalities
///
/// ToDo: Add optimizations between clauses
///
/// # Arguments
///
/// * `filter` - original filter
/// * `id_tracker` - used for converting collection-level ids into segment-level offsets of HasId condition
/// * `estimator` - function to estimate cardinality of individual conditions
/// * `total` - total number of points in segment (used for cardinality estimation)
///
/// # Result
///
/// Optimized query + Cardinality estimation
pub fn optimize_filter<'a, F>(
    filter: &'a Filter,
    id_tracker: &IdTrackerSS,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    estimator: &F,
    total: usize,
) -> (OptimizedFilter<'a>, CardinalityEstimation)
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    let mut filter_estimations: Vec<CardinalityEstimation> = vec![];

    let optimized_filter = OptimizedFilter {
        should: filter.should.as_ref().and_then(|conditions| {
            if !conditions.is_empty() {
                let (optimized_conditions, estimation) = optimize_should(
                    conditions,
                    id_tracker,
                    field_indexes,
                    payload_provider.clone(),
                    estimator,
                    total,
                );
                filter_estimations.push(estimation);
                Some(optimized_conditions)
            } else {
                None
            }
        }),
        must: filter.must.as_ref().and_then(|conditions| {
            if !conditions.is_empty() {
                let (optimized_conditions, estimation) = optimize_must(
                    conditions,
                    id_tracker,
                    field_indexes,
                    payload_provider.clone(),
                    estimator,
                    total,
                );
                filter_estimations.push(estimation);
                Some(optimized_conditions)
            } else {
                None
            }
        }),
        must_not: filter.must_not.as_ref().and_then(|conditions| {
            if !conditions.is_empty() {
                let (optimized_conditions, estimation) = optimize_must_not(
                    conditions,
                    id_tracker,
                    field_indexes,
                    payload_provider.clone(),
                    estimator,
                    total,
                );
                filter_estimations.push(estimation);
                Some(optimized_conditions)
            } else {
                None
            }
        }),
    };

    (
        optimized_filter,
        combine_must_estimations(&filter_estimations, total),
    )
}

fn convert_conditions<'a, F>(
    conditions: &'a [Condition],
    id_tracker: &IdTrackerSS,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    estimator: &F,
    total: usize,
) -> Vec<(OptimizedCondition<'a>, CardinalityEstimation)>
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    conditions
        .iter()
        .map(|condition| match condition {
            Condition::Filter(filter) => {
                let (optimized_filter, estimation) = optimize_filter(
                    filter,
                    id_tracker,
                    field_indexes,
                    payload_provider.clone(),
                    estimator,
                    total,
                );
                (OptimizedCondition::Filter(optimized_filter), estimation)
            }
            _ => {
                let estimation = estimator(condition);
                let condition_checker = condition_converter(
                    condition,
                    field_indexes,
                    payload_provider.clone(),
                    id_tracker,
                );
                (OptimizedCondition::Checker(condition_checker), estimation)
            }
        })
        .collect()
}

fn optimize_should<'a, F>(
    conditions: &'a [Condition],
    id_tracker: &IdTrackerSS,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    estimator: &F,
    total: usize,
) -> (Vec<OptimizedCondition<'a>>, CardinalityEstimation)
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    let mut converted = convert_conditions(
        conditions,
        id_tracker,
        field_indexes,
        payload_provider,
        estimator,
        total,
    );
    // More probable conditions first
    converted.sort_by_key(|(_, estimation)| Reverse(estimation.exp));
    let (conditions, estimations): (Vec<_>, Vec<_>) = converted.into_iter().unzip();

    (conditions, combine_should_estimations(&estimations, total))
}

fn optimize_must<'a, F>(
    conditions: &'a [Condition],
    id_tracker: &IdTrackerSS,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    estimator: &F,
    total: usize,
) -> (Vec<OptimizedCondition<'a>>, CardinalityEstimation)
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    let mut converted = convert_conditions(
        conditions,
        id_tracker,
        field_indexes,
        payload_provider,
        estimator,
        total,
    );
    // Less probable conditions first
    converted.sort_by_key(|(_, estimation)| estimation.exp);
    let (conditions, estimations): (Vec<_>, Vec<_>) = converted.into_iter().unzip();

    (conditions, combine_must_estimations(&estimations, total))
}

fn optimize_must_not<'a, F>(
    conditions: &'a [Condition],
    id_tracker: &IdTrackerSS,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    estimator: &F,
    total: usize,
) -> (Vec<OptimizedCondition<'a>>, CardinalityEstimation)
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    let mut converted = convert_conditions(
        conditions,
        id_tracker,
        field_indexes,
        payload_provider,
        estimator,
        total,
    );
    // More probable conditions first, as it will be reverted
    converted.sort_by_key(|(_, estimation)| estimation.exp);
    let (conditions, estimations): (Vec<_>, Vec<_>) = converted.into_iter().unzip();

    (
        conditions,
        combine_must_estimations(
            &estimations
                .into_iter()
                .map(|estimation| invert_estimation(&estimation, total))
                .collect_vec(),
            total,
        ),
    )
}

pub fn condition_converter<'a>(
    condition: &'a Condition,
    field_indexes: &'a IndexesMap,
    payload_provider: PayloadProvider,
    id_tracker: &IdTrackerSS,
) -> ConditionCheckerFn<'a> {
    match condition {
        Condition::Field(field_condition) => field_indexes
            .get(&field_condition.key)
            .and_then(|indexes| {
                indexes
                    .iter()
                    .find_map(|index| field_condition_index(index, field_condition))
            })
            .unwrap_or_else(|| {
                Box::new(move |point_id| {
                    payload_provider.with_payload(point_id, |payload| {
                        check_field_condition(field_condition, &payload, field_indexes)
                    })
                })
            }),
        // We can use index for `is_empty` condition effectively only when it is not empty.
        // If the index says it is "empty", we still need to check the payload.
        Condition::IsEmpty(is_empty) => {
            let first_field_index = field_indexes
                .get(&is_empty.is_empty.key)
                .and_then(|indexes| indexes.first());

            let fallback = Box::new(move |point_id| {
                payload_provider.with_payload(point_id, |payload| {
                    check_is_empty_condition(is_empty, &payload)
                })
            });

            match first_field_index {
                Some(index) => get_is_empty_checker(index, fallback),
                None => fallback,
            }
        }

        Condition::IsNull(is_null) => Box::new(move |point_id| {
            payload_provider.with_payload(point_id, |payload| {
                check_is_null_condition(is_null, &payload)
            })
        }),
        // ToDo: It might be possible to make this condition faster by using `VisitedPool` instead of HashSet
        Condition::HasId(has_id) => {
            let segment_ids: HashSet<_> = has_id
                .has_id
                .iter()
                .filter_map(|external_id| id_tracker.internal_id(*external_id))
                .collect();
            Box::new(move |point_id| segment_ids.contains(&point_id))
        }
        Condition::Nested(nested) => {
            // Select indexes for nested fields. Trim nested part from key, so
            // that nested condition can address fields without nested part.

            // Example:
            // Index for field `nested.field` will be stored under key `nested.field`
            // And we have a query:
            // {
            //   "nested": {
            //     "path": "nested",
            //     "filter": {
            //         ...
            //         "match": {"key": "field", "value": "value"}
            //     }
            //   }

            // In this case we want to use `nested.field`, but we only have `field` in query.
            // Therefore we need to trim `nested` part from key. So that query executor
            // can address proper index for nested field.
            let nested_path = nested.array_key();

            let nested_indexes = select_nested_indexes(&nested_path, field_indexes);

            Box::new(move |point_id| {
                payload_provider.with_payload(point_id, |payload| {
                    let field_values = payload.get_value(&nested_path).values();

                    for value in field_values {
                        if let Value::Object(object) = value {
                            let get_payload = || OwnedPayloadRef::from(object);
                            if check_payload(
                                Box::new(get_payload),
                                // None because has_id in nested is not supported. So retrieving
                                // IDs through the tracker would always return None.
                                None,
                                &nested.nested.filter,
                                point_id,
                                &nested_indexes,
                            ) {
                                // If at least one nested object matches, return true
                                return true;
                            }
                        }
                    }
                    false
                })
            })
        }
        Condition::Filter(_) => unreachable!(),
    }
}

pub fn field_condition_index<'a>(
    index: &'a FieldIndex,
    field_condition: &FieldCondition,
) -> Option<ConditionCheckerFn<'a>> {
    if let Some(checker) = field_condition
        .r#match
        .clone()
        .and_then(|cond| get_match_checkers(index, cond))
    {
        return Some(checker);
    }

    if let Some(checker) = field_condition
        .range
        .clone()
        .and_then(|cond| get_range_checkers(index, cond))
    {
        return Some(checker);
    }

    if let Some(checker) = field_condition
        .geo_radius
        .clone()
        .and_then(|cond| get_geo_radius_checkers(index, cond))
    {
        return Some(checker);
    }

    if let Some(checker) = field_condition
        .geo_bounding_box
        .clone()
        .and_then(|cond| get_geo_bounding_box_checkers(index, cond))
    {
        return Some(checker);
    }

    if let Some(checker) = field_condition
        .geo_polygon
        .clone()
        .and_then(|cond| get_geo_polygon_checkers(index, cond))
    {
        return Some(checker);
    }

    None
}

pub fn get_geo_polygon_checkers(
    index: &FieldIndex,
    geo_polygon: GeoPolygon,
) -> Option<ConditionCheckerFn> {
    let polygon_wrapper = geo_polygon.convert();
    match index {
        FieldIndex::GeoIndex(geo_index) => Some(Box::new(move |point_id: PointOffsetType| {
            geo_index.get_values(point_id).map_or(false, |values| {
                values
                    .iter()
                    .any(|geo_point| polygon_wrapper.check_point(geo_point))
            })
        })),
        _ => None,
    }
}

pub fn get_geo_radius_checkers(
    index: &FieldIndex,
    geo_radius: GeoRadius,
) -> Option<ConditionCheckerFn> {
    match index {
        FieldIndex::GeoIndex(geo_index) => Some(Box::new(move |point_id: PointOffsetType| {
            geo_index.get_values(point_id).map_or(false, |values| {
                values
                    .iter()
                    .any(|geo_point| geo_radius.check_point(geo_point))
            })
        })),
        _ => None,
    }
}

pub fn get_geo_bounding_box_checkers(
    index: &FieldIndex,
    geo_bounding_box: GeoBoundingBox,
) -> Option<ConditionCheckerFn> {
    match index {
        FieldIndex::GeoIndex(geo_index) => Some(Box::new(move |point_id: PointOffsetType| {
            match geo_index.get_values(point_id) {
                None => false,
                Some(values) => values
                    .iter()
                    .any(|geo_point| geo_bounding_box.check_point(geo_point)),
            }
        })),
        _ => None,
    }
}

pub fn get_range_checkers(index: &FieldIndex, range: Range) -> Option<ConditionCheckerFn> {
    match index {
        FieldIndex::IntIndex(num_index) => Some(Box::new(move |point_id: PointOffsetType| {
            num_index.get_values(point_id).map_or(false, |values| {
                values
                    .iter()
                    .copied()
                    .any(|i| range.check_range(i as FloatPayloadType))
            })
        })),
        FieldIndex::FloatIndex(num_index) => Some(Box::new(move |point_id: PointOffsetType| {
            num_index.get_values(point_id).map_or(false, |values| {
                values.iter().copied().any(|i| range.check_range(i))
            })
        })),
        _ => None,
    }
}

pub fn get_match_checkers(index: &FieldIndex, cond_match: Match) -> Option<ConditionCheckerFn> {
    match cond_match {
        Match::Value(MatchValue {
            value: value_variant,
        }) => match (value_variant, index) {
            (ValueVariants::Keyword(keyword), FieldIndex::KeywordIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index
                        .get_values(point_id)
                        .map_or(false, |values| values.iter().any(|k| k == &keyword))
                }))
            }
            (ValueVariants::Integer(value), FieldIndex::IntMapIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index
                        .get_values(point_id)
                        .map_or(false, |values| values.iter().any(|i| i == &value))
                }))
            }
            (ValueVariants::Bool(is_true), FieldIndex::BinaryIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    if is_true {
                        index.values_has_true(point_id)
                    } else {
                        index.values_has_false(point_id)
                    }
                }))
            }
            _ => None,
        },
        Match::Text(MatchText { text }) => match index {
            FieldIndex::FullTextIndex(full_text_index) => {
                let parsed_query = full_text_index.parse_query(&text);
                Some(Box::new(move |point_id: PointOffsetType| {
                    full_text_index
                        .get_doc(point_id)
                        .map_or(false, |doc| parsed_query.check_match(doc))
                }))
            }
            _ => None,
        },
        Match::Any(MatchAny { any }) => match (any, index) {
            (AnyVariants::Keywords(list), FieldIndex::KeywordIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index.get_values(point_id).map_or(false, |values| {
                        values
                            .iter()
                            .any(|k| list.iter().any(|s| s.as_str() == k.as_ref()))
                    })
                }))
            }
            (AnyVariants::Integers(list), FieldIndex::IntMapIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index
                        .get_values(point_id)
                        .map_or(false, |values| values.iter().any(|i| list.contains(i)))
                }))
            }
            _ => None,
        },
        Match::Except(MatchExcept { except }) => match (except, index) {
            (AnyVariants::Keywords(list), FieldIndex::KeywordIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index.get_values(point_id).map_or(false, |values| {
                        values
                            .iter()
                            .any(|k| !list.iter().any(|s| s.as_str() == k.as_ref()))
                    })
                }))
            }
            (AnyVariants::Integers(list), FieldIndex::IntMapIndex(index)) => {
                Some(Box::new(move |point_id: PointOffsetType| {
                    index
                        .get_values(point_id)
                        .map_or(false, |values| values.iter().any(|i| !list.contains(i)))
                }))
            }
            (_, index) => Some(Box::new(|point_id: PointOffsetType| {
                // If there is any other value of any other index, then it's a match
                index.values_count(point_id) > 0
            })),
        },
    }
}

/// Get a checker that checks if the field is empty
///
/// * `index` - index to check first
/// * `fallback` - Check if it is empty using plain payload
#[inline]
fn get_is_empty_checker<'a>(
    index: &'a FieldIndex,
    fallback: ConditionCheckerFn<'a>,
) -> ConditionCheckerFn<'a> {
    Box::new(move |point_id: PointOffsetType| {
        // Counting on the short-circuit of the `&&` operator
        // Only check the fallback if the index seems to be empty
        index.values_is_empty(point_id) && fallback(point_id)
    })
}

/// How many points do we need to check in order to estimate expected query cardinality.
/// Based on <https://en.wikipedia.org/wiki/Binomial_proportion_confidence_interval>
#[allow(dead_code)]
fn estimate_required_sample_size(total: usize, confidence_interval: usize) -> usize {
    let confidence_interval = min(confidence_interval, total);
    let z = 1.96; // percentile 0.95 of normal distribution
    let index_fraction = confidence_interval as f64 / total as f64 / 2.0;
    let h = 0.5; // success rate which requires most number of estimations
    let estimated_size = h * (1. - h) / (index_fraction / z).powi(2);
    max(estimated_size as usize, 10)
}

/// Returns (expected cardinality ± confidence interval at 0.99)
/// Based on <https://en.wikipedia.org/wiki/Binomial_proportion_confidence_interval#Agresti%E2%80%93Coull_interval>
fn confidence_agresti_coull_interval(trials: usize, positive: usize, total: usize) -> (i64, i64) {
    let z = 2.; // heuristics
    let n_hat = trials as f64 + z * z;
    let phat = (positive as f64 + z * z / 2.) / n_hat;
    let interval = z * ((phat / n_hat) * (1. - phat)).sqrt();

    let expected = (phat * total as f64) as i64;
    let delta = (interval * total as f64) as i64;
    (expected, delta)
}

/// Tests if given `query` have cardinality higher than the `threshold`
/// Iteratively samples points until the decision could be made with confidence
pub fn sample_check_cardinality(
    sample_points: impl Iterator<Item = PointOffsetType>,
    checker: impl Fn(PointOffsetType) -> bool,
    threshold: usize,
    total_points: usize,
) -> bool {
    let mut matched_points = 0;
    let mut total_checked = 0;

    let mut exp = 0;
    let mut interval;
    for idx in sample_points.take(MAX_ESTIMATED_POINTS) {
        matched_points += checker(idx) as usize;
        total_checked += 1;

        let estimation =
            confidence_agresti_coull_interval(total_checked, matched_points, total_points);
        exp = estimation.0;
        interval = estimation.1;

        if exp - interval > threshold as i64 {
            return true;
        }

        if exp + interval < threshold as i64 {
            return false;
        }
    }

    exp > threshold as i64
}

pub fn get_config_path(path: &Path) -> PathBuf {
    path.join(PAYLOAD_INDEX_CONFIG_FILE)
}

pub fn load(path: &Path) -> OperationResult<Self> {
    Ok(read_json(path)?)
}

pub fn save(&self, path: &Path) -> OperationResult<()> {
    Ok(atomic_save_json(path, self)?)
}

pub fn estimate_field_condition(
    &self,
    condition: &FieldCondition,
    nested_path: Option<&JsonPathPayload>,
) -> Option<CardinalityEstimation> {
    let full_path = JsonPathPayload::extend_or_new(nested_path, &condition.key);
    self.field_indexes.get(&full_path.path).and_then(|indexes| {
        // rewrite condition with fullpath to enable cardinality estimation
        let full_path_condition = FieldCondition {
            key: full_path.path,
            ..condition.clone()
        };

        indexes
            .iter()
            .find_map(|index| index.estimate_cardinality(&full_path_condition).ok())
    })
}

fn query_field<'a>(
    &'a self,
    field_condition: &'a FieldCondition,
) -> Option<Box<dyn Iterator<Item = PointOffsetType> + 'a>> {
    let indexes = self
        .field_indexes
        .get(&field_condition.key)
        .and_then(|indexes| {
            indexes
                .iter()
                .find_map(|field_index| field_index.filter(field_condition).ok())
        });
    indexes
}

fn config_path(&self) -> PathBuf {
    PayloadConfig::get_config_path(&self.path)
}

fn save_config(&self) -> OperationResult<()> {
    let config_path = self.config_path();
    self.config.save(&config_path)
}

fn load_all_fields(&mut self, is_appendable: bool) -> OperationResult<()> {
    let mut field_indexes: IndexesMap = Default::default();

    for (field, payload_schema) in &self.config.indexed_fields {
        let field_index = self.load_from_db(field, payload_schema.to_owned(), is_appendable)?;
        field_indexes.insert(field.clone(), field_index);
    }
    self.field_indexes = field_indexes;
    Ok(())
}

fn load_from_db(
    &self,
    field: PayloadKeyTypeRef,
    payload_schema: PayloadFieldSchema,
    is_appendable: bool,
) -> OperationResult<Vec<FieldIndex>> {
    let mut indexes = index_selector(field, &payload_schema, self.db.clone(), is_appendable);

    let mut is_loaded = true;
    for ref mut index in indexes.iter_mut() {
        if !index.load()? {
            is_loaded = false;
            break;
        }
    }
    if !is_loaded {
        debug!("Index for `{field}` was not loaded. Building...");
        // todo(ivan): decide what to do with indexes, which were not loaded
        indexes = self.build_field_indexes(field, payload_schema)?;
    }

    Ok(indexes)
}

pub fn open(
    payload: Arc<AtomicRefCell<PayloadStorageEnum>>,
    id_tracker: Arc<AtomicRefCell<IdTrackerSS>>,
    path: &Path,
    is_appendable: bool,
) -> OperationResult<Self> {
    create_dir_all(path)?;
    let config_path = PayloadConfig::get_config_path(path);
    let config = if config_path.exists() {
        PayloadConfig::load(&config_path)?
    } else {
        PayloadConfig::default()
    };

    let db = open_db_with_existing_cf(path)
        .map_err(|err| OperationError::service_error(format!("RocksDB open error: {err}")))?;

    let mut index = StructPayloadIndex {
        payload,
        id_tracker,
        field_indexes: Default::default(),
        config,
        path: path.to_owned(),
        visited_pool: Default::default(),
        db,
    };

    if !index.config_path().exists() {
        // Save default config
        index.save_config()?;
    }

    index.load_all_fields(is_appendable)?;

    Ok(index)
}

pub fn build_field_indexes(
    &self,
    field: PayloadKeyTypeRef,
    payload_schema: PayloadFieldSchema,
) -> OperationResult<Vec<FieldIndex>> {
    let payload_storage = self.payload.borrow();
    let mut field_indexes = index_selector(field, &payload_schema, self.db.clone(), true);
    for index in &field_indexes {
        index.recreate()?;
    }

    payload_storage.iter(|point_id, point_payload| {
        let field_value = &point_payload.get_value(field);
        for field_index in field_indexes.iter_mut() {
            field_index.add_point(point_id, field_value)?;
        }
        Ok(true)
    })?;
    Ok(field_indexes)
}

fn build_and_save(
    &mut self,
    field: PayloadKeyTypeRef,
    payload_schema: PayloadFieldSchema,
) -> OperationResult<()> {
    let field_indexes = self.build_field_indexes(field, payload_schema)?;
    self.field_indexes.insert(field.into(), field_indexes);
    Ok(())
}

/// Number of available points
///
/// - excludes soft deleted points
pub fn available_point_count(&self) -> usize {
    self.id_tracker.borrow().available_point_count()
}

fn struct_filtered_context<'a>(&'a self, filter: &'a Filter) -> StructFilterContext<'a> {
    let estimator = |condition: &Condition| self.condition_cardinality(condition, None);
    let id_tracker = self.id_tracker.borrow();
    let payload_provider = PayloadProvider::new(self.payload.clone());
    StructFilterContext::new(
        filter,
        id_tracker.deref(),
        payload_provider,
        &self.field_indexes,
        &estimator,
        self.available_point_count(),
    )
}

fn condition_cardinality(
    &self,
    condition: &Condition,
    nested_path: Option<&JsonPathPayload>,
) -> CardinalityEstimation {
    match condition {
        Condition::Filter(_) => panic!("Unexpected branching"),
        Condition::Nested(nested) => {
            // propagate complete nested path in case of multiple nested layers
            let full_path = JsonPathPayload::extend_or_new(nested_path, &nested.array_key());
            self.estimate_nested_cardinality(nested.filter(), &full_path)
        }
        Condition::IsEmpty(IsEmptyCondition { is_empty: field }) => {
            let available_points = self.available_point_count();
            let full_path = JsonPathPayload::extend_or_new(nested_path, &field.key);
            let full_path = full_path.path;

            let mut indexed_points = 0;
            if let Some(field_indexes) = self.field_indexes.get(&full_path) {
                for index in field_indexes {
                    indexed_points = indexed_points.max(index.count_indexed_points())
                }
                CardinalityEstimation {
                    primary_clauses: vec![PrimaryCondition::IsEmpty(IsEmptyCondition {
                        is_empty: PayloadField { key: full_path },
                    })],
                    min: 0, // It is possible, that some non-empty payloads are not indexed
                    exp: available_points.saturating_sub(indexed_points), // Expect field type consistency
                    max: available_points.saturating_sub(indexed_points),
                }
            } else {
                CardinalityEstimation {
                    primary_clauses: vec![PrimaryCondition::IsEmpty(IsEmptyCondition {
                        is_empty: PayloadField { key: full_path },
                    })],
                    min: 0,
                    exp: available_points / 2,
                    max: available_points,
                }
            }
        }
        Condition::IsNull(IsNullCondition { is_null: field }) => {
            let available_points = self.available_point_count();
            let full_path = JsonPathPayload::extend_or_new(nested_path, &field.key);
            let full_path = full_path.path;

            let mut indexed_points = 0;
            if let Some(field_indexes) = self.field_indexes.get(&full_path) {
                for index in field_indexes {
                    indexed_points = indexed_points.max(index.count_indexed_points())
                }
                CardinalityEstimation {
                    primary_clauses: vec![PrimaryCondition::IsNull(IsNullCondition {
                        is_null: PayloadField { key: full_path },
                    })],
                    min: 0,
                    exp: available_points.saturating_sub(indexed_points),
                    max: available_points.saturating_sub(indexed_points),
                }
            } else {
                CardinalityEstimation {
                    primary_clauses: vec![PrimaryCondition::IsNull(IsNullCondition {
                        is_null: PayloadField { key: full_path },
                    })],
                    min: 0,
                    exp: available_points / 2,
                    max: available_points,
                }
            }
        }
        Condition::HasId(has_id) => {
            let id_tracker_ref = self.id_tracker.borrow();
            let mapped_ids: HashSet<PointOffsetType> = has_id
                .has_id
                .iter()
                .filter_map(|external_id| id_tracker_ref.internal_id(*external_id))
                .collect();
            let num_ids = mapped_ids.len();
            CardinalityEstimation {
                primary_clauses: vec![PrimaryCondition::Ids(mapped_ids)],
                min: num_ids,
                exp: num_ids,
                max: num_ids,
            }
        }
        Condition::Field(field_condition) => self
            .estimate_field_condition(field_condition, nested_path)
            .unwrap_or_else(|| CardinalityEstimation::unknown(self.available_point_count())),
    }
}

pub fn get_telemetry_data(&self) -> Vec<PayloadIndexTelemetry> {
    self.field_indexes
        .iter()
        .flat_map(|(name, field)| -> Vec<PayloadIndexTelemetry> {
            field
                .iter()
                .map(|field| field.get_telemetry_data().set_name(name.to_string()))
                .collect()
        })
        .collect()
}

pub fn restore_database_snapshot(
    snapshot_path: &Path,
    segment_path: &Path,
