    crate::rocksdb_backup::restore(snapshot_path, &segment_path.join("payload_index"))
}

fn indexed_fields(&self) -> HashMap<PayloadKeyType, PayloadFieldSchema> {
    self.config.indexed_fields.clone()
}

fn set_indexed(
    &mut self,
    field: PayloadKeyTypeRef,
    payload_schema: PayloadFieldSchema,
) -> OperationResult<()> {
    if let Some(prev_schema) = self
        .config
        .indexed_fields
        .insert(field.to_owned(), payload_schema.clone())
    {
        // the field is already indexed with the same schema
        // no need to rebuild index and to save the config
        if prev_schema == payload_schema {
            return Ok(());
        }
    }
    self.build_and_save(field, payload_schema)?;
    self.save_config()?;

    Ok(())
}

fn drop_index(&mut self, field: PayloadKeyTypeRef) -> OperationResult<()> {
    self.config.indexed_fields.remove(field);
    let removed_indexes = self.field_indexes.remove(field);

    if let Some(indexes) = removed_indexes {
        for index in indexes {
            index.clear()?;
        }
    }

    self.save_config()?;
    Ok(())
}

fn estimate_cardinality(&self, query: &Filter) -> CardinalityEstimation {
    let available_points = self.available_point_count();
    let estimator = |condition: &Condition| self.condition_cardinality(condition, None);
    estimate_filter(&estimator, query, available_points)
}

fn estimate_nested_cardinality(
    &self,
    query: &Filter,
    nested_path: &JsonPathPayload,
) -> CardinalityEstimation {
    let available_points = self.available_point_count();
    let estimator =
        |condition: &Condition| self.condition_cardinality(condition, Some(nested_path));
    estimate_filter(&estimator, query, available_points)
}

fn query_points(&self, query: &Filter) -> Vec<PointOffsetType> {
    // Assume query is already estimated to be small enough so we can iterate over all matched ids

    let query_cardinality = self.estimate_cardinality(query);

    if query_cardinality.primary_clauses.is_empty() {
        let full_scan_iterator =
            ArcAtomicRefCellIterator::new(self.id_tracker.clone(), |points_iterator| {
                points_iterator.iter_ids()
            });

        let struct_filtered_context = self.struct_filtered_context(query);
        // Worst case: query expected to return few matches, but index can't be used
        let matched_points =
            full_scan_iterator.filter(move |i| struct_filtered_context.check(*i));

        matched_points.collect()
    } else {
        let points_iterator_ref = self.id_tracker.borrow();
        let struct_filtered_context = self.struct_filtered_context(query);

        // CPU-optimized strategy here: points are made unique before applying other filters.
        // TODO: Implement iterator which holds the `visited_pool` and borrowed `vector_storage_ref` to prevent `preselected` array creation
        let mut visited_list = self
            .visited_pool
            .get(points_iterator_ref.total_point_count());

        let preselected: Vec<PointOffsetType> = query_cardinality
            .primary_clauses
            .iter()
            .flat_map(|clause| {
                match clause {
                    PrimaryCondition::Condition(field_condition) => {
                        self.query_field(field_condition).unwrap_or_else(
                            || points_iterator_ref.iter_ids(), /* index is not built */
                        )
                    }
                    PrimaryCondition::Ids(ids) => Box::new(ids.iter().copied()),
                    PrimaryCondition::IsEmpty(_) => points_iterator_ref.iter_ids(), /* there are no fast index for IsEmpty */
                    PrimaryCondition::IsNull(_) => points_iterator_ref.iter_ids(),  /* no fast index for IsNull too */
                }
            })
            .filter(|&id| !visited_list.check_and_update_visited(id))
            .filter(move |&i| struct_filtered_context.check(i))
            .collect();
        preselected
    }
}

fn indexed_points(&self, field: PayloadKeyTypeRef) -> usize {
    self.field_indexes.get(field).map_or(0, |indexes| {
        // Assume that multiple field indexes are applied to the same data type,
        // so the points indexed with those indexes are the same.
        // We will return minimal number as a worst case, to highlight possible errors in the index early.
        indexes
            .iter()
            .map(|index| index.count_indexed_points())
            .min()
            .unwrap_or(0)
    })
}

fn filter_context<'a>(&'a self, filter: &'a Filter) -> Box<dyn FilterContext + 'a> {
    Box::new(self.struct_filtered_context(filter))
}

fn payload_blocks(
    &self,
    field: PayloadKeyTypeRef,
    threshold: usize,
) -> Box<dyn Iterator<Item = PayloadBlockCondition> + '_> {
    match self.field_indexes.get(field) {
        None => Box::new(vec![].into_iter()),
        Some(indexes) => {
            let field_clone = field.to_owned();
            Box::new(indexes.iter().flat_map(move |field_index| {
                field_index.payload_blocks(threshold, field_clone.clone())
            }))
        }
    }
}

fn assign(&mut self, point_id: PointOffsetType, payload: &Payload) -> OperationResult<()> {
    for (field, field_index) in &mut self.field_indexes {
        let field_value_opt = &payload.get_value_opt(field);
        if let Some(field_value) = field_value_opt {
            for index in field_index {
                index.add_point(point_id, field_value)?;
            }
        }
    }
    self.payload.borrow_mut().assign(point_id, payload)
}

fn payload(&self, point_id: PointOffsetType) -> OperationResult<Payload> {
    self.payload.borrow().payload(point_id)
}

fn delete(
    &mut self,
    point_id: PointOffsetType,
    key: PayloadKeyTypeRef,
) -> OperationResult<Vec<Value>> {
    if let Some(indexes) = self.field_indexes.get_mut(key) {
        for index in indexes {
            index.remove_point(point_id)?;
        }
    }
    self.payload.borrow_mut().delete(point_id, key)
}

fn drop(&mut self, point_id: PointOffsetType) -> OperationResult<Option<Payload>> {
    for (_, field_indexes) in self.field_indexes.iter_mut() {
        for index in field_indexes {
            index.remove_point(point_id)?;
        }
    }
    self.payload.borrow_mut().drop(point_id)
}

fn flusher(&self) -> Flusher {
    let mut flushers = Vec::new();
    for field_indexes in self.field_indexes.values() {
        for index in field_indexes {
            flushers.push(index.flusher());
        }
    }
    flushers.push(self.payload.borrow().flusher());
    Box::new(move || {
        for flusher in flushers {
            flusher()?
        }
        Ok(())
    })
}

fn infer_payload_type(
    &self,
    key: PayloadKeyTypeRef,
) -> OperationResult<Option<PayloadSchemaType>> {
    let mut schema = None;
    self.payload.borrow().iter(|_id, payload: &Payload| {
        let field_value = payload.get_value(key);
        match field_value {
            MultiValue::Single(field_value) => schema = field_value.and_then(infer_value_type),
            MultiValue::Multiple(fields_values) => {
                schema = infer_collection_value_type(fields_values)
            }
        }
        Ok(false)
    })?;
    Ok(schema)
}

fn take_database_snapshot(&self, path: &Path) -> OperationResult<()> {
    crate::rocksdb_backup::create(&self.db.read(), path)
}

fn files(&self) -> Vec<PathBuf> {
    vec![self.config_path()]
}

pub fn new<F>(
    filter: &'a Filter,
    id_tracker: &IdTrackerSS,
    payload_provider: PayloadProvider,
    field_indexes: &'a IndexesMap,
    estimator: &F,
    total: usize,
) -> Self
where
    F: Fn(&Condition) -> CardinalityEstimation,
{
    let (optimized_filter, _) = optimize_filter(
        filter,
        id_tracker,
        field_indexes,
        payload_provider,
        estimator,
        total,
    );

    Self { optimized_filter }
}

fn check(&self, point_id: PointOffsetType) -> bool {
    check_optimized_filter(&self.optimized_filter, point_id)
}

pub const fn exact(count: usize) -> Self {
    CardinalityEstimation {
        primary_clauses: vec![],
        min: count,
        exp: count,
        max: count,
    }
}

/// Generate estimation for unknown filter
pub const fn unknown(total: usize) -> Self {
    CardinalityEstimation {
        primary_clauses: vec![],
        min: 0,
        exp: total / 2,
        max: total,
    }
}

/// Push a primary clause to the estimation
pub fn with_primary_clause(mut self, clause: PrimaryCondition) -> Self {
    self.primary_clauses.push(clause);
    self
}

#[cfg(test)]
pub const fn equals_min_exp_max(&self, other: &Self) -> bool {
    self.min == other.min && self.exp == other.exp && self.max == other.max
}

fn new(db: Arc<RwLock<DB>>, field: &str) -> Self {
    let store_cf_name = GeoMapIndex::storage_cf_name(field);
    let db_wrapper = DatabaseColumnWrapper::new(db, &store_cf_name);
    Self {
        points_per_hash: Default::default(),
        values_per_hash: Default::default(),
        points_map: Default::default(),
        point_to_values: vec![],
        points_count: 0,
        points_values_count: 0,
        max_values_per_point: 0,
        db_wrapper,
    }
}

fn db_wrapper(&self) -> &DatabaseColumnWrapper {
    &self.db_wrapper
}

fn get_values(&self, idx: PointOffsetType) -> Option<&[GeoPoint]> {
    self.point_to_values.get(idx as usize).map(Vec::as_slice)
}

fn get_points_per_hash(&self) -> impl Iterator<Item = (&GeoHash, usize)> {
    self.points_per_hash
        .iter()
        .map(|(hash, count)| (hash, *count))
}

fn get_points_of_hash(&self, hash: &GeoHash) -> usize {
    self.points_per_hash.get(hash).cloned().unwrap_or(0)
}

fn get_values_of_hash(&self, hash: &GeoHash) -> usize {
    self.values_per_hash.get(hash).cloned().unwrap_or(0)
}

fn load(&mut self) -> OperationResult<bool> {
    if !self.db_wrapper.has_column_family()? {
        return Ok(false);
    };

    let mut points_to_hashes: BTreeMap<PointOffsetType, Vec<GeoHash>> = Default::default();

    for (key, value) in self.db_wrapper.lock_db().iter()? {
        let key_str = std::str::from_utf8(&key).map_err(|_| {
            OperationError::service_error("Index load error: UTF8 error while DB parsing")
        })?;

        let (geo_hash, idx) = GeoMapIndex::decode_db_key(key_str)?;
        let geo_point = GeoMapIndex::decode_db_value(value)?;

        if self.point_to_values.len() <= idx as usize {
            self.point_to_values.resize_with(idx as usize + 1, Vec::new);
        }

        if self.point_to_values[idx as usize].is_empty() {
            self.points_count += 1;
        }

        points_to_hashes
            .entry(idx)
            .or_default()
            .push(geo_hash.clone());

        self.point_to_values[idx as usize].push(geo_point);
        self.points_map
            .entry(geo_hash.clone())
            .or_default()
            .insert(idx);

        self.points_values_count += 1;
    }

    for (_idx, geo_hashes) in points_to_hashes.into_iter() {
        self.max_values_per_point = max(self.max_values_per_point, geo_hashes.len());
        self.increment_hash_point_counts(&geo_hashes);
        for geo_hash in geo_hashes {
            self.increment_hash_value_counts(&geo_hash);
        }
    }
    Ok(true)
}

fn remove_point(&mut self, idx: PointOffsetType) -> OperationResult<()> {
    if self.point_to_values.len() <= idx as usize {
        return Ok(()); // Already removed or never actually existed
    }

    let removed_geo_points = std::mem::take(&mut self.point_to_values[idx as usize]);

    if removed_geo_points.is_empty() {
        return Ok(());
    }

    self.points_count -= 1;
    self.points_values_count -= removed_geo_points.len();
    let mut removed_geo_hashes = Vec::with_capacity(removed_geo_points.len());

    for removed_geo_point in removed_geo_points {
        let removed_geo_hash: GeoHash =
            encode_max_precision(removed_geo_point.lon, removed_geo_point.lat).unwrap();
        removed_geo_hashes.push(removed_geo_hash.clone());

        let key = GeoMapIndex::encode_db_key(&removed_geo_hash, idx);
        self.db_wrapper.remove(key)?;

        let is_last = if let Some(hash_ids) = self.points_map.get_mut(&removed_geo_hash) {
            hash_ids.remove(&idx);
            hash_ids.is_empty()
        } else {
            log::warn!(
                "Geo index error: no points for hash {} was found",
                removed_geo_hash
            );
            false
        };

        if is_last {
            self.points_map.remove(&removed_geo_hash);
        }

        self.decrement_hash_value_counts(&removed_geo_hash);
    }

    self.decrement_hash_point_counts(&removed_geo_hashes);
    Ok(())
}

fn add_many_geo_points(
    &mut self,
    idx: PointOffsetType,
    values: &[GeoPoint],
) -> OperationResult<()> {
    if values.is_empty() {
        return Ok(());
    }

    if self.point_to_values.len() <= idx as usize {
        // That's a smart reallocation
        self.point_to_values.resize_with(idx as usize + 1, Vec::new);
    }

    self.point_to_values[idx as usize] = values.to_vec();

    let mut geo_hashes = vec![];

    for added_point in values {
        let added_geo_hash: GeoHash = encode_max_precision(added_point.lon, added_point.lat)
            .map_err(|e| OperationError::service_error(format!("Malformed geo points: {e}")))?;

        let key = GeoMapIndex::encode_db_key(&added_geo_hash, idx);
        let value = GeoMapIndex::encode_db_value(added_point);

        geo_hashes.push(added_geo_hash);

        self.db_wrapper.put(key, value)?;
    }

    for geo_hash in &geo_hashes {
        self.points_map
            .entry(geo_hash.to_owned())
            .or_default()
            .insert(idx);

        self.increment_hash_value_counts(geo_hash);
    }

    self.increment_hash_point_counts(&geo_hashes);

    self.points_values_count += values.len();
    self.points_count += 1;
    self.max_values_per_point = self.max_values_per_point.max(values.len());
    Ok(())
}

fn get_stored_sub_regions(
    &self,
    geo: &GeoHash,
) -> Box<dyn Iterator<Item = (&GeoHash, &HashSet<PointOffsetType>)> + '_> {
    let geo_clone = geo.clone();
    Box::new(
        self.points_map
            .range(geo.clone()..)
            .take_while(move |(p, _h)| p.starts_with(geo_clone.as_str())),
    )
}

fn increment_hash_value_counts(&mut self, geo_hash: &GeoHash) {
    for i in 0..=geo_hash.len() {
        let sub_geo_hash = &geo_hash[0..i];
        match self.values_per_hash.get_mut(sub_geo_hash) {
            None => {
                self.values_per_hash.insert(sub_geo_hash.into(), 1);
            }
            Some(count) => {
                *count += 1;
            }
        };
    }
}

fn increment_hash_point_counts(&mut self, geo_hashes: &[GeoHash]) {
    let mut seen_hashes: HashSet<&str> = Default::default();

    for geo_hash in geo_hashes {
        for i in 0..=geo_hash.len() {
            let sub_geo_hash = &geo_hash[0..i];
            if seen_hashes.contains(sub_geo_hash) {
                continue;
            }
            seen_hashes.insert(sub_geo_hash);
            match self.points_per_hash.get_mut(sub_geo_hash) {
                None => {
                    self.points_per_hash.insert(sub_geo_hash.into(), 1);
                }
                Some(count) => {
                    *count += 1;
                }
            };
        }
    }
}

fn decrement_hash_value_counts(&mut self, geo_hash: &GeoHash) {
    for i in 0..=geo_hash.len() {
        let sub_geo_hash = &geo_hash[0..i];
        match self.values_per_hash.get_mut(sub_geo_hash) {
            None => {
                debug_assert!(
                    false,
                    "Hash value count is not found for hash: {}",
                    sub_geo_hash
                );
                self.values_per_hash.insert(sub_geo_hash.into(), 0);
            }
            Some(count) => {
                *count -= 1;
            }
        };
    }
}

fn decrement_hash_point_counts(&mut self, geo_hashes: &[GeoHash]) {
    let mut seen_hashes: HashSet<&str> = Default::default();
    for geo_hash in geo_hashes {
        for i in 0..=geo_hash.len() {
            let sub_geo_hash = &geo_hash[0..i];
            if seen_hashes.contains(sub_geo_hash) {
                continue;
            }
            seen_hashes.insert(sub_geo_hash);
            match self.points_per_hash.get_mut(sub_geo_hash) {
                None => {
                    debug_assert!(
                        false,
                        "Hash point count is not found for hash: {}",
                        sub_geo_hash
                    );
                    self.points_per_hash.insert(sub_geo_hash.into(), 0);
                }
                Some(count) => {
                    *count -= 1;
                }
            };
        }
    }
}

