fn from(point: GeoPoint) -> Self {
    Self {
        x: point.lat,
        y: point.lon,
    }
}

pub fn common_hash_prefix(geo_hashes: &[GeoHash]) -> GeoHash {
    let first = &geo_hashes[0];
    let mut prefix: usize = first.len();
    for geo_hash in geo_hashes.iter().skip(1) {
        for i in 0..prefix {
            if first.as_bytes()[i] != geo_hash.as_bytes()[i] {
                prefix = i;
                break;
            }
        }
    }
    first[0..prefix].into()
}

/// Fix longitude for spherical overflow
/// lon: 181.0 -> -179.0
fn sphere_lon(lon: f64) -> f64 {
    let mut res_lon = lon;
    if res_lon > LON_RANGE.end {
        res_lon = LON_RANGE.start + res_lon - LON_RANGE.end;
    }
    if res_lon < LON_RANGE.start {
        res_lon = LON_RANGE.end + res_lon - LON_RANGE.start;
    }
    res_lon
}

/// Fix latitude for spherical overflow
fn sphere_lat(lat: f64) -> f64 {
    let mut res_lat = lat;
    if res_lat > LAT_RANGE.end {
        res_lat = LAT_RANGE.end - COORD_EPS;
    }
    if res_lat < LAT_RANGE.start {
        res_lat = LAT_RANGE.start + COORD_EPS;
    }
    res_lat
}

/// Get neighbour geohash even from the other side of coordinates
fn sphere_neighbor(hash_str: &str, direction: Direction) -> Result<GeoHash, GeohashError> {
    let (coord, lon_err, lat_err) = decode(hash_str)?;
    let (dlat, dlng) = direction.to_tuple();
    let lon = sphere_lon(coord.x + 2f64 * lon_err.abs() * dlng);
    let lat = sphere_lat(coord.y + 2f64 * lat_err.abs() * dlat);

    let neighbor_coord = Coord { x: lon, y: lat };
    encode(neighbor_coord, hash_str.len()).map(Into::into)
}

pub fn encode_max_precision(lon: f64, lat: f64) -> Result<GeoHash, GeohashError> {
    encode((lon, lat).into(), GEOHASH_MAX_LENGTH).map(Into::into)
}

pub fn geo_hash_to_box(geo_hash: &GeoHash) -> GeoBoundingBox {
    let rectangle = decode_bbox(geo_hash).unwrap();
    let top_left = GeoPoint {
        lon: rectangle.min().x,
        lat: rectangle.max().y,
    };
    let bottom_right = GeoPoint {
        lon: rectangle.max().x,
        lat: rectangle.min().y,
    };

    GeoBoundingBox {
        top_left,
        bottom_right,
    }
}

/// Calculate geo-hashes covering the rectangular region with given precision
///
/// # Arguments
///
/// * `precision` - precision of cover
/// * `max_regions` - stop early if maximal amount of regions exceeded
///
/// # Result
///
/// * None - if there are more regions than a limit
/// * Some(list of geo-hashes covering the region
///
fn geohash_regions(&self, precision: usize, max_regions: usize) -> Option<Vec<GeoHash>> {
    let mut seen: Vec<GeoHash> = Vec::new();

    let mut from_row: GeoHash = self.north_west[..precision].into();
    let mut to_row: GeoHash = self.north_east[..precision].into();

    let to_column = self.south_west[..precision].to_owned();

    loop {
        let mut current = from_row.clone();
        loop {
            seen.push(current.clone());

            if seen.len() > max_regions {
                return None;
            }

            if current == to_row {
                break;
            }
            current = sphere_neighbor(current.as_str(), Direction::E).unwrap();
        }
        if from_row == to_column {
            break;
        }

        from_row = sphere_neighbor(&from_row, Direction::S).unwrap();
        to_row = sphere_neighbor(&to_row, Direction::S).unwrap();
    }

    Some(seen)
}

fn from(bounding_box: GeoBoundingBox) -> Self {
    let GeoPoint {
        lat: max_lat,
        lon: min_lon,
    } = bounding_box.top_left;
    let GeoPoint {
        lat: min_lat,
        lon: max_lon,
    } = bounding_box.bottom_right;

    // Unwrap is acceptable, as data should be validated before
    let north_west = encode_max_precision(min_lon, max_lat).unwrap();
    let south_west = encode_max_precision(min_lon, min_lat).unwrap();
    let south_east = encode_max_precision(max_lon, min_lat).unwrap();
    let north_east = encode_max_precision(max_lon, max_lat).unwrap();

    Self {
        north_west,
        south_west,
        south_east,
        north_east,
    }
}

/// Check if geohash tile intersects the circle
fn check_circle_intersection(geohash: &str, circle: &GeoRadius) -> bool {
    let precision = geohash.len();
    if precision == 0 {
        return true;
    }
    let rect = decode_bbox(geohash).unwrap();
    let c0 = rect.min();
    let c1 = rect.max();

    let bbox_center = Point::new((c0.x + c1.x) / 2f64, (c0.y + c1.y) / 2f64);
    let half_diagonal = bbox_center.haversine_distance(&Point(c0));

    half_diagonal + circle.radius
        > bbox_center.haversine_distance(&Point::new(circle.center.lon, circle.center.lat))
}

/// Check if geohash tile intersects the polygon
fn check_polygon_intersection(geohash: &str, polygon: &Polygon) -> bool {
    let precision = geohash.len();
    if precision == 0 {
        return true;
    }
    let rect = decode_bbox(geohash).unwrap();

    rect.intersects(polygon)
}

fn create_hashes(
    mapping_fn: impl Fn(usize) -> Option<Vec<GeoHash>>,
) -> OperationResult<Vec<GeoHash>> {
    (0..=GEOHASH_MAX_LENGTH)
        .map(mapping_fn)
        .take_while(|hashes| hashes.is_some())
        .last()
        .ok_or_else(|| OperationError::service_error("no hash coverage for any precision"))?
        .ok_or_else(|| OperationError::service_error("geo-hash coverage is empty"))
}

/// Return as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain the whole circle.
pub fn circle_hashes(circle: &GeoRadius, max_regions: usize) -> OperationResult<Vec<GeoHash>> {
    if max_regions == 0 {
        return Err(OperationError::service_error(
            "max_regions cannot be equal to zero",
        ));
    }

    let geo_bounding_box = minimum_bounding_rectangle_for_circle(circle);
    let full_geohash_bounding_box: GeohashBoundingBox = geo_bounding_box.into();

    let mapping_fn = |precision| {
        full_geohash_bounding_box
            .geohash_regions(precision, max_regions)
            .map(|hashes| {
                hashes
                    .into_iter()
                    .filter(|hash| check_circle_intersection(hash, circle))
                    .collect_vec()
            })
    };
    create_hashes(mapping_fn)
}

/// Return as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain the whole rectangle.
pub fn rectangle_hashes(
    rectangle: &GeoBoundingBox,
    max_regions: usize,
) -> OperationResult<Vec<GeoHash>> {
    if max_regions == 0 {
        return Err(OperationError::service_error(
            "max_regions cannot be equal to zero",
        ));
    }
    let full_geohash_bounding_box: GeohashBoundingBox = rectangle.clone().into();

    let mapping_fn = |precision| full_geohash_bounding_box.geohash_regions(precision, max_regions);
    create_hashes(mapping_fn)
}

/// Return as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain a boundary defined by closed LineString.
fn boundary_hashes(boundary: &LineString, max_regions: usize) -> OperationResult<Vec<GeoHash>> {
    let geo_bounding_box = minimum_bounding_rectangle_for_boundary(boundary);
    let full_geohash_bounding_box: GeohashBoundingBox = geo_bounding_box.into();
    let polygon = Polygon::new(boundary.clone(), vec![]);

    let mapping_fn = |precision| {
        full_geohash_bounding_box
            .geohash_regions(precision, max_regions)
            .map(|hashes| {
                hashes
                    .into_iter()
                    .filter(|hash| check_polygon_intersection(hash, &polygon))
                    .collect_vec()
            })
    };
    create_hashes(mapping_fn)
}

/// A function used for cardinality estimation
/// The first return value is as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain the polygon's exterior.
/// The second return value is all as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain each polygon's interior.
pub fn polygon_hashes_estimation(
    polygon: &GeoPolygon,
    max_regions: usize,
) -> (Vec<GeoHash>, Vec<Vec<GeoHash>>) {
    assert_ne!(max_regions, 0, "max_regions cannot be equal to zero");
    let polygon_wrapper = polygon.convert().polygon;
    let exterior_hashes = boundary_hashes(&polygon_wrapper.exterior().clone(), max_regions);
    let interiors_hashes = polygon_wrapper
        .interiors()
        .iter()
        .map(|interior| boundary_hashes(interior, max_regions).unwrap())
        .collect_vec();

    (exterior_hashes.unwrap(), interiors_hashes)
}

/// Return as-high-as-possible with maximum of `max_regions`
/// number of geo-hash guaranteed to contain the whole polygon.
pub fn polygon_hashes(polygon: &GeoPolygon, max_regions: usize) -> OperationResult<Vec<GeoHash>> {
    if max_regions == 0 {
        return Err(OperationError::service_error(
            "max_regions cannot be equal to zero",
        ));
    }
    let polygon_wrapper = polygon.convert().polygon;
    let geo_bounding_box = minimum_bounding_rectangle_for_boundary(polygon_wrapper.exterior());
    let full_geohash_bounding_box: GeohashBoundingBox = geo_bounding_box.into();

    let mapping_fn = |precision| {
        full_geohash_bounding_box
            .geohash_regions(precision, max_regions)
            .map(|hashes| {
                hashes
                    .into_iter()
                    .filter(|hash| check_polygon_intersection(hash, &polygon_wrapper))
                    .collect_vec()
            })
    };
    create_hashes(mapping_fn)
}

/// Returns the GeoBoundingBox that defines the MBR
/// <http://janmatuschek.de/LatitudeLongitudeBoundingCoordinates#Longitude>
fn minimum_bounding_rectangle_for_circle(circle: &GeoRadius) -> GeoBoundingBox {
    // circle.radius is in meter
    let angular_radius: f64 = circle.radius / EARTH_RADIUS_METERS;

    let angular_lat = circle.center.lat.to_radians();
    let mut min_lat = (angular_lat - angular_radius).to_degrees();
    let mut max_lat = (angular_lat + angular_radius).to_degrees();

    let (min_lon, max_lon) = if LAT_RANGE.start < min_lat && max_lat < LAT_RANGE.end {
        // Poles are not within the query, default scenario
        let angular_lon = circle.center.lon.to_radians();
        let delta_lon = (angular_radius.sin() / angular_lat.cos()).asin();

        let min_lon = (angular_lon - delta_lon).to_degrees();
        let max_lon = (angular_lon + delta_lon).to_degrees();

        (min_lon, max_lon)
    } else {
        // poles are within circle - use whole cup
        if LAT_RANGE.start > min_lat {
            min_lat = LAT_RANGE.start + COORD_EPS;
        }
        if max_lat > LAT_RANGE.end {
            max_lat = LAT_RANGE.end - COORD_EPS;
        }

        (LON_RANGE.start + COORD_EPS, LON_RANGE.end - COORD_EPS)
    };

    let top_left = GeoPoint {
        lat: max_lat,
        lon: sphere_lon(min_lon),
    };
    let bottom_right = GeoPoint {
        lat: min_lat,
        lon: sphere_lon(max_lon),
    };

    GeoBoundingBox {
        top_left,
        bottom_right,
    }
}

fn minimum_bounding_rectangle_for_boundary(boundary: &LineString) -> GeoBoundingBox {
    let mut min_lon = f64::MAX;
    let mut max_lon = f64::MIN;
    let mut min_lat = f64::MAX;
    let mut max_lat = f64::MIN;

    for point in boundary.coords() {
        if point.x < min_lon {
            min_lon = point.x;
        }
        if point.x > max_lon {
            max_lon = point.x;
        }
        if point.y < min_lat {
            min_lat = point.y;
        }
        if point.y > max_lat {
            max_lat = point.y;
        }
    }

    let top_left = GeoPoint {
        lon: min_lon,
        lat: max_lat,
    };
    let bottom_right = GeoPoint {
        lon: max_lon,
        lat: min_lat,
    };

    GeoBoundingBox {
        top_left,
        bottom_right,
    }
}

/// This function estimates how many real points were selected with the filter.
/// It is assumed that each real point has, on average, X values in correspondence. As a response
/// to the execution of the query it is possible to establish only the number of matched associated
/// values.
///
/// # Arguments
///
/// * `total_points` - total number of the unique points in the whole collection
/// * `total_values` - total number of payload values in the collection
/// * `selected_values_count` - amount of values selected during the query
///
/// # Result
///
/// Expected amount of unique points contained in selected values
/// The result might overflow at some corner cases
///   so it is better to limit its value with min and max
///
pub fn estimate_multi_value_selection_cardinality(
    total_points: usize,
    total_values: usize,
    selected_values_count: usize,
) -> f64 {
    // Value >= 1.0
    assert!(total_values >= total_points);
    let values_per_point = total_values as f64 / total_points as f64;
    // Probability to select each unique value
    let prob_select = 1. - prob_not_select(total_values, values_per_point, selected_values_count);
    prob_select * total_points as f64
}

/// Fast approximate computation of $ln(n!)$
/// See: <https://en.wikipedia.org/wiki/Stirling%27s_approximation>
fn approx_fact_log(n: f64) -> f64 {
    if n < 1.0 {
        return 1.0; // By definition
    }
    (2. * PI * n).sqrt().ln() + n * (n / E).ln()
}

/// Probability of each individual unique point to be selected with the query
///
/// Straight equation:
///     $\prod_{i=0}^{N-1} \frac{total - avg - i}{total - i}$
/// , where `N` - number of selected points
///
/// Proof:
///
/// $$
/// \prod_{i=0}^{N-1} \frac{total - avg - i}{total - i}
///     = \frac{\prod_{i=0}^{N-1} (total - avg - i)}{\prod_{i=0}^{N-1}(total - i)}
///     = \frac{\prod_{i=1}^{N} (total - avg - i + 1)}{\prod_{i=1}^{N}(total - i + 1)}\\
///     = \frac{\prod_{i=1}^{N} (total - avg - (N - i + 1) + 1)}{\prod_{i=1}^{N}(total - (N - i + 1) + 1)}
///     = \frac{\prod_{i=1}^{N} (i + total - avg - N)}{\prod_{i=1}^{N}(i + total - N)}\\
///     = \frac{\prod_{i=1}^{total - avg} i}{\prod_{i=1}^{total - avg - N} i} \frac{\prod_{i=1}^{total - N} i}{\prod_{i=1}^{total} i}
///     = \frac{(total - avg)!(total - N)!}{(total - avg - N)!(total)!}
///     = \exp(\ln{\frac{(total - avg)!(total - N)!}{(total - avg - N)!(total)!}})\\
///     = \exp(\ln((total - avg)!(total - N)!) - \ln((total - avg - N)!(total)!))
///     = \exp( \ln((total - avg)!) + \ln((total - N)!) - \ln((total - avg - N)!) - \ln(total!))
/// $$
///
/// Hint: use <https://latex.codecogs.com/eqneditor/editor.php> to render formula
fn prob_not_select(total: usize, avg: f64, selected: usize) -> f64 {
    let total = total as f64;
    let selected = selected as f64;
    (approx_fact_log(total - avg) + approx_fact_log(total - selected)
        - approx_fact_log(total - avg - selected)
        - approx_fact_log(total))
    .exp()
}

/// Calculate number of selected points, based on the amount of matched values.
/// Assuming that values are randomly distributed among points and each point can have multiple values.
/// Math is based on: <https://en.wikipedia.org/wiki/Bloom_filter#Probability_of_false_positives>
pub fn number_of_selected_points(points: usize, values: usize) -> usize {
    let prob_of_selection = 1. - (-(values as f64 / points as f64)).exp();
    (prob_of_selection * points as f64).round() as usize
}

/// Selects index types based on field type
pub fn index_selector(
    field: &str,
    payload_schema: &PayloadFieldSchema,
    db: Arc<RwLock<DB>>,
    is_appendable: bool,
) -> Vec<FieldIndex> {
    match payload_schema {
        PayloadFieldSchema::FieldType(payload_type) => match payload_type {
            PayloadSchemaType::Keyword => {
                vec![FieldIndex::KeywordIndex(MapIndex::new(
                    db,
                    field,
                    is_appendable,
                ))]
            }
            PayloadSchemaType::Integer => vec![
                FieldIndex::IntMapIndex(MapIndex::new(db.clone(), field, is_appendable)),
                FieldIndex::IntIndex(NumericIndex::<IntPayloadType>::new(
                    db,
                    field,
                    is_appendable,
                )),
            ],
            PayloadSchemaType::Float => {
                vec![FieldIndex::FloatIndex(
                    NumericIndex::<FloatPayloadType>::new(db, field, is_appendable),
                )]
            }
            PayloadSchemaType::Geo => vec![FieldIndex::GeoIndex(GeoMapIndex::new(db, field))],
            PayloadSchemaType::Text => vec![FieldIndex::FullTextIndex(FullTextIndex::new(
                db,
                Default::default(),
                field,
            ))],
            PayloadSchemaType::Bool => vec![FieldIndex::BinaryIndex(BinaryIndex::new(db, field))],
        },
        PayloadFieldSchema::FieldParams(payload_params) => match payload_params {
            PayloadSchemaParams::Text(text_index_params) => vec![FieldIndex::FullTextIndex(
                FullTextIndex::new(db, text_index_params.clone(), field),
            )],
        },
    }
}

fn store_key(id: &PointOffsetType) -> Vec<u8> {
    bincode::serialize(&id).unwrap()
}

fn restore_key(data: &[u8]) -> PointOffsetType {
    bincode::deserialize(data).unwrap()
}

fn serialize_document_tokens(&self, tokens: BTreeSet<String>) -> OperationResult<Vec<u8>> {
    #[derive(Serialize)]
    struct StoredDocument {
        tokens: BTreeSet<String>,
    }
    let doc = StoredDocument { tokens };
    serde_cbor::to_vec(&doc).map_err(|e| {
        OperationError::service_error(format!("Failed to serialize document: {e}"))
    })
}

fn deserialize_document(data: &[u8], index: &mut InvertedIndex) -> OperationResult<Document> {
    #[derive(Deserialize)]
    struct StoredDocument {
        tokens: BTreeSet<String>,
    }
    serde_cbor::from_slice::<StoredDocument>(data)
        .map_err(|e| {
            OperationError::service_error(format!("Failed to deserialize document: {e}"))
        })
        .map(|doc| index.document_from_tokens(&doc.tokens))
}

fn storage_cf_name(field: &str) -> String {
    format!("{field}_fts")
}

pub fn new(db: Arc<RwLock<DB>>, config: TextIndexParams, field: &str) -> Self {
    let store_cf_name = Self::storage_cf_name(field);
    let db_wrapper = DatabaseColumnWrapper::new(db, &store_cf_name);
    FullTextIndex {
        inverted_index: InvertedIndex::new(),
        db_wrapper,
        config,
    }
}

pub fn get_doc(&self, idx: PointOffsetType) -> Option<&Document> {
    match self.inverted_index.point_to_docs.get(idx as usize) {
        Some(Some(doc)) => Some(doc),
        _ => None,
    }
}

pub fn get_telemetry_data(&self) -> PayloadIndexTelemetry {
    PayloadIndexTelemetry {
        field_name: None,
        points_values_count: self.inverted_index.points_count,
        points_count: self.inverted_index.points_count,
        histogram_bucket_size: None,
    }
}

pub fn recreate(&self) -> OperationResult<()> {
    self.db_wrapper.recreate_column_family()
}

pub fn parse_query(&self, text: &str) -> ParsedQuery {
    let mut tokens = HashSet::new();
    Tokenizer::tokenize_query(text, &self.config, |token| {
        tokens.insert(self.inverted_index.vocab.get(token).copied());
    });
    ParsedQuery {
        tokens: tokens.into_iter().collect(),
    }
}

pub fn parse_document(&self, text: &str) -> Document {
    let mut document_tokens = vec![];
    Tokenizer::tokenize_doc(text, &self.config, |token| {
        if let Some(token_id) = self.inverted_index.vocab.get(token) {
            document_tokens.push(*token_id);
        }
    });
    Document::new(document_tokens)
}

#[cfg(test)]
pub fn query(&self, query: &str) -> Box<dyn Iterator<Item = PointOffsetType> + '_> {
    let parsed_query = self.parse_query(query);
    self.inverted_index.filter(&parsed_query)
}

pub fn values_count(&self, point_id: PointOffsetType) -> usize {
    // Maybe we want number of documents in the future?
    self.get_doc(point_id).map(|x| x.len()).unwrap_or(0)
}

pub fn values_is_empty(&self, point_id: PointOffsetType) -> bool {
    self.get_doc(point_id).map(|x| x.is_empty()).unwrap_or(true)
}

fn add_many(&mut self, idx: PointOffsetType, values: Vec<String>) -> OperationResult<()> {
    if values.is_empty() {
        return Ok(());
    }

    let mut tokens: BTreeSet<String> = BTreeSet::new();

    for value in values {
        Tokenizer::tokenize_doc(&value, &self.config, |token| {
            tokens.insert(token.to_owned());
        });
    }

    let document = self.inverted_index.document_from_tokens(&tokens);
    self.inverted_index.index_document(idx, document);

    let db_idx = Self::store_key(&idx);
    let db_document = self.serialize_document_tokens(tokens)?;

    self.db_wrapper.put(db_idx, db_document)?;

    Ok(())
}

fn get_value(&self, value: &Value) -> Option<String> {
    if let Value::String(keyword) = value {
        return Some(keyword.to_owned());
    }
    None
}

fn remove_point(&mut self, id: PointOffsetType) -> OperationResult<()> {
    let removed_doc = self.inverted_index.remove_document(id);

    if removed_doc.is_none() {
        return Ok(());
    }

    let db_doc_id = Self::store_key(&id);
    self.db_wrapper.remove(db_doc_id)?;

    Ok(())
}

fn count_indexed_points(&self) -> usize {
    self.inverted_index.points_count
}

fn load(&mut self) -> OperationResult<bool> {
    if !self.db_wrapper.has_column_family()? {
        return Ok(false);
    };

    for (key, value) in self.db_wrapper.lock_db().iter()? {
        let idx = Self::restore_key(&key);
        let document = Self::deserialize_document(&value, &mut self.inverted_index)?;
        self.inverted_index.index_document(idx, document);
    }
    Ok(true)
}

fn clear(self) -> OperationResult<()> {
    self.db_wrapper.remove_column_family()
}

fn flusher(&self) -> Flusher {
    self.db_wrapper.flusher()
}

fn filter(
    &self,
    condition: &FieldCondition,
) -> OperationResult<Box<dyn Iterator<Item = PointOffsetType> + '_>> {
    if let Some(Match::Text(text_match)) = &condition.r#match {
        let parsed_query = self.parse_query(&text_match.text);
        return Ok(self.inverted_index.filter(&parsed_query));
    }
    Err(OperationError::service_error("failed to filter"))
}

fn estimate_cardinality(
    &self,
    condition: &FieldCondition,
) -> OperationResult<CardinalityEstimation> {
    if let Some(Match::Text(text_match)) = &condition.r#match {
        let parsed_query = self.parse_query(&text_match.text);
        return Ok(self
            .inverted_index
            .estimate_cardinality(&parsed_query, condition));
    }
    Err(OperationError::service_error(
        "failed to estimate cardinality",
    ))
}

fn payload_blocks(
    &self,
    threshold: usize,
    key: PayloadKeyType,
) -> Box<dyn Iterator<Item = PayloadBlockCondition> + '_> {
    self.inverted_index.payload_blocks(threshold, key)
}

pub fn new(mut tokens: Vec<TokenId>) -> Self {
    tokens.sort_unstable();
    Self { tokens }
}

pub fn len(&self) -> usize {
    self.tokens.len()
}

pub fn is_empty(&self) -> bool {
    self.tokens.is_empty()
}

pub fn tokens(&self) -> &[TokenId] {
    &self.tokens
}

pub fn check(&self, token: TokenId) -> bool {
    self.tokens.binary_search(&token).is_ok()
}

pub fn check_match(&self, document: &Document) -> bool {
    if self.tokens.contains(&None) {
        return false;
    }
    // Check that all tokens are in document
    self.tokens
        .iter()
        // unwrap crash safety: all tokens exist in the vocabulary if it passes the above check
        .all(|query_token| document.check(query_token.unwrap()))
}

pub fn new() -> InvertedIndex {
    Default::default()
}

pub fn document_from_tokens(&mut self, tokens: &BTreeSet<String>) -> Document {
    let mut document_tokens = vec![];
    for token in tokens {
        // check if in vocab
        let vocab_idx = match self.vocab.get(token) {
            Some(&idx) => idx,
            None => {
                let next_token_id = self.vocab.len() as TokenId;
                self.vocab.insert(token.to_string(), next_token_id);
                next_token_id
            }
        };
        document_tokens.push(vocab_idx);
    }

    Document::new(document_tokens)
}

pub fn index_document(&mut self, idx: PointOffsetType, document: Document) {
    self.points_count += 1;
    if self.point_to_docs.len() <= idx as usize {
        self.point_to_docs
            .resize_with(idx as usize + 1, Default::default);
    }

    for token_idx in document.tokens() {
        let token_idx_usize = *token_idx as usize;
        if self.postings.len() <= token_idx_usize {
            self.postings
                .resize_with(token_idx_usize + 1, Default::default);
        }
        let posting = self
            .postings
            .get_mut(token_idx_usize)
            .expect("posting must exist even if with None");
        match posting {
            None => *posting = Some(PostingList::new(idx)),
            Some(vec) => vec.insert(idx),
        }
    }
    self.point_to_docs[idx as usize] = Some(document);
}

pub fn remove_document(&mut self, idx: PointOffsetType) -> Option<Document> {
    if self.point_to_docs.len() <= idx as usize {
        return None; // Already removed or never actually existed
    }

    let removed_doc = match std::mem::take(&mut self.point_to_docs[idx as usize]) {
        Some(doc) => doc,
        None => return None,
    };

    self.points_count -= 1;

    for removed_token in removed_doc.tokens() {
        // unwrap safety: posting list exists and contains the document id
        let posting = self.postings.get_mut(*removed_token as usize).unwrap();
        if let Some(vec) = posting {
            vec.remove(idx);
        }
    }
    Some(removed_doc)
}

pub fn filter(&self, query: &ParsedQuery) -> Box<dyn Iterator<Item = PointOffsetType> + '_> {
    let postings_opt: Option<Vec<_>> = query
        .tokens
        .iter()
        .map(|&vocab_idx| match vocab_idx {
            None => None,
            // if a ParsedQuery token was given an index, then it must exist in the vocabulary
            // dictionary. Posting list entry can be None but it exists.
            Some(idx) => self.postings.get(idx as usize).unwrap().as_ref(),
        })
        .collect();
    if postings_opt.is_none() {
        // There are unseen tokens -> no matches
        return Box::new(vec![].into_iter());
    }
    let postings = postings_opt.unwrap();
    if postings.is_empty() {
        // Empty request -> no matches
        return Box::new(vec![].into_iter());
    }
    intersect_postings_iterator(postings)
}

pub fn estimate_cardinality(
    &self,
    query: &ParsedQuery,
    condition: &FieldCondition,
) -> CardinalityEstimation {
    let postings_opt: Option<Vec<_>> = query
        .tokens
        .iter()
        .map(|&vocab_idx| match vocab_idx {
            None => None,
            // unwrap safety: same as in filter()
            Some(idx) => self.postings.get(idx as usize).unwrap().as_ref(),
        })
        .collect();
    if postings_opt.is_none() {
        // There are unseen tokens -> no matches
        return CardinalityEstimation {
            primary_clauses: vec![PrimaryCondition::Condition(condition.clone())],
            min: 0,
            exp: 0,
            max: 0,
        };
    }
    let postings = postings_opt.unwrap();
    if postings.is_empty() {
        // Empty request -> no matches
        return CardinalityEstimation {
            primary_clauses: vec![PrimaryCondition::Condition(condition.clone())],
            min: 0,
            exp: 0,
            max: 0,
        };
    }
    // Smallest posting is the largest possible cardinality
    let smallest_posting = postings.iter().map(|posting| posting.len()).min().unwrap();

    return if postings.len() == 1 {
        CardinalityEstimation {
            primary_clauses: vec![PrimaryCondition::Condition(condition.clone())],
            min: smallest_posting,
            exp: smallest_posting,
            max: smallest_posting,
        }
    } else {
        let expected_frac: f64 = postings
            .iter()
            .map(|posting| posting.len() as f64 / self.points_count as f64)
            .product();
        let exp = (expected_frac * self.points_count as f64) as usize;
        CardinalityEstimation {
            primary_clauses: vec![PrimaryCondition::Condition(condition.clone())],
            min: 0, // ToDo: make better estimation
            exp,
            max: smallest_posting,
        }
    };
}

pub fn payload_blocks(
    &self,
    threshold: usize,
    key: PayloadKeyType,
) -> Box<dyn Iterator<Item = PayloadBlockCondition> + '_> {
    // It might be very hard to predict possible combinations of conditions,
    // so we only build it for individual tokens
    Box::new(
        self.vocab
            .iter()
            .filter(|(_token, &posting_idx)| self.postings[posting_idx as usize].is_some())
            .filter(move |(_token, &posting_idx)| {
                // unwrap crash safety: all tokens that passes the first filter should have postings
                self.postings[posting_idx as usize].as_ref().unwrap().len() >= threshold
            })
            .map(|(token, &posting_idx)| {
                (
                    token,
                    // same as the above case
                    self.postings[posting_idx as usize].as_ref().unwrap(),
                )
            })
            .map(move |(token, posting)| PayloadBlockCondition {
                condition: FieldCondition {
                    key: key.clone(),
                    r#match: Some(Match::Text(MatchText {
                        text: token.clone(),
                    })),
                    range: None,
                    geo_bounding_box: None,
                    geo_radius: None,
                    geo_polygon: None,
                    values_count: None,
                },
                cardinality: posting.len(),
            }),
    )
}

pub fn new(idx: PointOffsetType) -> Self {
    Self { list: vec![idx] }
}

pub fn insert(&mut self, idx: PointOffsetType) {
    if let Err(insertion_idx) = self.list.binary_search(&idx) {
        // Yes, this is O(n) but:
        // 1. That would give us maximal search performance with minimal memory usage
        // 2. Documents are inserted mostly sequentially, especially in large segments
        // 3. Vector indexing is more expensive anyway
        // 4. We can separate updatable and remove-only indexes later
        self.list.insert(insertion_idx, idx);
    }
}

pub fn remove(&mut self, idx: PointOffsetType) {
    if let Ok(removal_idx) = self.list.binary_search(&idx) {
        self.list.remove(removal_idx);
    }
}

pub fn len(&self) -> usize {
    self.list.len()
}

pub fn contains(&self, val: &PointOffsetType) -> bool {
    self.list.binary_search(val).is_ok()
}

pub fn iter(&self) -> impl Iterator<Item = PointOffsetType> + '_ {
    self.list.iter().copied()
}

fn into_iter(self) -> Self::IntoIter {
    self.list.into_iter()
}

fn tokenize<C: FnMut(&str)>(text: &str, callback: C) {
    text.split_whitespace().for_each(callback);
}

fn tokenize<C: FnMut(&str)>(text: &str, callback: C) {
    text.split(|c| !char::is_alphanumeric(c))
        .filter(|x| !x.is_empty())
        .for_each(callback);
}

fn tokenize<C: FnMut(&str)>(text: &str, min_ngram: usize, max_ngram: usize, mut callback: C) {
    text.split(|c| !char::is_alphanumeric(c))
        .filter(|token| !token.is_empty())
        .for_each(|word| {
            for n in min_ngram..=max_ngram {
                let ngram = word.char_indices().map(|(i, _)| i).nth(n);
                match ngram {
                    Some(end) => callback(&word[..end]),
                    None => {
                        callback(word);
                        break;
                    }
                }
            }
        });
}

/// For querying prefixes, it makes sense to use a maximal ngram only.
/// E.g.
///
/// Docs. tokens: "hello" -> ["he", "hel", "hell", "hello"]
/// Query tokens: "hel"   -> ["hel"]
/// Query tokens: "hell"  -> ["hell"]
/// Query tokens: "hello" -> ["hello"]
fn tokenize_query<C: FnMut(&str)>(text: &str, max_ngram: usize, mut callback: C) {
    text.split(|c| !char::is_alphanumeric(c))
        .filter(|token| !token.is_empty())
        .for_each(|word| {
            let ngram = word.char_indices().map(|(i, _)| i).nth(max_ngram);
            match ngram {
                Some(end) => callback(&word[..end]),
                None => {
                    callback(word);
                }
            }
        });
}

fn tokenize<C: FnMut(&str)>(text: &str, mut callback: C) {
    text.tokenize().for_each(|token| {
        if token.is_word() {
            callback(token.lemma());
        }
    });
}

fn doc_token_filter<'a, C: FnMut(&str) + 'a>(
    config: &'a TextIndexParams,
    mut callback: C,
) -> impl FnMut(&str) + 'a {
    move |token: &str| {
        if config
            .min_token_len
            .map(|min_len| token.len() < min_len && token.chars().count() < min_len)
            .unwrap_or(false)
        {
            return;
        }
        if config
            .max_token_len
            .map(|max_len| token.len() > max_len && token.chars().count() > max_len)
            .unwrap_or(false)
        {
            return;
        }
        if config.lowercase.unwrap_or(true) {
            callback(&token.to_lowercase());
        } else {
            callback(token);
        }
    }
}

pub fn tokenize_doc<C: FnMut(&str)>(text: &str, config: &TextIndexParams, mut callback: C) {
    let token_filter = Self::doc_token_filter(config, &mut callback);
    match config.tokenizer {
        TokenizerType::Whitespace => WhiteSpaceTokenizer::tokenize(text, token_filter),
        TokenizerType::Word => WordTokenizer::tokenize(text, token_filter),
        TokenizerType::Multilingual => MultilingualTokenizer::tokenize(text, token_filter),
        TokenizerType::Prefix => PrefixTokenizer::tokenize(
            text,
            config.min_token_len.unwrap_or(1),
            config.max_token_len.unwrap_or(usize::MAX),
            token_filter,
        ),
    }
}

pub fn tokenize_query<C: FnMut(&str)>(text: &str, config: &TextIndexParams, mut callback: C) {
    let token_filter = Self::doc_token_filter(config, &mut callback);
    match config.tokenizer {
        TokenizerType::Whitespace => WhiteSpaceTokenizer::tokenize(text, token_filter),
        TokenizerType::Word => WordTokenizer::tokenize(text, token_filter),
        TokenizerType::Multilingual => MultilingualTokenizer::tokenize(text, token_filter),
        TokenizerType::Prefix => PrefixTokenizer::tokenize_query(
            text,
            config.max_token_len.unwrap_or(usize::MAX),
            token_filter,
        ),
    }
}

pub fn intersect_postings_iterator<'a>(
    mut postings: Vec<&'a PostingList>,
) -> Box<dyn Iterator<Item = PointOffsetType> + 'a> {
    let smallest_posting_idx = postings
        .iter()
        .enumerate()
        .min_by_key(|(_idx, posting)| posting.len())
        .map(|(idx, _posting)| idx)
        .unwrap();
    let smallest_posting = postings.remove(smallest_posting_idx);

    let and_iter = smallest_posting
        .iter()
        .filter(move |doc_id| postings.iter().all(|posting| posting.contains(doc_id)));

    Box::new(and_iter)
}

#[test]
fn test_prefix_search() {
    let temp_dir = Builder::new().prefix("test_dir").tempdir().unwrap();
    let config = TextIndexParams {
        r#type: TextIndexType::Text,
        tokenizer: TokenizerType::Prefix,
        min_token_len: None,
        max_token_len: None,
        lowercase: None,
    };

    let db = open_db_with_existing_cf(&temp_dir.path().join("test_db")).unwrap();
    let mut index = FullTextIndex::new(db, config, "text");
    index.recreate().unwrap();

    let texts = get_texts();

    for (i, text) in texts.iter().enumerate() {
        index
            .add_many(i as PointOffsetType, vec![text.to_string()])
            .unwrap();
    }

    let res: Vec<_> = index.query("ROBO").collect();

    let query = index.parse_query("ROBO");

    for idx in res.iter() {
        let doc = index.get_doc(*idx).unwrap();
        assert!(query.check_match(doc));
    }

    assert_eq!(res.len(), 3);

    let res: Vec<_> = index.query("q231").collect();

    let query = index.parse_query("q231");

    for idx in [1, 2, 3] {
        let doc = index.get_doc(idx).unwrap();
        assert!(!query.check_match(doc));
    }

    assert_eq!(res.len(), 0);
}

