pub fn open(store: Arc<RwLock<DB>>) -> OperationResult<Self> {
    let mut deleted = BitVec::new();
    let mut internal_to_external: Vec<PointIdType> = Default::default();
    let mut external_to_internal_num: BTreeMap<u64, PointOffsetType> = Default::default();
    let mut external_to_internal_uuid: BTreeMap<Uuid, PointOffsetType> = Default::default();

    let mapping_db_wrapper = DatabaseColumnScheduledDeleteWrapper::new(
        DatabaseColumnWrapper::new(store.clone(), DB_MAPPING_CF),
    );
    for (key, val) in mapping_db_wrapper.lock_db().iter()? {
        let external_id = Self::restore_key(&key);
        let internal_id: PointOffsetType =
            bincode::deserialize::<PointOffsetType>(&val).unwrap();
        if internal_id as usize >= internal_to_external.len() {
            internal_to_external.resize(internal_id as usize + 1, PointIdType::NumId(u64::MAX));
        }
        if internal_id as usize >= deleted.len() {
            deleted.resize(internal_id as usize + 1, true);
        }

        let replaced_id = internal_to_external[internal_id as usize];
        internal_to_external[internal_id as usize] = external_id;
        if !deleted[internal_id as usize] {
            // Fixing corrupted mapping - this id should be recovered from WAL
            // This should not happen in normal operation, but it can happen if
            // the database is corrupted.
            log::warn!(
                "removing duplicated external id {} in internal id {}",
                external_id,
                replaced_id
            );
            match replaced_id {
                PointIdType::NumId(idx) => {
                    external_to_internal_num.remove(&idx);
                }
                PointIdType::Uuid(uuid) => {
                    external_to_internal_uuid.remove(&uuid);
                }
            }
        }
        deleted.set(internal_id as usize, false);

        match external_id {
            PointIdType::NumId(idx) => {
                external_to_internal_num.insert(idx, internal_id);
            }
            PointIdType::Uuid(uuid) => {
                external_to_internal_uuid.insert(uuid, internal_id);
            }
        }
    }

    let mut internal_to_version: Vec<SeqNumberType> = Default::default();
    let versions_db_wrapper = DatabaseColumnScheduledDeleteWrapper::new(
        DatabaseColumnWrapper::new(store, DB_VERSIONS_CF),
    );
    for (key, val) in versions_db_wrapper.lock_db().iter()? {
        let external_id = Self::restore_key(&key);
        let version: SeqNumberType = bincode::deserialize(&val).unwrap();
        let internal_id = match external_id {
            PointIdType::NumId(idx) => external_to_internal_num.get(&idx).copied(),
            PointIdType::Uuid(uuid) => external_to_internal_uuid.get(&uuid).copied(),
        };
        if let Some(internal_id) = internal_id {
            if internal_id as usize >= internal_to_version.len() {
                internal_to_version.resize(internal_id as usize + 1, 0);
            }
            internal_to_version[internal_id as usize] = version;
        } else {
            log::debug!(
                "Found version without internal id, external id: {}",
                external_id
            );
        }
    }

    #[cfg(debug_assertions)]
    {
        for (idx, id) in external_to_internal_num.iter() {
            debug_assert!(
                internal_to_external[*id as usize] == PointIdType::NumId(*idx),
                "Internal id {id} is mapped to external id {}, but should be {}",
                internal_to_external[*id as usize],
                PointIdType::NumId(*idx)
            );
        }
    }

    Ok(SimpleIdTracker {
        deleted,
        internal_to_external,
        internal_to_version,
        external_to_internal_num,
        external_to_internal_uuid,
        mapping_db_wrapper,
        versions_db_wrapper,
    })
}

fn store_key(external_id: &PointIdType) -> Vec<u8> {
    bincode::serialize(&external_to_stored_id(external_id)).unwrap()
}

fn restore_key(data: &[u8]) -> PointIdType {
    let stored_external_id: StoredPointId = bincode::deserialize(data).unwrap();
    stored_to_external_id(stored_external_id)
}

fn delete_key(&self, external_id: &PointIdType) -> OperationResult<()> {
    self.mapping_db_wrapper
        .remove(Self::store_key(external_id))?;
    self.versions_db_wrapper
        .remove(Self::store_key(external_id))?;
    Ok(())
}

fn persist_key(&self, external_id: &PointIdType, internal_id: usize) -> OperationResult<()> {
    self.mapping_db_wrapper.put(
        Self::store_key(external_id),
        bincode::serialize(&internal_id).unwrap(),
    )
}

fn internal_version(&self, internal_id: PointOffsetType) -> Option<SeqNumberType> {
    self.internal_to_version.get(internal_id as usize).copied()
}

fn set_internal_version(
    &mut self,
    internal_id: PointOffsetType,
    version: SeqNumberType,
) -> OperationResult<()> {
    if let Some(external_id) = self.external_id(internal_id) {
        if internal_id as usize >= self.internal_to_version.len() {
            self.internal_to_version.resize(internal_id as usize + 1, 0);
        }
        self.internal_to_version[internal_id as usize] = version;
        self.versions_db_wrapper.put(
            Self::store_key(&external_id),
            bincode::serialize(&version).unwrap(),
        )?;
    }
    Ok(())
}

fn internal_id(&self, external_id: PointIdType) -> Option<PointOffsetType> {
    match external_id {
        PointIdType::NumId(idx) => self.external_to_internal_num.get(&idx).copied(),
        PointIdType::Uuid(uuid) => self.external_to_internal_uuid.get(&uuid).copied(),
    }
}

fn external_id(&self, internal_id: PointOffsetType) -> Option<PointIdType> {
    if let Some(deleted) = self.deleted.get(internal_id as usize) {
        if !deleted {
            return self.internal_to_external.get(internal_id as usize).copied();
        }
    }
    None
}

fn set_link(
    &mut self,
    external_id: PointIdType,
    internal_id: PointOffsetType,
) -> OperationResult<()> {
    match external_id {
        PointIdType::NumId(idx) => {
            self.external_to_internal_num.insert(idx, internal_id);
        }
        PointIdType::Uuid(uuid) => {
            self.external_to_internal_uuid.insert(uuid, internal_id);
        }
    }

    let internal_id = internal_id as usize;
    if internal_id >= self.internal_to_external.len() {
        self.internal_to_external
            .resize(internal_id + 1, PointIdType::NumId(u64::MAX));
    }
    if internal_id >= self.deleted.len() {
        self.deleted.resize(internal_id + 1, true);
    }
    self.internal_to_external[internal_id] = external_id;
    self.deleted.set(internal_id, false);

    self.persist_key(&external_id, internal_id)?;
    Ok(())
}

fn drop(&mut self, external_id: PointIdType) -> OperationResult<()> {
    let internal_id = match &external_id {
        PointIdType::NumId(idx) => self.external_to_internal_num.remove(idx),
        PointIdType::Uuid(uuid) => self.external_to_internal_uuid.remove(uuid),
    };
    if let Some(internal_id) = internal_id {
        self.deleted.set(internal_id as usize, true);
        self.internal_to_external[internal_id as usize] = PointIdType::NumId(u64::MAX);
    }
    self.delete_key(&external_id)?;
    Ok(())
}

fn iter_external(&self) -> Box<dyn Iterator<Item = PointIdType> + '_> {
    let iter_num = self
        .external_to_internal_num
        .keys()
        .copied()
        .map(PointIdType::NumId);
    let iter_uuid = self
        .external_to_internal_uuid
        .keys()
        .copied()
        .map(PointIdType::Uuid);
    // order is important here, we want to iterate over the u64 ids first
    Box::new(iter_num.chain(iter_uuid))
}

fn iter_internal(&self) -> Box<dyn Iterator<Item = PointOffsetType> + '_> {
    Box::new(
        (0..self.internal_to_external.len() as PointOffsetType)
            .filter(move |i| !self.deleted[*i as usize]),
    )
}

fn iter_from(
    &self,
    external_id: Option<PointIdType>,
) -> Box<dyn Iterator<Item = (PointIdType, PointOffsetType)> + '_> {
    let full_num_iter = || {
        self.external_to_internal_num
            .iter()
            .map(|(k, v)| (PointIdType::NumId(*k), *v))
    };
    let offset_num_iter = |offset: u64| {
        self.external_to_internal_num
            .range(offset..)
            .map(|(k, v)| (PointIdType::NumId(*k), *v))
    };
    let full_uuid_iter = || {
        self.external_to_internal_uuid
            .iter()
            .map(|(k, v)| (PointIdType::Uuid(*k), *v))
    };
    let offset_uuid_iter = |offset: Uuid| {
        self.external_to_internal_uuid
            .range(offset..)
            .map(|(k, v)| (PointIdType::Uuid(*k), *v))
    };

    match external_id {
        None => {
            let iter_num = full_num_iter();
            let iter_uuid = full_uuid_iter();
            // order is important here, we want to iterate over the u64 ids first
            Box::new(iter_num.chain(iter_uuid))
        }
        Some(offset) => match offset {
            PointIdType::NumId(idx) => {
                // Because u64 keys are less that uuid key, we can just use the full iterator for uuid
                let iter_num = offset_num_iter(idx);
                let iter_uuid = full_uuid_iter();
                // order is important here, we want to iterate over the u64 ids first
                Box::new(iter_num.chain(iter_uuid))
            }
            PointIdType::Uuid(uuid) => {
                // if offset is a uuid, we can only iterate over uuids
                Box::new(offset_uuid_iter(uuid))
            }
        },
    }
}

fn total_point_count(&self) -> usize {
    self.internal_to_external.len()
}

fn available_point_count(&self) -> usize {
    self.external_to_internal_num.len() + self.external_to_internal_uuid.len()
}

fn deleted_point_count(&self) -> usize {
    self.total_point_count() - self.available_point_count()
}

fn iter_ids(&self) -> Box<dyn Iterator<Item = PointOffsetType> + '_> {
    self.iter_internal()
}

/// Creates a flusher function, that persists the removed points in the mapping database
/// and flushes the mapping to disk.
/// This function should be called _before_ flushing the version database.
fn mapping_flusher(&self) -> Flusher {
    self.mapping_db_wrapper.flusher()
}

/// Creates a flusher function, that persists the removed points in the version database
/// and flushes the version database to disk.
/// This function should be called _after_ flushing the mapping database.
fn versions_flusher(&self) -> Flusher {
    self.versions_db_wrapper.flusher()
}

fn is_deleted_point(&self, key: PointOffsetType) -> bool {
    let key = key as usize;
    if key >= self.deleted.len() {
        return true;
    }
    self.deleted[key]
}

fn deleted_point_bitslice(&self) -> &BitSlice {
    &self.deleted
}

/// Build new segment with plain index in given directory
///
/// # Arguments
///
/// * `path` - path to collection\`s segment directory
///
pub fn build_simple_segment(
    path: &Path,
    dim: usize,
    distance: Distance,
) -> OperationResult<Segment> {
    build_segment(
        path,
        &SegmentConfig {
            vector_data: HashMap::from([(
                DEFAULT_VECTOR_NAME.to_owned(),
                VectorDataConfig {
                    size: dim,
                    distance,
                    storage_type: VectorStorageType::Memory,
                    index: Indexes::Plain {},
                    quantization_config: None,
                },
            )]),
            sparse_vector_data: Default::default(),
            payload_storage_type: Default::default(),
        },
        true,
    )
}

pub fn build_multivec_segment(
    path: &Path,
    dim1: usize,
    dim2: usize,
    distance: Distance,
) -> OperationResult<Segment> {
    let mut vectors_config = HashMap::new();
    vectors_config.insert(
        "vector1".to_owned(),
        VectorDataConfig {
            size: dim1,
            distance,
            storage_type: VectorStorageType::Memory,
            index: Indexes::Plain {},
            quantization_config: None,
        },
    );
    vectors_config.insert(
        "vector2".to_owned(),
        VectorDataConfig {
            size: dim2,
            distance,
            storage_type: VectorStorageType::Memory,
            index: Indexes::Plain {},
            quantization_config: None,
        },
    );

    build_segment(
        path,
        &SegmentConfig {
            vector_data: vectors_config,
            sparse_vector_data: Default::default(),
            payload_storage_type: Default::default(),
        },
        true,
    )
}

fn sp<T>(t: T) -> Arc<AtomicRefCell<T>> {
    Arc::new(AtomicRefCell::new(t))
}

fn get_vector_name_with_prefix(prefix: &str, vector_name: &str) -> String {
    if !vector_name.is_empty() {
        format!("{prefix}-{vector_name}")
    } else {
        prefix.to_owned()
    }
}

pub fn get_vector_storage_path(segment_path: &Path, vector_name: &str) -> PathBuf {
    segment_path.join(get_vector_name_with_prefix(
        VECTOR_STORAGE_PATH,
        vector_name,
    ))
}

pub fn get_vector_index_path(segment_path: &Path, vector_name: &str) -> PathBuf {
    segment_path.join(get_vector_name_with_prefix(VECTOR_INDEX_PATH, vector_name))
}

fn create_segment(
    version: Option<SeqNumberType>,
    segment_path: &Path,
    config: &SegmentConfig,
) -> OperationResult<Segment> {
    let vector_db_names: Vec<String> = config
        .vector_data
        .keys()
        .map(|vector_name| get_vector_name_with_prefix(DB_VECTOR_CF, vector_name))
        .chain(
            config
                .sparse_vector_data
                .keys()
                .map(|vector_name| get_vector_name_with_prefix(DB_VECTOR_CF, vector_name)),
        )
        .collect();
    let database = open_db(segment_path, &vector_db_names)
        .map_err(|err| OperationError::service_error(format!("RocksDB open error: {err}")))?;

    let payload_storage = match config.payload_storage_type {
        PayloadStorageType::InMemory => sp(SimplePayloadStorage::open(database.clone())?.into()),
        PayloadStorageType::OnDisk => sp(OnDiskPayloadStorage::open(database.clone())?.into()),
    };

    let id_tracker = sp(SimpleIdTracker::open(database.clone())?);

    let appendable_flag = config
        .vector_data
        .values()
        .map(|vector_config| vector_config.is_appendable())
        .chain(
            config
                .sparse_vector_data
                .values()
                .map(|sparse_vector_config| sparse_vector_config.is_appendable()),
        )
        .all(|v| v);

    let payload_index_path = segment_path.join(PAYLOAD_INDEX_PATH);
    let payload_index: Arc<AtomicRefCell<StructPayloadIndex>> = sp(StructPayloadIndex::open(
        payload_storage,
        id_tracker.clone(),
        &payload_index_path,
        appendable_flag,
    )?);

    let mut vector_data = HashMap::new();
    for (vector_name, vector_config) in &config.vector_data {
        let vector_storage_path = get_vector_storage_path(segment_path, vector_name);
        let vector_index_path = get_vector_index_path(segment_path, vector_name);

        // Select suitable vector storage type based on configuration
        let vector_storage = match vector_config.storage_type {
            // In memory
            VectorStorageType::Memory => {
                let db_column_name = get_vector_name_with_prefix(DB_VECTOR_CF, vector_name);
                open_simple_vector_storage(
                    database.clone(),
                    &db_column_name,
                    vector_config.size,
                    vector_config.distance,
                )?
            }
            // Mmap on disk, not appendable
            VectorStorageType::Mmap => open_memmap_vector_storage(
                &vector_storage_path,
                vector_config.size,
                vector_config.distance,
            )?,
            // Chunked mmap on disk, appendable
            VectorStorageType::ChunkedMmap => open_appendable_memmap_vector_storage(
                &vector_storage_path,
                vector_config.size,
                vector_config.distance,
            )?,
        };

        // Warn when number of points between ID tracker and storage differs
        let point_count = id_tracker.borrow().total_point_count();
        let vector_count = vector_storage.borrow().total_vector_count();
        if vector_count != point_count {
            log::debug!(
                "Mismatch of point and vector counts ({point_count} != {vector_count}, storage: {})",
                vector_storage_path.display(),
            );
        }

        let quantized_vectors = sp(if config.quantization_config(vector_name).is_some() {
            let quantized_data_path = vector_storage_path;
            if QuantizedVectors::config_exists(&quantized_data_path) {
                let quantized_vectors =
                    QuantizedVectors::load(&vector_storage.borrow(), &quantized_data_path)?;
                Some(quantized_vectors)
            } else {
                None
            }
        } else {
            None
        });

        let vector_index: Arc<AtomicRefCell<VectorIndexEnum>> = match &vector_config.index {
            Indexes::Plain {} => sp(VectorIndexEnum::Plain(PlainIndex::new(
                id_tracker.clone(),
                vector_storage.clone(),
                payload_index.clone(),
            ))),
            Indexes::Hnsw(vector_hnsw_config) => sp(if vector_hnsw_config.on_disk == Some(true) {
                VectorIndexEnum::HnswMmap(HNSWIndex::<GraphLinksMmap>::open(
                    &vector_index_path,
                    id_tracker.clone(),
                    vector_storage.clone(),
                    quantized_vectors.clone(),
                    payload_index.clone(),
                    vector_hnsw_config.clone(),
                )?)
            } else {
                VectorIndexEnum::HnswRam(HNSWIndex::<GraphLinksRam>::open(
                    &vector_index_path,
                    id_tracker.clone(),
                    vector_storage.clone(),
                    quantized_vectors.clone(),
                    payload_index.clone(),
                    vector_hnsw_config.clone(),
                )?)
            }),
        };

        vector_data.insert(
            vector_name.to_owned(),
            VectorData {
                vector_storage,
                vector_index,
                quantized_vectors,
            },
        );
    }

    for (vector_name, sparse_vector_config) in &config.sparse_vector_data {
        let vector_storage_path = get_vector_storage_path(segment_path, vector_name);
        let vector_index_path = get_vector_index_path(segment_path, vector_name);

        let db_column_name = get_vector_name_with_prefix(DB_VECTOR_CF, vector_name);
        let vector_storage = open_simple_sparse_vector_storage(database.clone(), &db_column_name)?;

        // Warn when number of points between ID tracker and storage differs
        let point_count = id_tracker.borrow().total_point_count();
        let vector_count = vector_storage.borrow().total_vector_count();
        if vector_count != point_count {
            log::debug!(
                "Mismatch of point and vector counts ({point_count} != {vector_count}, storage: {})",
                vector_storage_path.display(),
            );
        }

        let vector_index = match sparse_vector_config.index.index_type {
            SparseIndexType::Mmap => sp(VectorIndexEnum::SparseMmap(SparseVectorIndex::open(
                sparse_vector_config.index,
                id_tracker.clone(),
                vector_storage.clone(),
                payload_index.clone(),
                &vector_index_path,
            )?)),
            SparseIndexType::MutableRam | SparseIndexType::ImmutableRam => {
                sp(VectorIndexEnum::SparseRam(SparseVectorIndex::open(
                    sparse_vector_config.index,
                    id_tracker.clone(),
                    vector_storage.clone(),
                    payload_index.clone(),
                    &vector_index_path,
                )?))
            }
        };

        vector_data.insert(
            vector_name.to_owned(),
            VectorData {
                vector_storage,
                vector_index,
                quantized_vectors: sp(None),
            },
        );
    }

    let segment_type = if config.is_any_vector_indexed() {
        SegmentType::Indexed
    } else {
        SegmentType::Plain
    };

    Ok(Segment {
        version,
        persisted_version: Arc::new(Mutex::new(version)),
        current_path: segment_path.to_owned(),
        id_tracker,
        vector_data,
        segment_type,
        appendable_flag,
        payload_index,
        segment_config: config.clone(),
        error_status: None,
        database,
        flush_thread: Mutex::new(None),
    })
}

pub fn load_segment(path: &Path) -> OperationResult<Option<Segment>> {
    if path
        .extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| ext == "deleted")
        .unwrap_or(false)
    {
        log::warn!("Segment is marked as deleted, skipping: {}", path.display());
        // Skip deleted segments
        return Ok(None);
    }

    if !SegmentVersion::check_exists(path) {
        // Assume segment was not properly saved.
        // Server might have crashed before saving the segment fully.
        log::warn!(
            "Segment version file not found, skipping: {}",
            path.display()
        );
        return Ok(None);
    }

    let stored_version: Version = SegmentVersion::load(path)?.parse()?;
    let app_version: Version = SegmentVersion::current().parse()?;

    if stored_version != app_version {
        info!("Migrating segment {} -> {}", stored_version, app_version,);

        if stored_version > app_version {
            return Err(OperationError::service_error(format!(
                "Data version {stored_version} is newer than application version {app_version}. \
                Please upgrade the application. Compatibility is not guaranteed."
            )));
        }

        if stored_version.major == 0 && stored_version.minor < 3 {
            return Err(OperationError::service_error(format!(
                "Segment version({stored_version}) is not compatible with current version({app_version})"
            )));
        }

        if stored_version.major == 0 && stored_version.minor == 3 {
            let segment_state = load_segment_state_v3(path)?;
            Segment::save_state(&segment_state, path)?;
        } else if stored_version.major == 0 && stored_version.minor <= 5 {
            let segment_state = load_segment_state_v5(path)?;
            Segment::save_state(&segment_state, path)?;
        }

        SegmentVersion::save(path)?
    }

    let segment_state = Segment::load_state(path)?;

    let segment = create_segment(segment_state.version, path, &segment_state.config)?;

    Ok(Some(segment))
}

/// Build segment instance using given configuration.
/// Builder will generate folder for the segment and store all segment information inside it.
///
/// # Arguments
///
/// * `path` - A path to collection. Segment folder will be created in this directory
/// * `config` - Segment configuration
/// * `ready` - Whether the segment is ready after building; will save segment version
///
/// To load a segment, saving the segment version is required. If `ready` is false, the version
/// will not be stored. Then the segment is skipped on restart when trying to load it again. In
/// that case, the segment version must be stored manually to make it ready.
pub fn build_segment(path: &Path, config: &SegmentConfig, ready: bool) -> OperationResult<Segment> {
    let segment_path = path.join(Uuid::new_v4().to_string());

    std::fs::create_dir_all(&segment_path)?;

    let segment = create_segment(None, &segment_path, config)?;
    segment.save_current_state()?;

    // Version is the last file to save, as it will be used to check if segment was built correctly.
    // If it is not saved, segment will be skipped.
    if ready {
        SegmentVersion::save(&segment_path)?;
    }

    Ok(segment)
}

/// Load v0.3.* segment data and migrate to current version
#[allow(deprecated)]
fn load_segment_state_v3(segment_path: &Path) -> OperationResult<SegmentState> {
    use crate::compat::{SegmentConfigV5, StorageTypeV5, VectorDataConfigV5};

    #[derive(Deserialize)]
    #[serde(rename_all = "snake_case")]
    #[deprecated]
    pub struct SegmentStateV3 {
        pub version: SeqNumberType,
        pub config: SegmentConfigV3,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "snake_case")]
    #[deprecated]
    pub struct SegmentConfigV3 {
        /// Size of a vectors used
        pub vector_size: usize,
        /// Type of distance function used for measuring distance between vectors
        pub distance: Distance,
        /// Type of index used for search
        pub index: Indexes,
        /// Type of vector storage
        pub storage_type: StorageTypeV5,
        /// Defines payload storage type
        #[serde(default)]
        pub payload_storage_type: PayloadStorageType,
    }

    let path = segment_path.join(SEGMENT_STATE_FILE);

    let mut contents = String::new();

    let mut file = File::open(&path)?;
    file.read_to_string(&mut contents)?;

    serde_json::from_str::<SegmentStateV3>(&contents)
        .map(|state| {
            // Construct V5 version, then convert into current
            let vector_data = VectorDataConfigV5 {
                size: state.config.vector_size,
                distance: state.config.distance,
                hnsw_config: None,
                quantization_config: None,
                on_disk: None,
            };
            let segment_config = SegmentConfigV5 {
                vector_data: HashMap::from([(DEFAULT_VECTOR_NAME.to_owned(), vector_data)]),
                index: state.config.index,
                storage_type: state.config.storage_type,
                payload_storage_type: state.config.payload_storage_type,
                quantization_config: None,
            };

            SegmentState {
                version: Some(state.version),
                config: segment_config.into(),
            }
        })
        .map_err(|err| {
            OperationError::service_error(format!(
                "Failed to read segment {}. Error: {}",
                path.to_str().unwrap(),
                err
            ))
        })
}

/// Load v0.5.0 segment data and migrate to current version
#[allow(deprecated)]
fn load_segment_state_v5(segment_path: &Path) -> OperationResult<SegmentState> {
    use crate::compat::SegmentStateV5;

    let path = segment_path.join(SEGMENT_STATE_FILE);

    let mut contents = String::new();

    let mut file = File::open(&path)?;
    file.read_to_string(&mut contents)?;

    serde_json::from_str::<SegmentStateV5>(&contents)
        .map(Into::into)
        .map_err(|err| {
            OperationError::service_error(format!(
                "Failed to read segment {}. Error: {}",
                path.to_str().unwrap(),
                err
            ))
        })
}

pub fn new(
    segment_path: &Path,
    temp_dir: &Path,
    segment_config: &SegmentConfig,
) -> OperationResult<Self> {
    let segment = build_segment(temp_dir, segment_config, true)?;
    let temp_path = segment.current_path.clone();

    let destination_path = segment_path.join(temp_path.file_name().unwrap());

    Ok(SegmentBuilder {
        segment: Some(segment),
        destination_path,
        temp_path,
        indexed_fields: Default::default(),
    })
}

/// Update current segment builder with all (not deleted) vectors and payload form `other` segment
/// Perform index building at the end of update
///
/// # Arguments
///
/// * `other` - segment to add into construction
///
/// # Result
///
/// * `bool` - if `true` - data successfully added, if `false` - process was interrupted
///
pub fn update_from(&mut self, other: &Segment, stopped: &AtomicBool) -> OperationResult<bool> {
    let self_segment = match &mut self.segment {
        Some(segment) => segment,
        None => {
            return Err(OperationError::service_error(
                "Segment building error: created segment not found",
            ))
        }
    };
    self_segment.version = Some(cmp::max(self_segment.version(), other.version()));

    let other_id_tracker = other.id_tracker.borrow();
    let other_vector_storages: HashMap<_, _> = other
        .vector_data
        .iter()
        .map(|(vector_name, vector_data)| {
            (vector_name.to_owned(), vector_data.vector_storage.borrow())
        })
        .collect();
    let other_payload_index = other.payload_index.borrow();

    let mut id_tracker = self_segment.id_tracker.borrow_mut();
    let mut vector_storages: HashMap<_, _> = self_segment
        .vector_data
        .iter()
        .map(|(vector_name, vector_data)| {
            (
                vector_name.to_owned(),
                vector_data.vector_storage.borrow_mut(),
            )
        })
        .collect();
    let mut payload_index = self_segment.payload_index.borrow_mut();

    if vector_storages.len() != other_vector_storages.len() {
        return Err(OperationError::service_error(
            format!("Self and other segments have different vector names count. Self count: {}, other count: {}", vector_storages.len(), other_vector_storages.len()),
        ));
    }

    let mut new_internal_range = None;
    for (vector_name, vector_storage) in &mut vector_storages {
        check_process_stopped(stopped)?;
        let other_vector_storage = other_vector_storages.get(vector_name).ok_or_else(|| {
            OperationError::service_error(format!(
                "Cannot update from other segment because if missing vector name {vector_name}"
            ))
        })?;
        let internal_range = vector_storage.update_from(
            other_vector_storage,
            &mut other_id_tracker.iter_ids(),
            stopped,
        )?;
        match new_internal_range.clone() {
            Some(new_internal_range) => {
                if new_internal_range != internal_range {
                    return Err(OperationError::service_error(
                        "Internal ids range mismatch between self segment vectors and other segment vectors",
                    ));
                }
            }
            None => new_internal_range = Some(internal_range.clone()),
        }
    }

    if let Some(new_internal_range) = new_internal_range {
        let internal_id_iter = new_internal_range.zip(other_id_tracker.iter_ids());

        for (new_internal_id, old_internal_id) in internal_id_iter {
            check_process_stopped(stopped)?;

            let external_id =
                if let Some(external_id) = other_id_tracker.external_id(old_internal_id) {
                    external_id
                } else {
                    log::warn!(
                        "Cannot find external id for internal id {old_internal_id}, skipping"
                    );
                    continue;
                };
            let other_version = other_id_tracker.internal_version(old_internal_id).unwrap();

            match id_tracker.internal_id(external_id) {
                None => {
                    // New point, just insert
                    id_tracker.set_link(external_id, new_internal_id)?;
                    id_tracker.set_internal_version(new_internal_id, other_version)?;
                    payload_index.assign(
                        new_internal_id,
                        &other_payload_index.payload(old_internal_id)?,
                    )?;
                }
                Some(existing_internal_id) => {
                    // Point exists in both: newly constructed and old segments, so we need to merge them
                    // Based on version
                    let existing_version =
                        id_tracker.internal_version(existing_internal_id).unwrap();
                    let remove_id = if existing_version < other_version {
                        // Other version is the newest, remove the existing one and replace
                        id_tracker.drop(external_id)?;
                        id_tracker.set_link(external_id, new_internal_id)?;
                        id_tracker.set_internal_version(new_internal_id, other_version)?;
                        payload_index.drop(existing_internal_id)?;
                        payload_index.assign(
                            new_internal_id,
                            &other_payload_index.payload(old_internal_id)?,
                        )?;
                        existing_internal_id
                    } else {
                        // Old version is still good, do not move anything else
                        // Mark newly added vector as removed
                        new_internal_id
                    };
                    for vector_storage in vector_storages.values_mut() {
                        vector_storage.delete_vector(remove_id)?;
                    }
                }
            }
        }
    }

    for (field, payload_schema) in other.payload_index.borrow().indexed_fields() {
        self.indexed_fields.insert(field, payload_schema);
    }

    Ok(true)
}

pub fn build(mut self, stopped: &AtomicBool) -> Result<Segment, OperationError> {
    {
        let mut segment = self.segment.take().ok_or(OperationError::service_error(
            "Segment building error: created segment not found",
        ))?;

        for (field, payload_schema) in &self.indexed_fields {
            segment.create_field_index(segment.version(), field, Some(payload_schema))?;
            check_process_stopped(stopped)?;
        }

        Self::update_quantization(&mut segment, stopped)?;

        for vector_data in segment.vector_data.values_mut() {
            vector_data.vector_index.borrow_mut().build_index(stopped)?;
        }

        segment.flush(true)?;
        drop(segment);
        // Now segment is evicted from RAM
    }

    // Move fully constructed segment into collection directory and load back to RAM
    std::fs::rename(&self.temp_path, &self.destination_path)
        .describe("Moving segment data after optimization")?;

    let loaded_segment = load_segment(&self.destination_path)?.ok_or_else(|| {
        OperationError::service_error(format!(
            "Segment loading error: {}",
            self.destination_path.display()
        ))
    })?;
    Ok(loaded_segment)
}

fn update_quantization(segment: &mut Segment, stopped: &AtomicBool) -> OperationResult<()> {
    let config = segment.config().clone();

    for (vector_name, vector_data) in &mut segment.vector_data {
        let max_threads = if let Some(config) = config.vector_data.get(vector_name) {
            match &config.index {
                Indexes::Hnsw(hnsw) => max_rayon_threads(hnsw.max_indexing_threads),
                _ => 1,
            }
        } else {
            // quantization is applied only for dense vectors
            continue;
        };

        if let Some(quantization) = config.quantization_config(vector_name) {
            let segment_path = segment.current_path.as_path();
            check_process_stopped(stopped)?;

            let vector_storage_path = get_vector_storage_path(segment_path, vector_name);

            let vector_storage = vector_data.vector_storage.borrow();

            let quantized_vectors = QuantizedVectors::create(
                &vector_storage,
                quantization,
                &vector_storage_path,
                max_threads,
                stopped,
            )?;

            *vector_data.quantized_vectors.borrow_mut() = Some(quantized_vectors);
        }
    }
    Ok(())
}

