fn new(
    points_count: PointOffsetType,
    query_scorer: TQueryScorer,
    storage: &'a MmapVectors,
    point_deleted: &'a BitSlice,
    vec_deleted: &'a BitSlice,
    is_stopped: &'a AtomicBool,
) -> Self {
    Self {
        points_count,
        query_scorer,
        storage,
        point_deleted,
        vec_deleted,
        is_stopped,
    }
}

fn score_points(&self, points: &[PointOffsetType], scores: &mut [ScoredPointOffset]) -> usize {
    if self.is_stopped.load(Ordering::Relaxed) {
        return 0;
    }
    let points_stream = points
        .iter()
        .copied()
        .filter(|point_id| self.check_vector(*point_id));

    let mut processed = 0;
    self.storage
        .read_vectors_async(points_stream, |idx, point_id, other_vector| {
            scores[idx] = ScoredPointOffset {
                idx: point_id,
                score: self.query_scorer.score(other_vector),
            };
            processed += 1;
        })
        .unwrap();

    // ToDo: io_uring is experimental, it can fail if it is not supported.
    // Instead of silently falling back to the sync implementation, we prefer to panic
    // and notify the user that they better use the default IO implementation.

    processed
}

fn score_points_unfiltered(
    &self,
    points: &mut dyn Iterator<Item = PointOffsetType>,
) -> Vec<ScoredPointOffset> {
    if self.is_stopped.load(Ordering::Relaxed) {
        return vec![];
    }
    let mut scores = vec![];

    self.storage
        .read_vectors_async(points, |_idx, point_id, other_vector| {
            scores.push(ScoredPointOffset {
                idx: point_id,
                score: self.query_scorer.score(other_vector),
            });
        })
        .unwrap();

    // ToDo: io_uring is experimental, it can fail if it is not supported.
    // Instead of silently falling back to the sync implementation, we prefer to panic
    // and notify the user that they better use the default IO implementation.

    scores
}

fn check_vector(&self, point: PointOffsetType) -> bool {
    point < self.points_count
        // Deleted points propagate to vectors; check vector deletion for possible early return
        && !self
            .vec_deleted
            .get(point as usize)
            .map(|x| *x)
            // Default to not deleted if our deleted flags failed grow
            .unwrap_or(false)
        // Additionally check point deletion for integrity if delete propagation to vector failed
        && !self
            .point_deleted
            .get(point as usize)
            .map(|x| *x)
            // Default to deleted if the point mapping was removed from the ID tracker
            .unwrap_or(true)
}

fn score_point(&self, point: PointOffsetType) -> ScoreType {
    self.query_scorer.score_stored(point)
}

fn score_internal(&self, point_a: PointOffsetType, point_b: PointOffsetType) -> ScoreType {
    self.query_scorer.score_internal(point_a, point_b)
}

fn peek_top_iter(
    &self,
    points: &mut dyn Iterator<Item = PointOffsetType>,
    top: usize,
) -> Vec<ScoredPointOffset> {
    if top == 0 {
        return vec![];
    }

    let mut pq = FixedLengthPriorityQueue::new(top);
    let points_stream = points
        .take_while(|_| !self.is_stopped.load(Ordering::Relaxed))
        .filter(|point_id| self.check_vector(*point_id));

    self.storage
        .read_vectors_async(points_stream, |_, point_id, other_vector| {
            let scored_point_offset = ScoredPointOffset {
                idx: point_id,
                score: self.query_scorer.score(other_vector),
            };
            pq.push(scored_point_offset);
        })
        .unwrap();

    // ToDo: io_uring is experimental, it can fail if it is not supported.
    // Instead of silently falling back to the sync implementation, we prefer to panic
    // and notify the user that they better use the default IO implementation.

    pq.into_vec()
}

fn peek_top_all(&self, top: usize) -> Vec<ScoredPointOffset> {
    if top == 0 {
        return vec![];
    }

    let points_stream = (0..self.points_count)
        .take_while(|_| !self.is_stopped.load(Ordering::Relaxed))
        .filter(|point_id| self.check_vector(*point_id));

    let mut pq = FixedLengthPriorityQueue::new(top);
    self.storage
        .read_vectors_async(points_stream, |_, point_id, other_vector| {
            let scored_point_offset = ScoredPointOffset {
                idx: point_id,
                score: self.query_scorer.score(other_vector),
            };
            pq.push(scored_point_offset);
        })
        .unwrap();

    // ToDo: io_uring is experimental, it can fail if it is not supported.
    // Instead of silently falling back to the sync implementation, we prefer to panic
    // and notify the user that they better use the default IO implementation.

    pq.into_vec()
}

pub fn new(
    query: QueryVector,
    storage: &'a MemmapVectorStorage,
    point_deleted: &'a BitSlice,
) -> OperationResult<Self> {
    let points_count = storage.total_vector_count() as _;
    let vec_deleted = storage.deleted_vector_bitslice();

    let distance = storage.distance();

    let builder = Self {
        points_count,
        query,
        point_deleted,
        vec_deleted,
        storage,
        distance,
        is_stopped: None,
    };

    Ok(builder)
}

pub fn build(self) -> OperationResult<Box<dyn RawScorer + 'a>> {
    match self.distance {
        Distance::Cosine => self._build_with_metric::<CosineMetric>(),
        Distance::Euclid => self._build_with_metric::<EuclidMetric>(),
        Distance::Dot => self._build_with_metric::<DotProductMetric>(),
        Distance::Manhattan => self._build_with_metric::<ManhattanMetric>(),
    }
}

pub fn with_is_stopped(mut self, is_stopped: &'a AtomicBool) -> Self {
    self.is_stopped = Some(is_stopped);
    self
}

fn _build_with_metric<TMetric: Metric + 'a>(self) -> OperationResult<Box<dyn RawScorer + 'a>> {
    let Self {
        points_count,
        query,
        storage,
        point_deleted,
        vec_deleted,
        distance: _,
        is_stopped,
    } = self;

    match query {
        QueryVector::Nearest(vector) => {
            match vector {
                Vector::Dense(dense_vector) => {
                    let query_scorer =
                        MetricQueryScorer::<TMetric, _>::new(dense_vector, storage);
                    Ok(Box::new(AsyncRawScorerImpl::new(
                        points_count,
                        query_scorer,
                        storage.get_mmap_vectors(),
                        point_deleted,
                        vec_deleted,
                        is_stopped.unwrap_or(&DEFAULT_STOPPED),
                    )))
                }
                Vector::Sparse(_sparse_vector) => Err(OperationError::service_error(
                    "sparse vectors are not supported for async scorer",
                )), // TODO(sparse) add support?
            }
        }
        QueryVector::Recommend(reco_query) => {
            let reco_query: RecoQuery<DenseVector> = reco_query.transform_into()?;
            let query_scorer = CustomQueryScorer::<TMetric, _, _>::new(reco_query, storage);
            Ok(Box::new(AsyncRawScorerImpl::new(
                points_count,
                query_scorer,
                storage.get_mmap_vectors(),
                point_deleted,
                vec_deleted,
                is_stopped.unwrap_or(&DEFAULT_STOPPED),
            )))
        }
        QueryVector::Discovery(discovery_query) => {
            let discovery_query: DiscoveryQuery<DenseVector> =
                discovery_query.transform_into()?;
            let query_scorer =
                CustomQueryScorer::<TMetric, _, _>::new(discovery_query, storage);
            Ok(Box::new(AsyncRawScorerImpl::new(
                points_count,
                query_scorer,
                storage.get_mmap_vectors(),
                point_deleted,
                vec_deleted,
                is_stopped.unwrap_or(&DEFAULT_STOPPED),
            )))
        }
        QueryVector::Context(context_query) => {
            let context_query: ContextQuery<DenseVector> = context_query.transform_into()?;
            let query_scorer = CustomQueryScorer::<TMetric, _, _>::new(context_query, storage);
            Ok(Box::new(AsyncRawScorerImpl::new(
                points_count,
                query_scorer,
                storage.get_mmap_vectors(),
                point_deleted,
                vec_deleted,
                is_stopped.unwrap_or(&DEFAULT_STOPPED),
            )))
        }
    }
}

/// Set deleted state in given bitvec.
///
/// Grows bitvec automatically if it is not big enough.
///
/// Returns previous deleted state of the given point.
#[inline]
pub fn bitvec_set_deleted(bitvec: &mut BitVec, point_id: PointOffsetType, deleted: bool) -> bool {
    // Set deleted flag if bitvec is large enough, no need to check bounds
    if (point_id as usize) < bitvec.len() {
        return unsafe { bitvec.replace_unchecked(point_id as usize, deleted) };
    }

    // Bitvec is too small; grow and set the deletion flag, no need to check bounds
    if deleted {
        bitvec.resize(point_id as usize + 1, false);
        unsafe { bitvec.set_unchecked(point_id as usize, true) };
    }
    false
}

pub fn new(dim: usize) -> Self {
    assert_ne!(dim, 0, "The vector's dimension cannot be 0");
    let vector_size = dim * mem::size_of::<T>();
    let chunk_capacity = max(MIN_CHUNK_CAPACITY, CHUNK_SIZE / vector_size);
    Self {
        dim,
        len: 0,
        chunk_capacity,
        chunks: Vec::new(),
    }
}

pub fn len(&self) -> usize {
    self.len
}

pub fn is_empty(&self) -> bool {
    self.len == 0
}

pub fn get<TKey>(&self, key: TKey) -> &[T]
where
    TKey: num_traits::cast::AsPrimitive<usize>,
{
    let key: usize = key.as_();
    let chunk_data = &self.chunks[key / self.chunk_capacity];
    let idx = (key % self.chunk_capacity) * self.dim;
    &chunk_data[idx..idx + self.dim]
}

pub fn push(&mut self, vector: &[T]) -> Result<PointOffsetType, TryReserveError> {
    let new_id = self.len as PointOffsetType;
    self.insert(new_id, vector)?;
    Ok(new_id)
}

pub fn insert(&mut self, key: PointOffsetType, vector: &[T]) -> Result<(), TryReserveError> {
    let key = key as usize;
    self.len = max(self.len, key + 1);
    self.chunks
        .resize_with(self.len.div_ceil(self.chunk_capacity), Vec::new);

    let chunk_idx = key / self.chunk_capacity;
    let chunk_data = &mut self.chunks[chunk_idx];
    let idx = (key % self.chunk_capacity) * self.dim;

    // Grow the current chunk if needed to fit the new vector.
    //
    // All chunks are dynamically resized to fit their vectors in it.
    // Chunks have a size of zero by default. It's grown with zeroes to fit new vectors.
    //
    // The capacity for the first chunk is allocated normally to keep the memory footprint as
    // small as possible, see
    // <https://doc.rust-lang.org/std/vec/struct.Vec.html#capacity-and-reallocation>).
    // All other chunks allocate their capacity in full on first use to prevent expensive
    // reallocations when their data grows.
    if chunk_data.len() < idx + self.dim {
        // If the chunk is not the first one, allocate it fully on first use
        if chunk_idx != 0 {
            let desired_capacity = self.chunk_capacity * self.dim;
            chunk_data.try_set_capacity_exact(desired_capacity)?;
        }
        chunk_data.resize_with(idx + self.dim, T::default);
    }

    let data = &mut chunk_data[idx..idx + self.dim];
    data.copy_from_slice(vector);

    Ok(())
}

fn get_vector_data(&self, index: usize, _vector_size: usize) -> &[u8] {
    self.get(index)
}

fn from_file(
    path: &Path,
    quantized_vector_size: usize,
    vectors_count: usize,
) -> std::io::Result<Self> {
    let mut vectors = Self::new(quantized_vector_size);
    vectors
        .try_set_capacity_exact(vectors_count)
        .map_err(|err| {
            std::io::Error::new(
                std::io::ErrorKind::OutOfMemory,
                format!("Failed to load quantized vectors from file: {err}"),
            )
        })?;
    let mut file = File::open(path)?;
    let mut buffer = vec![0u8; quantized_vector_size];
    while file.read_exact(&mut buffer).is_ok() {
        vectors.push(&buffer).map_err(|err| {
            std::io::Error::new(
                std::io::ErrorKind::OutOfMemory,
                format!("Failed to load quantized vectors from file: {err}"),
            )
        })?;
    }
    if vectors.len() == vectors_count {
        Ok(vectors)
    } else {
        Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            format!(
                "Loaded vectors count {} is not equal to expected count {vectors_count}",
                vectors.len(),
            ),
        ))
    }
}

fn save_to_file(&self, path: &Path) -> std::io::Result<()> {
    let mut buffer = File::create(path)?;
    for i in 0..self.len() {
        buffer.write_all(self.get(i))?;
    }
    buffer.flush()?;
    Ok(())
}

fn try_set_capacity_exact(&mut self, capacity: usize) -> Result<(), TryReserveError> {
    let num_chunks = capacity.div_ceil(self.chunk_capacity);
    let last_chunk_idx = capacity / self.chunk_capacity;
    self.chunks.try_set_capacity_exact(num_chunks)?;
    self.chunks.resize_with(num_chunks, Vec::new);
    for chunk_idx in 0..num_chunks {
        if chunk_idx == last_chunk_idx {
            let desired_capacity = (capacity % self.chunk_capacity) * self.dim;
            self.chunks[chunk_idx].try_set_capacity_exact(desired_capacity)?;
        } else {
            let desired_capacity = self.chunk_capacity * self.dim;
            self.chunks[chunk_idx].try_set_capacity_exact(desired_capacity)?;
        }
    }
    Ok(())
}

fn build(self) -> ChunkedVectors<u8> {
    self
}

fn push_vector_data(&mut self, other: &[u8]) {
    // Memory for ChunkedVectors are already pre-allocated,
    // so we do not expect any errors here.
    self.push(other).unwrap();
}

