#[cfg(target_os = "linux")]
fn process_points_uring(
    &self,
    points: impl Iterator<Item = PointOffsetType>,
    callback: impl FnMut(usize, PointOffsetType, &[VectorElementType]),
) -> OperationResult<()> {
    self.uring_reader
        .lock()
        .as_mut()
        .expect("io_uring reader should be initialized")
        .read_stream(points, callback)
}

#[cfg(not(target_os = "linux"))]
fn process_points_simple(
    &self,
    points: impl Iterator<Item = PointOffsetType>,
    mut callback: impl FnMut(usize, PointOffsetType, &[VectorElementType]),
) -> OperationResult<()> {
    for (idx, point) in points.enumerate() {
        let vector = self.get_vector(point);
        callback(idx, point, vector);
    }
    Ok(())
}

/// Reads vectors for the given ids and calls the callback for each vector.
/// Tries to utilize asynchronous IO if possible.
/// In particular, uses io_uring on Linux and simple synchronous IO otherwise.
pub fn read_vectors_async(
    &self,
    points: impl Iterator<Item = PointOffsetType>,
    callback: impl FnMut(usize, PointOffsetType, &[VectorElementType]),
) -> OperationResult<()> {
    #[cfg(target_os = "linux")]
    {
        self.process_points_uring(points, callback)
    }

    #[cfg(not(target_os = "linux"))]
    {
        self.process_points_simple(points, callback)
    }
}

/// Ensure the given mmap file exists and is the given size
///
/// # Arguments
/// * `path`: path of the file.
/// * `header`: header to set when the file is newly created.
/// * `size`: set the file size in bytes, filled with zeroes.
fn ensure_mmap_file_size(path: &Path, header: &[u8], size: Option<u64>) -> OperationResult<()> {
    // If it exists, only set the length
    if path.exists() {
        if let Some(size) = size {
            let file = OpenOptions::new().write(true).open(path)?;
            file.set_len(size)?;
        }
        return Ok(());
    }

    // Create file, and make it the correct size
    let mut file = File::create(path)?;
    file.write_all(header)?;
    if let Some(size) = size {
        if size > header.len() as u64 {
            file.set_len(size)?;
        }
    }
    Ok(())
}

/// Get start position of flags `BitSlice` in deleted mmap.
#[inline]
const fn deleted_mmap_data_start() -> usize {
    let align = mem::align_of::<usize>();
    HEADER_SIZE.div_ceil(align) * align
}

/// Calculate size for deleted mmap to hold the given number of vectors.
///
/// The mmap will hold a file header and an aligned `BitSlice`.
fn deleted_mmap_size(num: usize) -> usize {
    let unit_size = mem::size_of::<usize>();
    let num_bytes = num.div_ceil(8);
    let num_usizes = num_bytes.div_ceil(unit_size);
    let data_size = num_usizes * unit_size;
    deleted_mmap_data_start() + data_size
}

/// Helper to open a test sparse vector index
pub fn fixture_open_sparse_index<I: InvertedIndex>(
    data_dir: &Path,
    num_vectors: usize,
    full_scan_threshold: usize,
    index_type: SparseIndexType,
) -> OperationResult<SparseVectorIndex<I>> {
    // directories
    let index_dir = &data_dir.join("index");
    let payload_dir = &data_dir.join("payload");
    let storage_dir = &data_dir.join("storage");

    // setup
    let id_tracker = Arc::new(AtomicRefCell::new(FixtureIdTracker::new(num_vectors)));
    let payload_storage = InMemoryPayloadStorage::default();
    let wrapped_payload_storage = Arc::new(AtomicRefCell::new(payload_storage.into()));
    let payload_index = StructPayloadIndex::open(
        wrapped_payload_storage,
        id_tracker.clone(),
        payload_dir,
        true,
    )?;
    let wrapped_payload_index = Arc::new(AtomicRefCell::new(payload_index));

    let db = open_db(storage_dir, &[DB_VECTOR_CF]).unwrap();
    let vector_storage = open_simple_sparse_vector_storage(db, DB_VECTOR_CF)?;
    let mut borrowed_storage = vector_storage.borrow_mut();

    // add empty points to storage
    for idx in 0..num_vectors {
        let vec = &SparseVector::new(vec![], vec![]).unwrap();
        borrowed_storage
            .insert_vector(idx as PointOffsetType, vec.into())
            .unwrap();
    }
    drop(borrowed_storage);

    // assert all empty points are in storage
    assert_eq!(
        vector_storage.borrow().available_vector_count(),
        num_vectors,
    );

    let sparse_index_config = SparseIndexConfig::new(Some(full_scan_threshold), index_type);
    let sparse_vector_index: SparseVectorIndex<I> = SparseVectorIndex::open(
        sparse_index_config,
        id_tracker,
        vector_storage.clone(),
        wrapped_payload_index,
        index_dir,
    )?;

    Ok(sparse_vector_index)
}

/// Prepares a sparse vector index with random sparse vectors
pub fn fixture_sparse_index_ram<R: Rng + ?Sized>(
    rnd: &mut R,
    num_vectors: usize,
    max_dim: usize,
    full_scan_threshold: usize,
    data_dir: &Path,
    stopped: &AtomicBool,
) -> SparseVectorIndex<InvertedIndexRam> {
    let mut sparse_vector_index = fixture_open_sparse_index(
        data_dir,
        num_vectors,
        full_scan_threshold,
        SparseIndexType::ImmutableRam,
    )
    .unwrap();
    let mut borrowed_storage = sparse_vector_index.vector_storage.borrow_mut();

    // add points to storage
    for idx in 0..num_vectors {
        let vec = &random_sparse_vector(rnd, max_dim);
        borrowed_storage
            .insert_vector(idx as PointOffsetType, vec.into())
            .unwrap();
    }
    drop(borrowed_storage);

    // assert all points are in storage
    assert_eq!(
        sparse_vector_index
            .vector_storage
            .borrow()
            .available_vector_count(),
        num_vectors
    );

    // assert no points are indexed following open for RAM index
    assert_eq!(sparse_vector_index.indexed_vector_count(), 0);

    // build index to refresh RAM index
    sparse_vector_index.build_index(stopped).unwrap();
    assert_eq!(sparse_vector_index.indexed_vector_count(), num_vectors);
    sparse_vector_index
}

