/// Creates in-memory payload storage and fills it with random points
///
/// # Arguments
///
/// * `num_points` - how many random points to insert
///
/// # Result
///
/// Payload storage fixture
///
pub fn create_payload_storage_fixture(num_points: usize, seed: u64) -> InMemoryPayloadStorage {
    let mut payload_storage = InMemoryPayloadStorage::default();
    let mut rng = StdRng::seed_from_u64(seed);

    for id in 0..num_points {
        let payload = generate_diverse_payload(&mut rng);
        payload_storage
            .assign(id as PointOffsetType, &payload)
            .unwrap();
    }

    payload_storage
}

/// Function generates `PlainPayloadIndex` with random payload for testing
///
/// # Arguments
///
/// * `path` - temp directory path
/// * `num_points` - how many payloads generate?
///
/// # Result
///
/// `PlainPayloadIndex`
///
pub fn create_plain_payload_index(path: &Path, num_points: usize, seed: u64) -> PlainPayloadIndex {
    let payload_storage = create_payload_storage_fixture(num_points, seed);
    let id_tracker = Arc::new(AtomicRefCell::new(FixtureIdTracker::new(num_points)));

    let condition_checker = Arc::new(SimpleConditionChecker::new(
        Arc::new(AtomicRefCell::new(payload_storage.into())),
        id_tracker.clone(),
    ));

    PlainPayloadIndex::open(condition_checker, id_tracker, path).unwrap()
}

/// Function generates `StructPayloadIndex` with random payload for testing.
/// It will also create indexes for payloads
///
/// # Arguments
///
/// * `path` - temp directory path
/// * `num_points` - how many payloads generate?
///
/// # Result
///
/// `StructPayloadIndex`
///
pub fn create_struct_payload_index(
    path: &Path,
    num_points: usize,
    seed: u64,
) -> StructPayloadIndex {
    let payload_storage = Arc::new(AtomicRefCell::new(
        create_payload_storage_fixture(num_points, seed).into(),
    ));
    let id_tracker = Arc::new(AtomicRefCell::new(FixtureIdTracker::new(num_points)));

    let mut index = StructPayloadIndex::open(payload_storage, id_tracker, path, true).unwrap();

    index
        .set_indexed(STR_KEY, PayloadSchemaType::Keyword.into())
        .unwrap();
    index
        .set_indexed(INT_KEY, PayloadSchemaType::Integer.into())
        .unwrap();
    index
        .set_indexed(FLT_KEY, PayloadSchemaType::Float.into())
        .unwrap();
    index
        .set_indexed(GEO_KEY, PayloadSchemaType::Geo.into())
        .unwrap();

    index
        .set_indexed(TEXT_KEY, PayloadSchemaType::Text.into())
        .unwrap();

    index
        .set_indexed(BOOL_KEY, PayloadSchemaType::Bool.into())
        .unwrap();

    index
}

fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
    match self {
        ExtendedPointId::NumId(idx) => write!(f, "{idx}"),
        ExtendedPointId::Uuid(uuid) => write!(f, "{uuid}"),
    }
}

fn from(idx: u64) -> Self {
    ExtendedPointId::NumId(idx)
}

fn from_str(s: &str) -> Result<Self, Self::Err> {
    let try_num: Result<u64, _> = s.parse();
    if let Ok(num) = try_num {
        return Ok(Self::NumId(num));
    }
    let try_uuid = Uuid::from_str(s);
    if let Ok(uuid) = try_uuid {
        return Ok(Self::Uuid(uuid));
    }
    Err(())
}

fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let value = match serde_value::Value::deserialize(deserializer) {
        Ok(val) => val,
        Err(err) => return Err(err),
    };

    if let Ok(num) = value.clone().deserialize_into() {
        return Ok(ExtendedPointId::NumId(num));
    }

    if let Ok(uuid) = value.clone().deserialize_into() {
        return Ok(ExtendedPointId::Uuid(uuid));
    }

    Err(serde::de::Error::custom(format!(
        "value {} is not a valid point ID, \
         valid values are either an unsigned integer or a UUID",
        crate::utils::fmt::SerdeValue(&value),
    )))
}

pub fn preprocess_vector(&self, vector: DenseVector) -> DenseVector {
    match self {
        Distance::Cosine => CosineMetric::preprocess(vector),
        Distance::Euclid => EuclidMetric::preprocess(vector),
        Distance::Dot => DotProductMetric::preprocess(vector),
        Distance::Manhattan => ManhattanMetric::preprocess(vector),
    }
}

pub fn postprocess_score(&self, score: ScoreType) -> ScoreType {
    match self {
        Distance::Cosine => CosineMetric::postprocess(score),
        Distance::Euclid => EuclidMetric::postprocess(score),
        Distance::Dot => DotProductMetric::postprocess(score),
        Distance::Manhattan => ManhattanMetric::postprocess(score),
    }
}

pub fn distance_order(&self) -> Order {
    match self {
        Distance::Cosine | Distance::Dot => Order::LargeBetter,
        Distance::Euclid | Distance::Manhattan => Order::SmallBetter,
    }
}

/// Checks if score satisfies threshold condition
pub fn check_threshold(&self, score: ScoreType, threshold: ScoreType) -> bool {
    match self.distance_order() {
        Order::LargeBetter => score > threshold,
        Order::SmallBetter => score < threshold,
    }
}

/// Calculates distance between two vectors
///
/// Warn: prefer compile-time generics with `Metric` trait
pub fn similarity(&self, v1: &[VectorElementType], v2: &[VectorElementType]) -> ScoreType {
    match self {
        Distance::Cosine => CosineMetric::similarity(v1, v2),
        Distance::Euclid => EuclidMetric::similarity(v1, v2),
        Distance::Dot => DotProductMetric::similarity(v1, v2),
        Distance::Manhattan => ManhattanMetric::similarity(v1, v2),
    }
}

fn cmp(&self, other: &Self) -> Ordering {
    OrderedFloat(self.score).cmp(&OrderedFloat(other.score))
}

fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
    Some(self.cmp(other))
}

fn eq(&self, other: &Self) -> bool {
    (self.id, &self.score) == (other.id, &other.score)
}

