    self.iter().map(|e| e.anonymize()).collect()
}

fn anonymize(&self) -> Self {
    Box::new(self.as_ref().anonymize())
}

fn anonymize(&self) -> Self {
    self.iter()
        .map(|(k, v)| (k.anonymize(), v.anonymize()))
        .collect()
}

fn anonymize(&self) -> Self {
    self.iter()
        .map(|(k, v)| (k.anonymize(), v.anonymize()))
        .collect()
}

fn anonymize(&self) -> Self {
    let mut hasher = DefaultHasher::new();
    self.hash(&mut hasher);
    hasher.finish().to_string()
}

fn anonymize(&self) -> Self {
    let log10 = (*self as f32).log10().round() as u32;
    if log10 > 4 {
        let skip_digits = log10 - 4;
        let coeff = 10usize.pow(skip_digits);
        (*self / coeff) * coeff
    } else {
        *self
    }
}

fn anonymize(&self) -> Self {
    let coeff: f32 = rand::random();

    *self + chrono::Duration::seconds(((coeff * 20.0) - 10.0) as i64)
}

pub fn db_options() -> Options {
    let mut options: Options = Options::default();
    options.set_write_buffer_size(DB_CACHE_SIZE);
    options.create_if_missing(true);
    options.set_log_level(LogLevel::Error);
    options.set_recycle_log_file_num(1);
    options.set_keep_log_file_num(1); // must be greater than zero
    options.set_max_log_file_size(DB_MAX_LOG_SIZE);
    options.set_delete_obsolete_files_period_micros(DB_DELETE_OBSOLETE_FILES_PERIOD);
    options.create_missing_column_families(true);
    options.set_max_open_files(DB_MAX_OPEN_FILES as i32);

    // Qdrant relies on it's own WAL for durability
    options.set_wal_recovery_mode(DBRecoveryMode::TolerateCorruptedTailRecords);
    #[cfg(debug_assertions)]
    {
        options.set_paranoid_checks(true);
    }
    options
}

pub fn open_db<T: AsRef<str>>(
    path: &Path,
    vector_paths: &[T],
) -> Result<Arc<RwLock<DB>>, rocksdb::Error> {
    let mut column_families = vec![DB_PAYLOAD_CF, DB_MAPPING_CF, DB_VERSIONS_CF];
    for vector_path in vector_paths {
        column_families.push(vector_path.as_ref());
    }
    let db = DB::open_cf(&db_options(), path, column_families)?;
    Ok(Arc::new(RwLock::new(db)))
}

pub fn check_db_exists(path: &Path) -> bool {
    let db_file = path.join("CURRENT");
    db_file.exists()
}

pub fn open_db_with_existing_cf(path: &Path) -> Result<Arc<RwLock<DB>>, rocksdb::Error> {
    let existing_column_families = if check_db_exists(path) {
        DB::list_cf(&db_options(), path)?
    } else {
        vec![]
    };
    let db = DB::open_cf(&db_options(), path, existing_column_families)?;
    Ok(Arc::new(RwLock::new(db)))
}

pub fn create_db_cf_if_not_exists(
    db: Arc<RwLock<DB>>,
    store_cf_name: &str,
) -> Result<(), rocksdb::Error> {
    let mut db_mut = db.write();
    if db_mut.cf_handle(store_cf_name).is_none() {
        db_mut.create_cf(store_cf_name, &db_options())?;
    }
    Ok(())
}

pub fn recreate_cf(db: Arc<RwLock<DB>>, store_cf_name: &str) -> Result<(), rocksdb::Error> {
    let mut db_mut = db.write();

    if db_mut.cf_handle(store_cf_name).is_some() {
        db_mut.drop_cf(store_cf_name)?;
    }

    db_mut.create_cf(store_cf_name, &db_options())?;
    Ok(())
}

pub fn new(database: Arc<RwLock<DB>>, column_name: &str) -> Self {
    Self {
        database,
        column_name: column_name.to_string(),
    }
}

pub fn put<K, V>(&self, key: K, value: V) -> OperationResult<()>
where
    K: AsRef<[u8]>,
    V: AsRef<[u8]>,
{
    let db = self.database.read();
    let cf_handle = self.get_column_family(&db)?;
    db.put_cf_opt(cf_handle, key, value, &Self::get_write_options())
        .map_err(|err| OperationError::service_error(format!("RocksDB put_cf error: {err}")))?;
    Ok(())
}

pub fn get<K>(&self, key: K) -> OperationResult<Vec<u8>>
where
    K: AsRef<[u8]>,
{
    let db = self.database.read();
    let cf_handle = self.get_column_family(&db)?;
    db.get_cf(cf_handle, key)
        .map_err(|err| OperationError::service_error(format!("RocksDB get_cf error: {err}")))?
        .ok_or_else(|| OperationError::service_error("RocksDB get_cf error: key not found"))
}

pub fn get_pinned<T, F>(&self, key: &[u8], f: F) -> OperationResult<Option<T>>
where
    F: FnOnce(&[u8]) -> T,
{
    let db = self.database.read();
    let cf_handle = self.get_column_family(&db)?;
    let result = db
        .get_pinned_cf(cf_handle, key)
        .map_err(|err| {
            OperationError::service_error(format!("RocksDB get_pinned_cf error: {err}"))
        })?
        .map(|value| f(&value));
    Ok(result)
}

pub fn remove<K>(&self, key: K) -> OperationResult<()>
where
    K: AsRef<[u8]>,
{
    let db = self.database.read();
    let cf_handle = self.get_column_family(&db)?;
    db.delete_cf(cf_handle, key).map_err(|err| {
        OperationError::service_error(format!("RocksDB delete_cf error: {err}"))
    })?;
    Ok(())
}

pub fn lock_db(&self) -> LockedDatabaseColumnWrapper {
    LockedDatabaseColumnWrapper {
        guard: self.database.read(),
        column_name: &self.column_name,
    }
}

pub fn flusher(&self) -> Flusher {
    let database = self.database.clone();
    let column_name = self.column_name.clone();
    Box::new(move || {
        let db = database.read();
        let Some(column_family) = db.cf_handle(&column_name) else {
            // It is possible, that the index was removed during the flush by user or another thread.
            // In this case, non-existing column family is not an error, but an expected behavior.

            // Still we want to log this event, for potential debugging.
            log::warn!(
                "Flush: RocksDB cf_handle error: Cannot find column family {}. Ignoring",
                &column_name
            );
            return Ok(()); // ignore error
        };

        db.flush_cf(column_family).map_err(|err| {
            OperationError::service_error(format!("RocksDB flush_cf error: {err}"))
        })?;
        Ok(())
    })
}

pub fn create_column_family_if_not_exists(&self) -> OperationResult<()> {
    let mut db = self.database.write();
    if db.cf_handle(&self.column_name).is_none() {
        db.create_cf(&self.column_name, &db_options())
            .map_err(|err| {
                OperationError::service_error(format!("RocksDB create_cf error: {err}"))
            })?;
    }
    Ok(())
}

pub fn recreate_column_family(&self) -> OperationResult<()> {
    self.remove_column_family()?;
    self.create_column_family_if_not_exists()
}

pub fn remove_column_family(&self) -> OperationResult<()> {
    let mut db = self.database.write();
    if db.cf_handle(&self.column_name).is_some() {
        db.drop_cf(&self.column_name).map_err(|err| {
            OperationError::service_error(format!("RocksDB drop_cf error: {err}"))
        })?;
    }
    Ok(())
}

pub fn has_column_family(&self) -> OperationResult<bool> {
    let db = self.database.read();
    Ok(db.cf_handle(&self.column_name).is_some())
}

fn get_write_options() -> WriteOptions {
    let mut write_options = WriteOptions::default();
    write_options.set_sync(false);
    write_options.disable_wal(true);
    write_options
}

fn get_column_family<'a>(
    &self,
    db: &'a parking_lot::RwLockReadGuard<'_, DB>,
) -> OperationResult<&'a ColumnFamily> {
    db.cf_handle(&self.column_name).ok_or_else(|| {
        OperationError::service_error(format!(
            "RocksDB cf_handle error: Cannot find column family {}",
            &self.column_name
        ))
    })
}

pub fn iter(&self) -> OperationResult<DatabaseColumnIterator> {
    DatabaseColumnIterator::new(&self.guard, self.column_name)
}

pub fn new(db: &'a DB, column_name: &str) -> OperationResult<DatabaseColumnIterator<'a>> {
    let handle = db.cf_handle(column_name).ok_or_else(|| {
        OperationError::service_error(format!(
            "RocksDB cf_handle error: Cannot find column family {column_name}"
        ))
    })?;
    let mut iter = db.raw_iterator_cf(&handle);
    iter.seek_to_first();
    Ok(DatabaseColumnIterator { handle, iter })
}

fn next(&mut self) -> Option<Self::Item> {
    // Stop if iterator has ended or errored
    if !self.iter.valid() {
        return None;
    }

    let item = (
        Box::from(self.iter.key().unwrap()),
        Box::from(self.iter.value().unwrap()),
    );

    // Search to next item for next iteration
    self.iter.next();

    Some(item)
}

fn default() -> Self {
    Self::Single(None)
}

pub(crate) fn one(value: T) -> Self {
    Self::Single(Some(value))
}

fn option(value: Option<T>) -> Self {
    Self::Single(value)
}

fn push(&mut self, value: T) {
    match self {
        Self::Single(opt) => match opt.take() {
            Some(v) => {
                *self = Self::Multiple(vec![v, value]);
            }
            None => {
                *self = Self::Single(Some(value));
            }
        },
        Self::Multiple(vec) => {
            vec.push(value);
        }
    }
}

fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
    for value in iter {
        self.push(value);
    }
}

pub fn values(self) -> Vec<T> {
    match self {
        Self::Single(opt) => opt.into_iter().collect(),
        Self::Multiple(vec) => vec,
    }
}

#[cfg(test)]
pub(crate) fn as_ref(&self) -> MultiValue<&T> {
    match self {
        Self::Single(opt) => MultiValue::option(opt.as_ref()),
        Self::Multiple(vec) => MultiValue::Multiple(vec.iter().collect()),
    }
}

pub(crate) fn check_is_empty(&self) -> bool {
    match self {
        Self::Multiple(vec) => vec.iter().all(|x| match x {
            Value::Array(vec) => vec.is_empty(),
            Value::Null => true,
            _ => false,
        }),
        Self::Single(val) => match val {
            None => true,
            Some(Value::Array(vec)) => vec.is_empty(),
            Some(Value::Null) => true,
            _ => false,
        },
    }
}

pub(crate) fn check_is_null(&self) -> bool {
    match self {
        MultiValue::Single(val) => {
            if let Some(val) = val {
                return val.is_null();
            }
            false
        }
        // { "a": [ { "b": null }, { "b": 1 } ] } => true
        // { "a": [ { "b": 1 }, { "b": null } ] } => true
        // { "a": [ { "b": 1 }, { "b": 2 } ] } => false
        MultiValue::Multiple(vals) => vals.iter().any(|val| val.is_null()),
    }
}

fn into_iter(self) -> Self::IntoIter {
    match self {
        Self::Single(None) => vec![].into_iter(),
        Self::Single(Some(a)) => vec![a].into_iter(),
        Self::Multiple(vec) => vec.into_iter(),
    }
}

pub fn rev_range(a: usize, b: usize) -> impl Iterator<Item = usize> {
    (b + 1..=a).rev()
}

/// Parse array path and index from path
///
/// return Some((path, Some(index))) if path is an array path with index
fn parse_array_path(path: &str) -> Option<(&str, Option<u32>)> {
    // shortcut no array path
    if !path.contains('[') || !path.ends_with(']') {
        return None;
    }
    let mut path = path.split('[');
    let element = path.next();
    let index = path.next();
    match (element, index) {
        (Some(element), None) => Some((element, None)), // no index info
        (Some(element), Some("]")) => Some((element, None)), // full array
        (Some(element), Some(index)) => {
            let trimmed_index = index.trim_matches(']');
            // get numeric index
            match trimmed_index.parse::<u32>() {
                Ok(num_index) => Some((element, Some(num_index))),
                Err(_) => None, // not a well formed path array
            }
        }
        _ => None,
    }
}

/// Focus on array values references according to array path
///
/// Expects to be called with a path that is a path to an Array
fn focus_array_path<'a>(
    array_path: &str,
    array_index: Option<u32>,
    rest_of_path: Option<&str>,
    json_map: &'a serde_json::Map<String, Value>,
) -> Option<MultiValue<&'a Value>> {
    match json_map.get(array_path) {
        Some(Value::Array(array)) => {
            let mut values: MultiValue<_> = MultiValue::default();
            for (i, value) in array.iter().enumerate() {
                if let Some(array_index) = array_index {
                    if i == array_index as usize {
                        match rest_of_path {
                            Some(rest_path) => {
                                // expect an Object if there is a rest path
                                if let Value::Object(map) = value {
                                    values.extend(get_value_from_json_map(rest_path, map))
                                }
                            }
                            None => values.push(value),
                        }
                    }
                } else {
                    match rest_of_path {
                        Some(rest_path) => {
                            // expect an Object if there is a rest path
                            if let Value::Object(map) = value {
                                values.extend(get_value_from_json_map(rest_path, map))
                            }
                        }
                        None => values.push(value),
                    }
                }
            }
            Some(values)
        }
        _ => None,
    }
}

pub fn get_value_from_json_map_opt<'a>(
    path: &str,
    json_map: &'a serde_json::Map<String, Value>,
) -> Option<MultiValue<&'a Value>> {
    // check if leaf path element
    match path.split_once('.') {
        Some((element, rest_path)) => {
            // check if targeting array
            match parse_array_path(element) {
                Some((array_element_path, array_index)) => {
                    focus_array_path(array_element_path, array_index, Some(rest_path), json_map)
                }
                None => {
                    // no array notation
                    match json_map.get(element) {
                        Some(Value::Object(map)) => get_value_from_json_map_opt(rest_path, map),
                        Some(value) => rest_path.is_empty().then_some(MultiValue::one(value)),
                        None => None,
                    }
                }
            }
        }
        None => match parse_array_path(path) {
            Some((array_element_path, array_index)) => {
                focus_array_path(array_element_path, array_index, None, json_map)
            }
            None => json_map.get(path).map(MultiValue::one),
        },
    }
}

/// Focus on value references according to path
/// Flatten intermediate arrays but keep leaf array values on demand.
/// E.g
/// {
///   "arr": [
///       { "a": [1, 2, 3] },
///       { "a": 4 },
///       { "b": 5 }
///   ]
/// }
///
/// path: "arr[].a"   => Vec![Value::Array[ 1, 2, 3], 4]
/// path: "arr[].a[]" => Vec![ 1, 2, 3, 4]
///
/// performance: the function could be improved by using the Entry API instead of BTreeMap.get
pub fn get_value_from_json_map<'a>(
    path: &str,
    json_map: &'a serde_json::Map<String, Value>,
) -> MultiValue<&'a Value> {
    get_value_from_json_map_opt(path, json_map).unwrap_or_default()
}

/// Delete array values according to array path
///
/// Expects to be called with a path that is a path to an Array
fn delete_array_path(
    array_path: &str,
    array_index: Option<u32>,
    rest_of_path: Option<&str>,
    json_map: &mut serde_json::Map<String, Value>,
) -> MultiValue<Value> {
    if let Some(Value::Array(array)) = json_map.get_mut(array_path) {
        match rest_of_path {
            None => {
                // end of path - delete and collect
                if let Some(array_index) = array_index {
                    if array.len() > array_index as usize {
                        return MultiValue::one(array.remove(array_index as usize));
                    }
                } else {
                    return MultiValue::one(Value::Array(std::mem::take(array)));
                }
            }
            Some(rest_path) => {
                // dig deeper
                let mut values = MultiValue::default();
                for (i, value) in array.iter_mut().enumerate() {
                    if let Value::Object(map) = value {
                        if let Some(array_index) = array_index {
                            if i == array_index as usize {
                                values.extend(remove_value_from_json_map(rest_path, map));
                            }
                        } else {
                            values.extend(remove_value_from_json_map(rest_path, map));
                        }
                    }
                }
                return values;
            }
        }
    }
    // no array found
    MultiValue::default()
}

/// Remove value at a given JSON path from JSON map
///
/// performance: the function could be improved by using the Entry API instead of BTreeMap.get_mut
pub fn remove_value_from_json_map(
    path: &str,
    json_map: &mut serde_json::Map<String, Value>,
) -> MultiValue<Value> {
    // check if leaf path element
    match path.split_once('.') {
        Some((element, rest_path)) => {
            // check if targeting array
            match parse_array_path(element) {
                Some((array_element_path, array_index)) => {
                    delete_array_path(array_element_path, array_index, Some(rest_path), json_map)
                }
                None => {
                    // no array notation
                    if rest_path.is_empty() {
                        MultiValue::option(json_map.remove(element))
                    } else {
                        match json_map.get_mut(element) {
                            None => MultiValue::default(),
                            Some(Value::Object(map)) => remove_value_from_json_map(rest_path, map),
                            Some(_value) => MultiValue::default(),
                        }
                    }
                }
            }
        }
        None => match parse_array_path(path) {
            Some((array_element_path, array_index)) => {
                delete_array_path(array_element_path, array_index, None, json_map)
            }
            None => MultiValue::option(json_map.remove(path)),
        },
    }
}

/// Check if a path is included in a list of patterns
///
/// Basically, it checks if either the pattern or path is a prefix of the other.
/// Examples:
/// ```
/// assert!(segment::common::utils::check_include_pattern("a.b.c", "a.b.c"));
/// assert!(segment::common::utils::check_include_pattern("a.b.c", "a.b"));
/// assert!(!segment::common::utils::check_include_pattern("a.b.c", "a.b.d"));
/// assert!(segment::common::utils::check_include_pattern("a.b.c", "a"));
/// assert!(segment::common::utils::check_include_pattern("a", "a.d"));
/// ```
pub fn check_include_pattern(pattern: &str, path: &str) -> bool {
    pattern
        .split(['.', '['])
        .zip(path.split(['.', '[']))
        .all(|(p, v)| p == v)
}

/// Check if a path should be excluded by a pattern
///
/// Basically, it checks if pattern is a prefix of path, but not the other way around.
///
/// ```
/// assert!(segment::common::utils::check_exclude_pattern("a.b.c", "a.b.c"));
/// assert!(!segment::common::utils::check_exclude_pattern("a.b.c", "a.b"));
/// assert!(!segment::common::utils::check_exclude_pattern("a.b.c", "a.b.d"));
/// assert!(!segment::common::utils::check_exclude_pattern("a.b.c", "a"));
/// assert!(segment::common::utils::check_exclude_pattern("a", "a.d"));
/// ```

pub fn check_exclude_pattern(pattern: &str, path: &str) -> bool {
    if pattern.len() > path.len() {
        return false;
    }
    pattern
        .split(['.', '['])
        .zip(path.split(['.', '[']))
        .all(|(p, v)| p == v)
}

fn _filter_json_values<'a>(
    mut path: String,
    value: &'a Value,
    filter: &dyn Fn(&str, &Value) -> bool,
) -> (String, Value) {
    let value = match &value {
        Value::Null => value.clone(),
        Value::Bool(_) => value.clone(),
        Value::Number(_) => value.clone(),
        Value::String(_) => value.clone(),
        Value::Array(array) => {
            let mut new_array = Vec::new();
            path.push_str("[]");
            for value in array.iter() {
                if filter(&path, value) {
                    let (path_, value) = _filter_json_values(path, value, filter);
                    path = path_;
                    new_array.push(value);
                }
            }
            path.truncate(path.len() - 2);
            Value::Array(new_array)
        }
        Value::Object(object) => {
            let mut new_object = serde_json::Map::new();
            for (key, value) in object.iter() {
                if !path.is_empty() {
                    path.push('.');
                }
                path.push_str(key);
                if filter(&path, value) {
                    let (path_, value) = _filter_json_values(path, value, filter);
                    path = path_;
                    new_object.insert(key.clone(), value);
                }
                path.truncate(path.len() - key.len());
                if !path.is_empty() {
                    path.pop();
                }
            }
            Value::Object(new_object)
        }
    };
    (path, value)
}

/// Filter json map based on external filter function
///
/// Filter function takes path and value as input and returns true if the value should be kept
pub fn filter_json_values(
    json_map: &serde_json::Map<String, Value>,
    filter: impl Fn(&str, &Value) -> bool,
) -> serde_json::Map<String, Value> {
    let path = "".to_string();
    let (_, res) = _filter_json_values(path, &Value::Object(json_map.clone()), &filter);

    if let Value::Object(map) = res {
        map
    } else {
        // This should never happen, because _filter_json_values always returns same
        // type as input
        unreachable!("Unexpected value type")
    }
}

pub fn transpose_map_into_named_vector<TVector: Into<Vector>>(
    map: HashMap<String, Vec<TVector>>,
) -> Vec<NamedVectors<'static>> {
    let mut result = Vec::new();
    for (key, values) in map {
        result.resize_with(values.len(), NamedVectors::default);
        for (i, value) in values.into_iter().enumerate() {
            result[i].insert(key.clone(), value.into());
        }
    }
    result
}

