/// Append `file` to the archive under `dest_dir` directory at `file`'s path relative to `base`.
///
/// E.g.:
/// - if `base` is `/some/directory/`
/// - `file` is `/some/directory/file/path`
/// - and `dest_dir` is `/inside/the/archive/`
/// - then the `file` will be added to the archive at path `/inside/the/archive/file/path`
pub fn append_file_relative_to_base(
    builder: &mut tar::Builder<impl io::Write>,
    base: &Path,
    file: &Path,
    dest_dir: &Path,
) -> OperationResult<()> {
    let name =
        utils::path::strip_prefix(file, base).map_err(|err| failed_to_append_error(file, err))?;

    append_file(builder, file, &dest_dir.join(name))
}

pub fn append_file(
    builder: &mut tar::Builder<impl io::Write>,
    file: &Path,
    dest: &Path,
) -> OperationResult<()> {
    builder
        .append_path_with_name(file, dest)
        .map_err(|err| failed_to_append_error(file, err))
}

/// Create "failed to append `<path>` to the archive" error.
pub fn failed_to_append_error(path: &Path, err: impl fmt::Display) -> OperationError {
    OperationError::service_error(format!(
        "failed to append {path:?} path to the archive: {err}"
    ))
}

#[allow(clippy::new_without_default)]
pub fn new() -> Self {
    Self {
        #[cfg(target_os = "linux")]
        cgroups: cgroups_mem::CgroupsMem::new(),
        sysinfo: sysinfo_mem::SysinfoMem::new(),
    }
}

#[allow(dead_code)]
pub fn refresh(&mut self) {
    #[cfg(target_os = "linux")]
    if let Some(cgroups) = &mut self.cgroups {
        cgroups.refresh();
    }

    self.sysinfo.refresh();
}

pub fn total_memory_bytes(&self) -> u64 {
    #[cfg(target_os = "linux")]
    if let Some(cgroups) = &self.cgroups {
        if let Some(memory_limit_bytes) = cgroups.memory_limit_bytes() {
            return memory_limit_bytes;
        }
    }

    self.sysinfo.total_memory_bytes()
}

pub fn available_memory_bytes(&self) -> u64 {
    #[cfg(target_os = "linux")]
    if let Some(cgroups) = &self.cgroups {
        if let Some(memory_limit_bytes) = cgroups.memory_limit_bytes() {
            return memory_limit_bytes.saturating_sub(cgroups.used_memory_bytes());
        }
    }

    self.sysinfo.available_memory_bytes()
}

/// Move all files and directories from the `dir` directory to the `dest_dir` directory.
///
/// - `<dir>/child/directory` will be merged with `<dest-dir>/child/directory` if one already exists
/// - `<dir>/some/file` will overwrite `<dest-dir>/some/file` if one already exists
pub fn move_all(dir: &Path, dest_dir: &Path) -> OperationResult<()> {
    assert_is_dir(dir)?;
    assert_is_dir(dest_dir)?;

    move_all_impl(dir, dir, dest_dir).map_err(|err| failed_to_move_error(dir, dest_dir, err))
}

fn move_all_impl(base: &Path, dir: &Path, dest_dir: &Path) -> OperationResult<()> {
    let entries = dir.read_dir().map_err(|err| {
        if base != dir {
            failed_to_read_dir_error(dir, err)
        } else {
            err.into()
        }
    })?;

    for entry in entries {
        let entry = entry.map_err(|err| {
            if base != dir {
                failed_to_read_dir_error(dir, err)
            } else {
                err.into()
            }
        })?;

        let path = entry.path();

        let name = path
            .file_name()
            .ok_or_else(|| failed_to_move_error(&path, dest_dir, "source path ends with .."))?;

        let dest_path = dest_dir.join(name);

        if path.is_dir() && dest_path.exists() {
            move_all_impl(base, &path, &dest_path)?;
        } else {
            if let Some(dir) = dest_path.parent() {
                if !dir.exists() {
                    fs::create_dir_all(dir).map_err(|err| {
                        failed_to_move_error(
                            &path,
                            &dest_path,
                            format!("failed to create {dir:?} directory: {err}"),
                        )
                    })?;
                }
            }

            fs::rename(&path, &dest_path)
                .map_err(|err| failed_to_move_error(&path, &dest_path, err))?;
        }
    }

    Ok(())
}

fn assert_is_dir(dir: &Path) -> OperationResult<()> {
    if dir.is_dir() {
        Ok(())
    } else {
        Err(not_a_dir_error(dir))
    }
}

fn not_a_dir_error(dir: &Path) -> OperationError {
    OperationError::service_error(format!(
        "path {dir:?} is not a directory (or does not exist)"
    ))
}

fn failed_to_read_dir_error(dir: &Path, err: impl fmt::Display) -> OperationError {
    OperationError::service_error(format!("failed to read {dir:?} directory: {err}"))
}

fn failed_to_move_error(path: &Path, dest: &Path, err: impl fmt::Display) -> OperationError {
    OperationError::service_error(format!("failed to move {path:?} to {dest:?}: {err}"))
}

/// Finds the first symlink in the directory tree and returns its path.
pub fn find_symlink(directory: &Path) -> Option<PathBuf> {
    let entries = match fs::read_dir(directory) {
        Ok(entries) => entries,
        Err(_) => return None,
    };

    for entry in entries {
        let entry = match entry {
            Ok(entry) => entry,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_dir() {
            if let Some(path) = find_symlink(&path) {
                return Some(path);
            }
        } else if path.is_symlink() {
            return Some(path);
        }
    }

    None
}

fn current() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

pub fn prefault_mmap_pages(&self) -> impl Iterator<Item = mmap_ops::PrefaultMmapPages> {
    let index_task = match &*self.vector_index.borrow() {
        VectorIndexEnum::HnswMmap(index) => index.prefault_mmap_pages(),
        _ => None,
    };

    let storage_task = match &*self.vector_storage.borrow() {
        VectorStorageEnum::Memmap(storage) => storage.prefault_mmap_pages(),
        _ => None,
    };

    index_task.into_iter().chain(storage_task)
}

/// Replace vectors in-place
///
/// This replaces all named vectors for this point with the given set of named vectors.
///
/// - new named vectors are inserted
/// - existing named vectors are replaced
/// - existing named vectors not specified are deleted
///
/// This differs with [`Segment::update_vectors`], because this deletes unspecified vectors.
///
/// # Warning
///
/// Available for appendable segments only.
fn replace_all_vectors(
    &mut self,
    internal_id: PointOffsetType,
    vectors: NamedVectors,
) -> OperationResult<()> {
    debug_assert!(self.is_appendable());
    check_named_vectors(&vectors, &self.segment_config)?;
    for (vector_name, vector_data) in self.vector_data.iter_mut() {
        let vector = vectors.get(vector_name);
        match vector {
            Some(vector) => {
                let mut vector_storage = vector_data.vector_storage.borrow_mut();
                vector_storage.insert_vector(internal_id, vector)?;
                let mut vector_index = vector_data.vector_index.borrow_mut();
                vector_index.update_vector(internal_id, vector)?;
            }
            None => {
                // No vector provided, so we remove it
                let mut vector_storage = vector_data.vector_storage.borrow_mut();
                vector_storage.delete_vector(internal_id)?;
            }
        }
    }
    Ok(())
}

/// Update vectors in-place
///
/// This updates all specified named vectors for this point with the given set of named vectors, leaving unspecified vectors untouched.
///
/// - new named vectors are inserted
/// - existing named vectors are replaced
/// - existing named vectors not specified are untouched and kept as-is
///
/// This differs with [`Segment::replace_all_vectors`], because this keeps unspecified vectors as-is.
///
/// # Warning
///
/// Available for appendable segments only.
fn update_vectors(
    &mut self,
    internal_id: PointOffsetType,
    vectors: NamedVectors,
) -> OperationResult<()> {
    debug_assert!(self.is_appendable());
    check_named_vectors(&vectors, &self.segment_config)?;
    for (vector_name, new_vector) in vectors {
        let vector_data = &self.vector_data[vector_name.as_ref()];
        let new_vector = new_vector.as_vec_ref();
        vector_data
            .vector_storage
            .borrow_mut()
            .insert_vector(internal_id, new_vector)?;
        vector_data
            .vector_index
            .borrow_mut()
            .update_vector(internal_id, new_vector)?;
    }
    Ok(())
}

/// Insert new vectors into the segment
///
/// # Warning
///
/// Available for appendable segments only.
fn insert_new_vectors(
    &mut self,
    point_id: PointIdType,
    vectors: NamedVectors,
) -> OperationResult<PointOffsetType> {
    debug_assert!(self.is_appendable());
    check_named_vectors(&vectors, &self.segment_config)?;
    let new_index = self.id_tracker.borrow().total_point_count() as PointOffsetType;
    for (vector_name, vector_data) in self.vector_data.iter_mut() {
        let vector_opt = vectors.get(vector_name);
        let mut vector_storage = vector_data.vector_storage.borrow_mut();
        let mut vector_index = vector_data.vector_index.borrow_mut();
        match vector_opt {
            None => {
                let dim = vector_storage.vector_dim();
                let vector: Vector = match *vector_storage {
                    VectorStorageEnum::DenseSimple(_)
                    | VectorStorageEnum::Memmap(_)
                    | VectorStorageEnum::AppendableMemmap(_) => vec![1.0; dim].into(),
                    VectorStorageEnum::SparseSimple(_) => SparseVector::default().into(),
                };
                vector_storage.insert_vector(new_index, vector.to_vec_ref())?;
                vector_storage.delete_vector(new_index)?;
                vector_index.update_vector(new_index, vector.to_vec_ref())?;
            }
            Some(vec) => {
                vector_storage.insert_vector(new_index, vec)?;
                vector_index.update_vector(new_index, vec)?;
            }
        }
    }
    self.id_tracker.borrow_mut().set_link(point_id, new_index)?;
    Ok(new_index)
}

/// Operation wrapped, which handles previous and new errors in the segment,
/// automatically updates versions and skips operations if version is too old
///
/// # Arguments
///
/// * `op_num` - sequential operation of the current operation
/// * `op_point_offset` - if operation is point-related, specify this point offset.
///     If point offset is specified, handler will use point version for comparison.
///     Otherwise, it will use global storage version
/// * `op` - operation to be wrapped. Should return `OperationResult` of bool (which is returned outside)
///     and optionally new offset of the changed point.
///
/// # Result
///
/// Propagates `OperationResult` of bool (which is returned in the `op` closure)
///
fn handle_version_and_failure<F>(
    &mut self,
    op_num: SeqNumberType,
    op_point_offset: Option<PointOffsetType>,
    operation: F,
) -> OperationResult<bool>
where
    F: FnOnce(&mut Segment) -> OperationResult<(bool, Option<PointOffsetType>)>,
{
    if let Some(SegmentFailedState {
        version: failed_version,
        point_id: _failed_point_id,
        error,
    }) = &self.error_status
    {
        // Failed operations should not be skipped,
        // fail if newer operation is attempted before proper recovery
        if *failed_version < op_num {
            return Err(OperationError::service_error(format!(
                "Not recovered from previous error: {error}"
            )));
        } // else: Re-try operation
    }

    let res = self.handle_version(op_num, op_point_offset, operation);

    match get_service_error(&res) {
        None => {
            // Recover error state
            match &self.error_status {
                None => {} // all good
                Some(error) => {
                    let point_id = op_point_offset.and_then(|point_offset| {
                        self.id_tracker.borrow().external_id(point_offset)
                    });
                    if error.point_id == point_id {
                        // Fixed
                        log::info!("Recovered from error: {}", error.error);
                        self.error_status = None;
                    }
                }
            }
        }
        Some(error) => {
            // ToDo: Recover previous segment state
            log::error!(
                "Segment {:?} operation error: {}",
                self.current_path.as_path(),
                error
            );
            let point_id = op_point_offset
                .and_then(|point_offset| self.id_tracker.borrow().external_id(point_offset));
            self.error_status = Some(SegmentFailedState {
                version: op_num,
                point_id,
                error,
            });
        }
    }
    res
}

/// Manage segment version checking
/// If current version if higher than operation version - do not perform the operation
/// Update current version if operation successfully executed
fn handle_version<F>(
    &mut self,
    op_num: SeqNumberType,
    op_point_offset: Option<PointOffsetType>,
    operation: F,
) -> OperationResult<bool>
where
    F: FnOnce(&mut Segment) -> OperationResult<(bool, Option<PointOffsetType>)>,
{
    match op_point_offset {
        None => {
            // Not a point operation *or* point does not exist.
            // Use global version to check if operation has been already applied.
            if self.version.unwrap_or(0) > op_num {
                return Ok(false); // Skip without execution
            }
        }
        Some(point_offset) => {
            // Check if point not exists or have lower version
            if self
                .id_tracker
                .borrow()
                .internal_version(point_offset)
                .map_or(false, |current_version| current_version > op_num)
            {
                return Ok(false);
            }
        }
    }

    let (applied, point_id) = operation(self)?;

    self.version = Some(max(op_num, self.version.unwrap_or(0)));

    if let Some(point_id) = point_id {
        self.id_tracker
            .borrow_mut()
            .set_internal_version(point_id, op_num)?;
    }

    Ok(applied)
}

fn lookup_internal_id(&self, point_id: PointIdType) -> OperationResult<PointOffsetType> {
    let internal_id_opt = self.id_tracker.borrow().internal_id(point_id);
    match internal_id_opt {
        Some(internal_id) => Ok(internal_id),
        None => Err(OperationError::PointIdError {
            missed_point_id: point_id,
        }),
    }
}

