pub async fn into_core_group_request<'a, F, Fut>(
    self,
    collection: &Collection,
    collection_by_name: F,
    read_consistency: Option<ReadConsistency>,
    shard_selection: ShardSelectorInternal,
) -> CollectionResult<CoreGroupRequest>
where
    F: Fn(String) -> Fut,
    Fut: Future<Output = Option<RwLockReadGuard<'a, Collection>>>,
{
    let core_search = match self.source {
        SourceRequest::Search(search_req) => search_req.into(),
        SourceRequest::Recommend(recommend_req) => {
            let referenced_vectors = fetch_vectors::resolve_referenced_vectors_batch(
                &[(recommend_req.clone(), shard_selection)],
                collection,
                collection_by_name,
                read_consistency,
            )
            .await?;

            recommend_into_core_search(recommend_req, &referenced_vectors)?
        }
    };

    Ok(CoreGroupRequest {
        source: core_search,
        group_by: self.group_by,
        group_size: self.group_size,
        limit: self.limit,
        with_lookup: self.with_lookup,
    })
}

/// Make `group_by` field selector work with as `with_payload`.
fn group_by_to_payload_selector(&self, group_by: &str) -> WithPayloadInterface {
    let group_by = group_by.strip_suffix("[]").unwrap_or(group_by).to_owned();
    WithPayloadInterface::Fields(vec![group_by])
}

async fn r#do(
    &self,
    collection: &Collection,
    read_consistency: Option<ReadConsistency>,
    shard_selection: ShardSelectorInternal,
    timeout: Option<Duration>,
) -> CollectionResult<Vec<ScoredPoint>> {
    let mut request = self.source.clone();

    request.limit = self.limit * self.group_size;

    let key_not_empty = Filter::new_must_not(Condition::IsEmpty(self.group_by.clone().into()));
    request.filter = Some(request.filter.unwrap_or_default().merge(&key_not_empty));

    let with_group_by_payload = self.group_by_to_payload_selector(&self.group_by);

    // We're enriching the final results at the end, so we'll keep this minimal
    request.with_payload = Some(with_group_by_payload);
    request.with_vector = None;

    collection
        .search(request, read_consistency, &shard_selection, timeout)
        .await
}

fn from(request: SearchGroupsRequestInternal) -> Self {
    let SearchGroupsRequestInternal {
        vector,
        filter,
        params,
        with_payload,
        with_vector,
        score_threshold,
        group_request:
            BaseGroupRequest {
                group_by,
                group_size,
                limit,
                with_lookup: with_lookup_interface,
            },
    } = request;

    let search = SearchRequestInternal {
        vector,
        filter,
        params,
        limit: 0,
        offset: Some(0),
        with_payload,
        with_vector,
        score_threshold,
    };

    GroupRequest {
        source: SourceRequest::Search(search),
        group_by,
        group_size: group_size as usize,
        limit: limit as usize,
        with_lookup: with_lookup_interface.map(Into::into),
    }
}

fn from(request: RecommendGroupsRequestInternal) -> Self {
    let RecommendGroupsRequestInternal {
        positive,
        negative,
        strategy,
        filter,
        params,
        with_payload,
        with_vector,
        score_threshold,
        using,
        lookup_from,
        group_request:
            BaseGroupRequest {
                group_by,
                group_size,
                limit,
                with_lookup: with_lookup_interface,
            },
    } = request;

    let recommend = RecommendRequestInternal {
        positive,
        negative,
        strategy,
        filter,
        params,
        limit: 0,
        offset: None,
        with_payload,
        with_vector,
        score_threshold,
        using,
        lookup_from,
    };

    GroupRequest {
        source: SourceRequest::Recommend(recommend),
        group_by,
        group_size: group_size as usize,
        limit: limit as usize,
        with_lookup: with_lookup_interface.map(Into::into),
    }
}

/// Uses the request to fill up groups of points.
pub async fn group_by(
    request: CoreGroupRequest,
    collection: &Collection,
    read_consistency: Option<ReadConsistency>,
    shard_selection: ShardSelectorInternal,
    timeout: Option<Duration>,
) -> CollectionResult<Vec<PointGroup>> {
    let score_ordering = {
        let vector_name = request.source.query.get_vector_name();
        let collection_params = collection.collection_config.read().await;
        let distance = collection_params.params.get_distance(vector_name)?;
        distance.distance_order()
    };

    let mut aggregator = GroupsAggregator::new(
        request.limit,
        request.group_size,
        request.group_by.clone(),
        score_ordering,
    );

    // Try to complete amount of groups
    let mut needs_filling = true;
    for _ in 0..MAX_GET_GROUPS_REQUESTS {
        let mut request = request.clone();

        let source = &mut request.source;

        // Construct filter to exclude already found groups
        let full_groups = aggregator.keys_of_filled_groups();
        if !full_groups.is_empty() {
            let except_any = except_on(&request.group_by, full_groups);
            if !except_any.is_empty() {
                let exclude_groups = Filter {
                    must: Some(except_any),
                    ..Default::default()
                };
                source.filter = Some(
                    source
                        .filter
                        .as_ref()
                        .map(|filter| filter.merge(&exclude_groups))
                        .unwrap_or(exclude_groups),
                );
            }
        }

        // Exclude already aggregated points
        let ids = aggregator.ids().clone();
        if !ids.is_empty() {
            let exclude_ids = Filter::new_must_not(Condition::HasId(ids.into()));
            source.filter = Some(
                source
                    .filter
                    .as_ref()
                    .map(|filter| filter.merge(&exclude_ids))
                    .unwrap_or(exclude_ids),
            );
        }

        // Make request
        let points = request
            .r#do(
                collection,
                read_consistency,
                shard_selection.clone(),
                timeout,
            )
            .await?;

        if points.is_empty() {
            break;
        }

        aggregator.add_points(&points);

        // TODO: should we break early if we have some amount of "enough" groups?
        if aggregator.len_of_filled_best_groups() >= request.limit {
            needs_filling = false;
            break;
        }
    }

    // Try to fill up groups
    if needs_filling {
        for _ in 0..MAX_GROUP_FILLING_REQUESTS {
            let mut request = request.clone();

            let source = &mut request.source;

            // Construct filter to only include unsatisfied groups
            let unsatisfied_groups = aggregator.keys_of_unfilled_best_groups();
            let match_any = match_on(&request.group_by, unsatisfied_groups);
            if !match_any.is_empty() {
                let include_groups = Filter {
                    must: Some(match_any),
                    ..Default::default()
                };
                source.filter = Some(
                    source
                        .filter
                        .as_ref()
                        .map(|filter| filter.merge(&include_groups))
                        .unwrap_or(include_groups),
                );
            }

            // Exclude already aggregated points
            let ids = aggregator.ids().clone();
            if !ids.is_empty() {
                let exclude_ids = Filter::new_must_not(Condition::HasId(ids.into()));
                source.filter = Some(
                    source
                        .filter
                        .as_ref()
                        .map(|filter| filter.merge(&exclude_ids))
                        .unwrap_or(exclude_ids),
                );
            }

            // Make request
            let points = request
                .r#do(
                    collection,
                    read_consistency,
                    shard_selection.clone(),
                    timeout,
                )
                .await?;

            if points.is_empty() {
                break;
            }

            aggregator.add_points(&points);

            if aggregator.len_of_filled_best_groups() >= request.limit {
                break;
            }
        }
    }

    // extract best results
    let mut groups = aggregator.distill();

    // flatten results
    let bare_points = groups
        .iter()
        .cloned()
        .flat_map(|group| group.hits)
        .collect();

    // enrich with payload and vector
    let enriched_points: HashMap<_, _> = collection
        .fill_search_result_with_payload(
            bare_points,
            request.source.with_payload,
            request.source.with_vector.unwrap_or_default(),
            read_consistency,
            &shard_selection,
        )
        .await?
        .into_iter()
        .map(|point| (point.id, point))
        .collect();

    // hydrate groups with enriched points
    groups
        .iter_mut()
        .for_each(|group| group.hydrate_from(&enriched_points));

    // turn into output form
    let groups = groups.into_iter().map(PointGroup::from).collect();

    Ok(groups)
}

/// Uses the set of values to create Match::Except's, if possible
fn except_on(path: &str, values: Vec<Value>) -> Vec<Condition> {
    values_to_any_variants(values)
        .into_iter()
        .map(|v| Condition::Field(FieldCondition::new_match(path, Match::new_except(v))))
        .collect()
}

/// Uses the set of values to create Match::Any's, if possible
fn match_on(path: &str, values: Vec<Value>) -> Vec<Condition> {
    values_to_any_variants(values)
        .into_iter()
        .map(|any_variants| {
            Condition::Field(FieldCondition::new_match(
                path,
                Match::new_any(any_variants),
            ))
        })
        .collect()
}

fn values_to_any_variants(values: Vec<Value>) -> Vec<AnyVariants> {
    let mut any_variants = Vec::new();

    // gather int values
    let ints = values.iter().filter_map(|v| v.as_i64()).collect_vec();

    if !ints.is_empty() {
        any_variants.push(AnyVariants::Integers(ints));
    }

    // gather string values
    let strs = values
        .iter()
        .filter_map(|v| v.as_str().map(|s| s.to_owned()))
        .collect_vec();

    if !strs.is_empty() {
        any_variants.push(AnyVariants::Keywords(strs));
    }

    any_variants
}

pub(super) fn new(groups: usize, group_size: usize, grouped_by: String, order: Order) -> Self {
    Self {
        groups: HashMap::with_capacity(groups),
        max_group_size: group_size,
        grouped_by,
        max_groups: groups,
        full_groups: HashSet::with_capacity(groups),
        group_best_scores: HashMap::with_capacity(groups),
        all_ids: HashSet::with_capacity(groups * group_size),
        order,
    }
}

/// Adds a point to the group that corresponds based on the group_by field, assumes that the point has the group_by field
fn add_point(&mut self, point: ScoredPoint) -> Result<(), AggregatorError> {
    // extract all values from the group_by field
    let payload_values: Vec<_> = point
        .payload
        .as_ref()
        .map(|p| {
            p.get_value(&self.grouped_by)
                .values()
                .into_iter()
                .flat_map(|v| match v {
                    Value::Array(arr) => arr.iter().collect(),
                    _ => vec![v],
                })
                .collect()
        })
        .ok_or(KeyNotFound)?;

    let group_keys = payload_values
        .into_iter()
        .map(GroupId::try_from)
        .collect::<Result<Vec<GroupId>, ()>>()
        .map_err(|_| BadKeyType)?;

    let unique_group_keys: Vec<_> = group_keys.into_iter().unique().collect();

    for group_key in unique_group_keys {
        let group = self
            .groups
            .entry(group_key.clone())
            .or_insert_with(|| HashMap::with_capacity(self.max_group_size));

        let entry = group.entry(point.id);

        // if the point is already in the group, check if it has newer version
        match entry {
            Entry::Occupied(mut o) => {
                if o.get().version < point.version {
                    o.insert(point.clone());
                }
            }
            Entry::Vacant(v) => {
                v.insert(point.clone());
                self.all_ids.insert(point.id);
            }
        }

        if group.len() == self.max_group_size {
            self.full_groups.insert(group_key.clone());
        }

        // Insert score if better than the group best score
        self.group_best_scores
            .entry(group_key.clone())
            .and_modify(|e| {
                *e = match self.order {
                    Order::LargeBetter => point.score.max(*e),
                    Order::SmallBetter => point.score.min(*e),
                }
            })
            .or_insert(point.score);
    }
    Ok(())
}

/// Adds multiple points to the group that they corresponds based on the group_by field, assumes that the points always have the grouped_by field, else it just ignores them
pub(super) fn add_points(&mut self, points: &[ScoredPoint]) {
    for point in points {
        match self.add_point(point.to_owned()) {
            Ok(()) | Err(KeyNotFound | BadKeyType) => continue, // ignore points that don't have the group_by field
        }
    }
}

#[cfg(test)]
pub(super) fn len(&self) -> usize {
    self.groups.len()
}

/// Return `max_groups` number of keys of the groups with the best score
fn best_group_keys(&self) -> impl Iterator<Item = &GroupId> {
    self.group_best_scores
        .iter()
        .sorted_by_key(|(_, score)| match self.order {
            Order::LargeBetter => -OrderedFloat(**score),
            Order::SmallBetter => OrderedFloat(**score),
        })
        .take(self.max_groups)
        .map(|(k, _)| k)
}

/// Gets the keys of the groups that have less than the max group size
pub(super) fn keys_of_unfilled_best_groups(&self) -> Vec<Value> {
    let best_group_keys: HashSet<_> = self.best_group_keys().cloned().collect();
    best_group_keys
        .difference(&self.full_groups)
        .cloned()
        .map_into()
        .collect()
}

/// Gets the keys of the groups that have reached the max group size
pub(super) fn keys_of_filled_groups(&self) -> Vec<Value> {
    self.full_groups.iter().cloned().map_into().collect()
}

/// Gets the amount of best groups that have reached the max group size
pub(super) fn len_of_filled_best_groups(&self) -> usize {
    let best_group_keys: HashSet<_> = self.best_group_keys().cloned().collect();
    best_group_keys.intersection(&self.full_groups).count()
}

/// Gets the ids of the already present points across all the groups
pub(super) fn ids(&self) -> &HashSet<ExtendedPointId> {
    &self.all_ids
}

/// Returns the best groups sorted by their best hit. The hits are sorted too.
pub(super) fn distill(mut self) -> Vec<Group> {
    let best_groups: Vec<_> = self.best_group_keys().cloned().collect();
    let mut groups = Vec::with_capacity(best_groups.len());

    for group_key in best_groups {
        let mut group = self.groups.remove(&group_key).unwrap();
        let scored_points_iter = group.drain().map(|(_, hit)| hit);
        let hits = match self.order {
            Order::LargeBetter => {
                peek_top_largest_iterable(scored_points_iter, self.max_group_size)
            }
            Order::SmallBetter => {
                peek_top_smallest_iterable(scored_points_iter, self.max_group_size)
            }
        };
        groups.push(Group {
            hits,
            key: group_key,
        });
    }

    groups
}

