/// Wait until all other known peers reach the given commit
///
/// # Errors
///
/// This errors if:
/// - any of the peers is not on the same term
/// - waiting takes longer than the specified timeout
/// - any of the peers cannot be reached
///
/// # Cancel safety
///
/// This method is cancel safe.
pub async fn await_commit_on_all_peers(
    &self,
    this_peer_id: PeerId,
    commit: u64,
    term: u64,
    timeout: Duration,
) -> Result<(), CollectionError> {
    let requests = self
        .id_to_address
        .read()
        .keys()
        .filter(|id| **id != this_peer_id)
        // The collective timeout at the bottom of this function handles actually timing out.
        // Since an explicit timeout must be given here as well, it is multiplied by two to
        // give the collective timeout some space.
        .map(|peer_id| self.await_commit_on_peer(*peer_id, commit, term, timeout * 2))
        .collect::<Vec<_>>();
    let responses = try_join_all(requests);

    // Handle requests with timeout
    tokio::time::timeout(timeout, responses)
        .await
        // Timeout error
        .map_err(|_elapsed| CollectionError::Timeout {
            description: "Failed to wait for consensus commit on all peers, timed out.".into(),
        })?
        // Await consensus error
        .map_err(|err| {
            CollectionError::service_error(format!(
                "Failed to wait for consensus commit on peer: {err}"
            ))
        })?;
    Ok(())
}

/// Wait until the given peer reaches the given commit
///
/// # Errors
///
/// This errors if the given peer is on a different term. Also errors if the peer cannot be reached.
///
/// # Cancel safety
///
/// This method is cancel safe.
async fn await_commit_on_peer(
    &self,
    peer_id: PeerId,
    commit: u64,
    term: u64,
    timeout: Duration,
) -> Result<(), CollectionError> {
    let response = self
        .with_qdrant_client(peer_id, |mut client| async move {
            let request = WaitOnConsensusCommitRequest {
                commit: commit as i64,
                term: term as i64,
                timeout: timeout.as_secs() as i64,
            };
            client.wait_on_consensus_commit(Request::new(request)).await
        })
        .await
        .map_err(|err| {
            CollectionError::service_error(format!(
                "Failed to wait for consensus commit on peer {peer_id}: {err}"
            ))
        })?
        .into_inner();

    // Create error if wait request failed
    if !response.ok {
        return Err(CollectionError::service_error(format!(
            "Failed to wait for consensus commit on peer {peer_id}, has diverged commit/term or timed out."
        )));
    }
    Ok(())
}

async fn with_qdrant_client<T, O: Future<Output = Result<T, Status>>>(
    &self,
    peer_id: PeerId,
    f: impl Fn(QdrantInternalClient<InterceptedService<Channel, AddTimeout>>) -> O,
) -> Result<T, CollectionError> {
    let address = self
        .id_to_address
        .read()
        .get(&peer_id)
        .ok_or_else(|| CollectionError::service_error("Address for peer ID is not found."))?
        .clone();
    self.channel_pool
        .with_channel(&address, |channel| {
            let client = QdrantInternalClient::new(channel);
            let client = client.max_decoding_message_size(usize::MAX);
            f(client)
        })
        .await
        .map_err(Into::into)
}

/// Get the REST address for the current peer.
pub fn current_rest_address(&self, this_peer_id: PeerId) -> CollectionResult<Url> {
    // Get local peer URI
    let local_peer_uri = self
        .id_to_address
        .read()
        .get(&this_peer_id)
        .cloned()
        .ok_or_else(|| {
            CollectionError::service_error(format!(
                "Cannot determine REST address, this peer not found in cluster by ID {this_peer_id} ",
            ))
        })?;

    // Construct REST URL from URI
    let mut url = Url::parse(&local_peer_uri.to_string()).expect("Malformed URL");
    url.set_port(Some(self.current_rest_port))
        .map_err(|()| {
            CollectionError::service_error(format!(
                "Cannot determine REST address, cannot specify port on address {url} for peer ID {this_peer_id}",
            ))
        })?;
    Ok(url)
}

fn default() -> Self {
    Self {
        id_to_address: Default::default(),
        channel_pool: Default::default(),
        current_rest_port: 6333,
    }
}

pub fn new(collection_path: &Path) -> CollectionResult<Self> {
    let mut rings = HashMap::new();
    rings.insert(None, HashRing::fair(HASH_RING_SHARD_SCALE));
    let shard_transfers = SaveOnDisk::load_or_init(collection_path.join(SHARD_TRANSFERS_FILE))?;
    let key_mapping: SaveOnDisk<ShardKeyMapping> =
        SaveOnDisk::load_or_init(collection_path.join(SHARD_KEY_MAPPING_FILE))?;
    let mut shard_id_to_key_mapping = HashMap::new();

    for (shard_key, shard_ids) in key_mapping.read().iter() {
        for shard_id in shard_ids {
            shard_id_to_key_mapping.insert(*shard_id, shard_key.clone());
        }
    }

    Ok(Self {
        shards: HashMap::new(),
        shard_transfers,
        rings,
        key_mapping,
        shard_id_to_key_mapping,
    })
}

pub fn save_key_mapping_to_dir(&self, dir: &Path) -> CollectionResult<()> {
    let path = dir.join(SHARD_KEY_MAPPING_FILE);
    self.key_mapping.save_to(path)?;
    Ok(())
}

pub fn get_shard_id_to_key_mapping(&self) -> &HashMap<ShardId, ShardKey> {
    &self.shard_id_to_key_mapping
}

pub fn get_shard_key_to_ids_mapping(&self) -> ShardKeyMapping {
    self.key_mapping.read().clone()
}

async fn drop_and_remove_shard(&mut self, shard_id: ShardId) -> Result<(), CollectionError> {
    if let Some(replica_set) = self.shards.remove(&shard_id) {
        let shard_path = replica_set.shard_path.clone();
        drop(replica_set);
        tokio::fs::remove_dir_all(shard_path).await?;
    }
    Ok(())
}

pub fn add_shard(
    &mut self,
    shard_id: ShardId,
    shard: ShardReplicaSet,
    shard_key: Option<ShardKey>,
) -> Result<(), CollectionError> {
    self.shards.insert(shard_id, shard);
    self.rings
        .entry(shard_key.clone())
        .or_insert_with(|| HashRing::fair(HASH_RING_SHARD_SCALE))
        .add(shard_id);

    if let Some(shard_key) = shard_key {
        self.key_mapping.write_optional(|key_mapping| {
            let has_id = key_mapping
                .get(&shard_key)
                .map(|shard_ids| shard_ids.contains(&shard_id))
                .unwrap_or(false);

            if has_id {
                return None;
            }
            let mut copy_of_mapping = key_mapping.clone();
            let shard_ids = copy_of_mapping.entry(shard_key.clone()).or_default();
            shard_ids.insert(shard_id);
            Some(copy_of_mapping)
        })?;
        self.shard_id_to_key_mapping.insert(shard_id, shard_key);
    }
    Ok(())
}

pub async fn remove_shard_key(&mut self, shard_key: &ShardKey) -> Result<(), CollectionError> {
    let mut remove_shard_ids = Vec::new();

    self.key_mapping.write_optional(|key_mapping| {
        if key_mapping.contains_key(shard_key) {
            let mut new_key_mapping = key_mapping.clone();
            if let Some(shard_ids) = new_key_mapping.remove(shard_key) {
                for shard_id in shard_ids {
                    remove_shard_ids.push(shard_id);
                }
            }
            Some(new_key_mapping)
        } else {
            None
        }
    })?;

    self.rings.remove(&Some(shard_key.clone()));
    for shard_id in remove_shard_ids {
        self.drop_and_remove_shard(shard_id).await?;
        self.shard_id_to_key_mapping.remove(&shard_id);
    }
    Ok(())
}

fn rebuild_rings(&mut self) {
    let mut rings = HashMap::new();
    rings.insert(None, HashRing::fair(HASH_RING_SHARD_SCALE));
    let ids_to_key = self.get_shard_id_to_key_mapping();
    for shard_id in self.shards.keys() {
        let shard_key = ids_to_key.get(shard_id).cloned();
        rings
            .entry(shard_key)
            .or_insert_with(|| HashRing::fair(HASH_RING_SHARD_SCALE))
            .add(*shard_id);
    }

    self.rings = rings;
}

pub async fn apply_shards_state(
    &mut self,
    shard_ids: HashSet<ShardId>,
    shard_key_mapping: ShardKeyMapping,
    extra_shards: HashMap<ShardId, ShardReplicaSet>,
) -> Result<(), CollectionError> {
    self.shards.extend(extra_shards.into_iter());

    let all_shard_ids = self.shards.keys().cloned().collect::<HashSet<_>>();

    self.key_mapping
        .write_optional(|_key_mapping| Some(shard_key_mapping))?;

    for shard_id in all_shard_ids {
        if !shard_ids.contains(&shard_id) {
            self.drop_and_remove_shard(shard_id).await?;
        }
    }

    self.rebuild_rings();

    Ok(())
}

/// Take shard
///
/// remove shard and return ownership
pub fn take_shard(&mut self, shard_id: ShardId) -> Option<ShardReplicaSet> {
    self.shards.remove(&shard_id)
}

pub fn contains_shard(&self, shard_id: &ShardId) -> bool {
    self.shards.contains_key(shard_id)
}

pub fn get_shard(&self, shard_id: &ShardId) -> Option<&ShardReplicaSet> {
    self.shards.get(shard_id)
