pub fn split_by_shard<O: SplitByShard + Clone>(
    &self,
    operation: O,
    shard_keys_selection: &Option<ShardKey>,
) -> CollectionResult<Vec<(&ShardReplicaSet, O)>> {
    let Some(hashring) = self.rings.get(shard_keys_selection) else {
        return if let Some(shard_key) = shard_keys_selection {
            Err(CollectionError::bad_input(format!(
                "Shard key {shard_key} not found"
            )))
        } else {
            Err(CollectionError::bad_input(
                "Shard key not specified".to_string(),
            ))
        };
    };

    if hashring.is_empty() {
        return Err(CollectionError::bad_input(
            "No shards found for shard key".to_string(),
        ));
    }

    let operation_to_shard = operation.split_by_shard(hashring);
    let shard_ops: Vec<_> = match operation_to_shard {
        OperationToShard::ByShard(by_shard) => by_shard
            .into_iter()
            .map(|(shard_id, operation)| (self.shards.get(&shard_id).unwrap(), operation))
            .collect(),
        OperationToShard::ToAll(operation) => {
            if let Some(shard_key) = shard_keys_selection {
                let shard_ids = self
                    .key_mapping
                    .read()
                    .get(shard_key)
                    .cloned()
                    .unwrap_or_default();
                shard_ids
                    .into_iter()
                    .map(|shard_id| (self.shards.get(&shard_id).unwrap(), operation.clone()))
                    .collect()
            } else {
                self.all_shards()
                    .map(|shard| (shard, operation.clone()))
                    .collect()
            }
        }
    };
    Ok(shard_ops)
}

pub fn register_start_shard_transfer(&self, transfer: ShardTransfer) -> CollectionResult<bool> {
    Ok(self
        .shard_transfers
        .write(|transfers| transfers.insert(transfer))?)
}

pub fn register_finish_transfer(&self, key: &ShardTransferKey) -> CollectionResult<bool> {
    Ok(self.shard_transfers.write(|transfers| {
        let before_remove = transfers.len();
        transfers.retain(|transfer| !key.check(transfer));
        before_remove != transfers.len() // `true` if something was removed
    })?)
}

/// The count of incoming and outgoing shard transfers on the given peer
///
/// This only includes shard transfers that are in consensus for the current collection. A
/// shard transfer that has just been proposed may not be included yet.
pub fn count_shard_transfer_io(&self, peer_id: &PeerId) -> (usize, usize) {
    let (mut incoming, mut outgoing) = (0, 0);

    for transfer in self.shard_transfers.read().iter() {
        incoming += (transfer.to == *peer_id) as usize;
        outgoing += (transfer.from == *peer_id) as usize;
    }

    (incoming, outgoing)
}

pub fn get_shard_transfer_info(&self) -> Vec<ShardTransferInfo> {
    let mut shard_transfers = vec![];
    for shard_transfer in self.shard_transfers.read().iter() {
        let shard_id = shard_transfer.shard_id;
        let to = shard_transfer.to;
        let from = shard_transfer.from;
        let sync = shard_transfer.sync;
        let method = shard_transfer.method;
        shard_transfers.push(ShardTransferInfo {
            shard_id,
            from,
            to,
            sync,
            method,
        })
    }
    shard_transfers.sort_by_key(|k| k.shard_id);
    shard_transfers
}

fn get_shard_ids_by_key(&self, shard_key: &ShardKey) -> CollectionResult<HashSet<ShardId>> {
    match self.key_mapping.read().get(shard_key).cloned() {
        None => Err(CollectionError::bad_request(format!(
            "Shard key {shard_key} not found"
        ))),
        Some(ids) => Ok(ids),
    }
}

pub fn select_shards<'a>(
    &'a self,
    shard_selector: &'a ShardSelectorInternal,
) -> CollectionResult<Vec<(&ShardReplicaSet, Option<&ShardKey>)>> {
    let mut res = Vec::new();

    match shard_selector {
        ShardSelectorInternal::Empty => {
            debug_assert!(false, "Do not expect empty shard selector")
        }
        ShardSelectorInternal::All => {
            for (shard_id, shard) in self.shards.iter() {
                let shard_key = self.shard_id_to_key_mapping.get(shard_id);
                res.push((shard, shard_key));
            }
        }
        ShardSelectorInternal::ShardKey(shard_key) => {
            for shard_id in self.get_shard_ids_by_key(shard_key)? {
                if let Some(replica_set) = self.shards.get(&shard_id) {
                    res.push((replica_set, Some(shard_key)));
                } else {
                    debug_assert!(false, "Shard id {shard_id} not found")
                }
            }
        }
        ShardSelectorInternal::ShardKeys(shard_keys) => {
            for shard_key in shard_keys {
                for shard_id in self.get_shard_ids_by_key(shard_key)? {
                    if let Some(replica_set) = self.shards.get(&shard_id) {
                        res.push((replica_set, Some(shard_key)));
                    } else {
                        debug_assert!(false, "Shard id {shard_id} not found")
                    }
                }
            }
        }
        ShardSelectorInternal::ShardId(shard_id) => {
            if let Some(replica_set) = self.shards.get(shard_id) {
                res.push((replica_set, self.shard_id_to_key_mapping.get(shard_id)));
            } else {
                return Err(shard_not_found_error(*shard_id));
            }
        }
    }
    Ok(res)
}

pub fn target_shard(
    &self,
    shard_selection: Option<ShardId>,
) -> CollectionResult<Vec<&ShardReplicaSet>> {
    match shard_selection {
        None => Ok(self.all_shards().collect()),
        Some(shard_selection) => {
            let shard_opt = self.get_shard(&shard_selection);
            let shards = match shard_opt {
                None => vec![],
                Some(shard) => vec![shard],
            };
            Ok(shards)
        }
    }
}

pub fn len(&self) -> usize {
    self.shards.len()
}

pub fn is_empty(&self) -> bool {
    self.shards.is_empty()
}

#[allow(clippy::too_many_arguments)]
pub async fn load_shards(
    &mut self,
    collection_path: &Path,
    collection_id: &CollectionId,
    collection_config: Arc<RwLock<CollectionConfig>>,
    shared_storage_config: Arc<SharedStorageConfig>,
    channel_service: ChannelService,
    on_peer_failure: ChangePeerState,
    abort_shard_transfer: AbortShardTransfer,
    this_peer_id: PeerId,
    update_runtime: Handle,
    search_runtime: Handle,
) {
    let shard_number = collection_config.read().await.params.shard_number.get();

    let (shard_ids_list, shard_id_to_key_mapping) = match collection_config
        .read()
        .await
        .params
        .sharding_method
        .unwrap_or_default()
    {
        ShardingMethod::Auto => {
            let ids_list = (0..shard_number).collect::<Vec<_>>();
            let shard_id_to_key_mapping = HashMap::new();
            (ids_list, shard_id_to_key_mapping)
        }
        ShardingMethod::Custom => {
            let shard_id_to_key_mapping = self.get_shard_id_to_key_mapping();
            let ids_list = shard_id_to_key_mapping
                .keys()
                .cloned()
                .sorted()
                .collect::<Vec<_>>();
            (ids_list, shard_id_to_key_mapping.clone())
        }
    };

    // ToDo: remove after version 0.11.0
    for shard_id in shard_ids_list {
        for (path, _shard_version, shard_type) in
            latest_shard_paths(collection_path, shard_id).await.unwrap()
        {
            let replica_set = ShardReplicaSet::load(
                shard_id,
                collection_id.clone(),
                &path,
                collection_config.clone(),
                shared_storage_config.clone(),
                channel_service.clone(),
                on_peer_failure.clone(),
                abort_shard_transfer.clone(),
                this_peer_id,
                update_runtime.clone(),
                search_runtime.clone(),
            )
            .await;

            let mut require_migration = true;
            match shard_type {
                ShardType::Local => {
                    // deprecated
                    let local_shard = LocalShard::load(
                        shard_id,
                        collection_id.clone(),
                        &path,
                        collection_config.clone(),
                        shared_storage_config.clone(),
                        update_runtime.clone(),
                    )
                    .await
                    .unwrap();
                    replica_set
                        .set_local(local_shard, Some(ReplicaState::Active))
                        .await
                        .unwrap();
                }
                ShardType::Remote { peer_id } => {
                    // deprecated
                    replica_set
                        .add_remote(peer_id, ReplicaState::Active)
                        .await
                        .unwrap();
                }
                ShardType::Temporary => {
                    // deprecated
                    let temp_shard = LocalShard::load(
                        shard_id,
                        collection_id.clone(),
                        &path,
                        collection_config.clone(),
                        shared_storage_config.clone(),
                        update_runtime.clone(),
                    )
                    .await
                    .unwrap();

                    replica_set
                        .set_local(temp_shard, Some(ReplicaState::Partial))
                        .await
                        .unwrap();
                }
                ShardType::ReplicaSet => {
                    require_migration = false;
                    // nothing to do, replicate set should be loaded already
                }
            }
            // Migrate shard config to replica set
            // Override existing shard configuration
            if require_migration {
                ShardConfig::new_replica_set()
                    .save(&path)
                    .map_err(|e| panic!("Failed to save shard config {path:?}: {e}"))
                    .unwrap();
            }

            // Change local shards stuck in Initializing state to Active
            let local_peer_id = replica_set.this_peer_id();
            let not_distributed = !shared_storage_config.is_distributed;
            let is_local =
                replica_set.this_peer_id() == local_peer_id && replica_set.is_local().await;
            let is_initializing =
                replica_set.peer_state(&local_peer_id) == Some(ReplicaState::Initializing);
            if not_distributed && is_local && is_initializing {
                log::warn!("Local shard {collection_id}:{} stuck in Initializing state, changing to Active", replica_set.shard_id);
                replica_set
                    .set_replica_state(&local_peer_id, ReplicaState::Active)
                    .expect("Failed to set local shard state");
            }
            let shard_key = shard_id_to_key_mapping.get(&shard_id).cloned();
            self.add_shard(shard_id, replica_set, shard_key).unwrap();
        }
    }
}

pub async fn assert_shard_exists(&self, shard_id: ShardId) -> CollectionResult<()> {
    match self.get_shard(&shard_id) {
        Some(_) => Ok(()),
        None => Err(shard_not_found_error(shard_id)),
    }
}

async fn assert_shard_is_local(&self, shard_id: ShardId) -> CollectionResult<()> {
    let is_local_shard = self
        .is_shard_local(&shard_id)
        .await
        .ok_or_else(|| shard_not_found_error(shard_id))?;

    if is_local_shard {
        Ok(())
    } else {
        Err(CollectionError::bad_input(format!(
            "Shard {shard_id} is not a local shard"
        )))
    }
}

async fn assert_shard_is_local_or_queue_proxy(
    &self,
    shard_id: ShardId,
) -> CollectionResult<()> {
    let is_local_shard = self
        .is_shard_local_or_queue_proxy(&shard_id)
        .await
        .ok_or_else(|| shard_not_found_error(shard_id))?;

    if is_local_shard {
        Ok(())
    } else {
        Err(CollectionError::bad_input(format!(
            "Shard {shard_id} is not a local or queue proxy shard"
        )))
    }
}

/// Returns true if shard is explicitly local, false otherwise.
pub async fn is_shard_local(&self, shard_id: &ShardId) -> Option<bool> {
    match self.get_shard(shard_id) {
        Some(shard) => Some(shard.is_local().await),
        None => None,
    }
}

/// Returns true if shard is explicitly local or is queue proxy shard, false otherwise.
pub async fn is_shard_local_or_queue_proxy(&self, shard_id: &ShardId) -> Option<bool> {
    match self.get_shard(shard_id) {
        Some(shard) => Some(shard.is_local().await || shard.is_queue_proxy().await),
        None => None,
    }
}

/// Return a list of local shards, present on this peer
pub async fn get_local_shards(&self) -> Vec<ShardId> {
    let mut res = Vec::with_capacity(1);
    for (shard_id, replica_set) in self.get_shards() {
        if replica_set.has_local_shard().await {
            res.push(*shard_id);
        }
    }
    res
}

pub async fn is_all_active(&self) -> bool {
    self.get_shards().all(|(_, replica_set)| {
        replica_set
            .peers()
            .into_iter()
            .all(|(_, state)| state == ReplicaState::Active)
    })
}

pub fn check_transfer_exists(&self, transfer_key: &ShardTransferKey) -> bool {
    self.shard_transfers
        .read()
        .iter()
        .any(|transfer| transfer_key.check(transfer))
}

pub fn get_outgoing_transfers(&self, current_peer_id: &PeerId) -> Vec<ShardTransfer> {
    self.get_transfers(|transfer| transfer.from == *current_peer_id)
}

/// # Cancel safety
///
/// This method is cancel safe.
pub async fn list_shard_snapshots(
    &self,
    snapshots_path: &Path,
    shard_id: ShardId,
) -> CollectionResult<Vec<SnapshotDescription>> {
    self.assert_shard_is_local(shard_id).await?;

    let snapshots_path = self.snapshots_path_for_shard_unchecked(snapshots_path, shard_id);

    if !snapshots_path.exists() {
        return Ok(Vec::new());
    }

    list_snapshots_in_directory(&snapshots_path).await
}

/// # Cancel safety
///
/// This method is cancel safe.
pub async fn create_shard_snapshot(
    &self,
    snapshots_path: &Path,
    collection_name: &str,
    shard_id: ShardId,
    temp_dir: &Path,
) -> CollectionResult<SnapshotDescription> {
    // - `snapshot_temp_dir`, `snapshot_target_dir` and `temp_file` are handled by `tempfile`
    //   and would be deleted, if future is cancelled

    let shard = self
        .get_shard(&shard_id)
        .ok_or_else(|| shard_not_found_error(shard_id))?;

    if !shard.is_local().await && !shard.is_queue_proxy().await {
        return Err(CollectionError::bad_input(format!(
            "Shard {shard_id} is not a local or queue proxy shard"
        )));
    }

    let snapshot_file_name = format!(
        "{collection_name}-shard-{shard_id}-{}.snapshot",
        chrono::Utc::now().format("%Y-%m-%d-%H-%M-%S"),
    );

    let snapshot_temp_dir = tempfile::Builder::new()
        .prefix(&format!("{snapshot_file_name}-temp-"))
        .tempdir_in(temp_dir)?;

    let snapshot_target_dir = tempfile::Builder::new()
        .prefix(&format!("{snapshot_file_name}-target-"))
        .tempdir_in(temp_dir)?;

    shard
        .create_snapshot(snapshot_temp_dir.path(), snapshot_target_dir.path(), false)
        .await?;

    let snapshot_temp_dir_path = snapshot_temp_dir.path().to_path_buf();
    if let Err(err) = snapshot_temp_dir.close() {
        log::error!(
            "Failed to remove temporary directory {}: {err}",
            snapshot_temp_dir_path.display(),
        );
    }

    let mut temp_file = tempfile::Builder::new()
        .prefix(&format!("{snapshot_file_name}-"))
        .tempfile_in(temp_dir)?;

    let task = {
        let snapshot_target_dir = snapshot_target_dir.path().to_path_buf();

        cancel::blocking::spawn_cancel_on_drop(move |cancel| -> CollectionResult<_> {
            let mut tar = TarBuilder::new(temp_file.as_file_mut());

            if cancel.is_cancelled() {
                return Err(cancel::Error::Cancelled.into());
            }

            tar.append_dir_all(".", &snapshot_target_dir)?;

            if cancel.is_cancelled() {
                return Err(cancel::Error::Cancelled.into());
            }

            tar.finish()?;
            drop(tar);

            Ok(temp_file)
        })
    };

    let task_result = task.await;

    let snapshot_target_dir_path = snapshot_target_dir.path().to_path_buf();
    if let Err(err) = snapshot_target_dir.close() {
        log::error!(
            "Failed to remove temporary directory {}: {err}",
            snapshot_target_dir_path.display(),
        );
    }

    let temp_file = task_result??;

    let snapshot_path =
        self.shard_snapshot_path_unchecked(snapshots_path, shard_id, snapshot_file_name)?;

    if let Some(snapshot_dir) = snapshot_path.parent() {
        if !snapshot_dir.exists() {
            std::fs::create_dir_all(snapshot_dir)?;
        }
    }

    // Remove partially moved `snapshot_path`, if `move_file` fails
    let snapshot_file = tempfile::TempPath::from_path(&snapshot_path);

    // `tempfile::NamedTempFile::persist` does not work if destination file is on another
    // file-system, so we have to move the file explicitly
    move_file(temp_file.path(), &snapshot_path).await?;

    // We successfully moved `snapshot_path`, so we `keep` it
    snapshot_file.keep()?;

    // We successfully moved `temp_file`, but `tempfile` will still try to delete the file on drop,
    // so we `keep` it and ignore the error
    let _ = temp_file.keep();

    get_snapshot_description(&snapshot_path).await
}

/// # Cancel safety
///
/// This method is *not* cancel safe.
#[allow(clippy::too_many_arguments)]
pub async fn restore_shard_snapshot(
    &self,
    snapshot_path: &Path,
    collection_name: &str,
    shard_id: ShardId,
    this_peer_id: PeerId,
    is_distributed: bool,
    temp_dir: &Path,
    cancel: cancel::CancellationToken,
) -> CollectionResult<()> {
    if !self.contains_shard(&shard_id) {
        return Err(shard_not_found_error(shard_id));
    }

    let snapshot = std::fs::File::open(snapshot_path)?;

    if !temp_dir.exists() {
        std::fs::create_dir_all(temp_dir)?;
    }

    let snapshot_file_name = snapshot_path.file_name().unwrap().to_string_lossy();

    let snapshot_temp_dir = tempfile::Builder::new()
        .prefix(&format!(
            "{collection_name}-shard-{shard_id}-{snapshot_file_name}"
        ))
        .tempdir_in(temp_dir)?;

    let task = {
        let snapshot_temp_dir = snapshot_temp_dir.path().to_path_buf();

        cancel::blocking::spawn_cancel_on_token(
            cancel.child_token(),
            move |cancel| -> CollectionResult<_> {
                let mut tar = tar::Archive::new(snapshot);

                if cancel.is_cancelled() {
                    return Err(cancel::Error::Cancelled.into());
                }

                tar.unpack(&snapshot_temp_dir)?;
                drop(tar);

                if cancel.is_cancelled() {
                    return Err(cancel::Error::Cancelled.into());
                }

                ShardReplicaSet::restore_snapshot(
                    &snapshot_temp_dir,
                    this_peer_id,
                    is_distributed,
                )?;

                Ok(())
            },
        )
    };

    task.await??;

    // `ShardHolder::recover_local_shard_from` is *not* cancel safe
    // (see `ShardReplicaSet::restore_local_replica_from`)
    let recovered = self
        .recover_local_shard_from(snapshot_temp_dir.path(), shard_id, cancel)
        .await?;

    if !recovered {
        return Err(CollectionError::bad_request(format!(
            "Invalid snapshot {snapshot_file_name}"
        )));
    }

    Ok(())
}

/// # Cancel safety
///
/// This method is *not* cancel safe.
pub async fn recover_local_shard_from(
    &self,
    snapshot_shard_path: &Path,
    shard_id: ShardId,
    cancel: cancel::CancellationToken,
) -> CollectionResult<bool> {
    // TODO:
    //   Check that shard snapshot is compatible with the collection
    //   (see `VectorsConfig::check_compatible_with_segment_config`)

    let replica_set = self
        .get_shard(&shard_id)
        .ok_or_else(|| shard_not_found_error(shard_id))?;

    // `ShardReplicaSet::restore_local_replica_from` is *not* cancel safe
    replica_set
        .restore_local_replica_from(snapshot_shard_path, cancel)
        .await
}

/// # Cancel safety
///
/// This method is cancel safe.
pub async fn get_shard_snapshot_path(
    &self,
    snapshots_path: &Path,
    shard_id: ShardId,
    snapshot_file_name: impl AsRef<Path>,
) -> CollectionResult<PathBuf> {
    self.assert_shard_is_local_or_queue_proxy(shard_id).await?;
    self.shard_snapshot_path_unchecked(snapshots_path, shard_id, snapshot_file_name)
}

fn snapshots_path_for_shard_unchecked(
    &self,
    snapshots_path: &Path,
    shard_id: ShardId,
) -> PathBuf {
    snapshots_path.join(format!("shards/{shard_id}"))
}

fn shard_snapshot_path_unchecked(
    &self,
    snapshots_path: &Path,
    shard_id: ShardId,
    snapshot_file_name: impl AsRef<Path>,
) -> CollectionResult<PathBuf> {
    let snapshots_path = self.snapshots_path_for_shard_unchecked(snapshots_path, shard_id);

    let snapshot_file_name = snapshot_file_name.as_ref();

    if snapshot_file_name.file_name() != Some(snapshot_file_name.as_os_str()) {
        return Err(CollectionError::bad_input(format!(
            "Invalid snapshot file name {}",
            snapshot_file_name.display(),
        )));
    }

    let snapshot_path = snapshots_path.join(snapshot_file_name);

    Ok(snapshot_path)
}

pub async fn remove_shards_at_peer(&self, peer_id: PeerId) -> CollectionResult<()> {
    for (_shard_id, replica_set) in self.get_shards() {
        replica_set.remove_peer(peer_id).await?;
    }
    Ok(())
}

pub(crate) fn shard_not_found_error(shard_id: ShardId) -> CollectionError {
    CollectionError::NotFound {
        what: format!("shard {shard_id}"),
    }
}

fn resolve(records: Vec<Self>, condition: ResolveCondition) -> Self {
    match condition {
        ResolveCondition::All => Self {
            count: records
                .iter()
                .map(|result| result.count)
                .min()
                .unwrap_or_default(),
        },
        ResolveCondition::Majority => {
            let mut counts = records
                .iter()
                .map(|result| result.count)
                .collect::<Vec<_>>();
            counts.sort_unstable();
            let middle = counts.len() / 2;
            Self {
                count: counts.get(middle).copied().unwrap_or_default(),
            }
        }
    }
}

fn resolve(records: Vec<Self>, condition: ResolveCondition) -> Self {
    let mut resolved = Resolver::resolve(records, |record| record.id, record_eq, condition);
    resolved.sort_unstable_by_key(|record| record.id);
    resolved
}

fn resolve(batches: Vec<Self>, condition: ResolveCondition) -> Self {
    // batches: <replica_id, <batch_id, ScoredPoint>>
    // transpose to <batch_id, <replica_id, ScoredPoint>>

    let batches = transpose(batches);

    batches
        .into_iter()
        .map(|points| {
            let mut resolved =
                Resolver::resolve(points, |point| point.id, scored_point_eq, condition);

            resolved.sort_unstable();
            resolved
        })
        .collect()
}

fn transpose<T>(vec: Vec<Vec<T>>) -> Vec<Vec<T>> {
    if vec.is_empty() {
        return Vec::new();
    }

    let len = vec[0].len();

    let mut iters: Vec<_> = vec.into_iter().map(IntoIterator::into_iter).collect();

    (0..len)
        .map(|_| iters.iter_mut().filter_map(Iterator::next).collect())
        .collect()
}

fn record_eq(this: &Record, other: &Record) -> bool {
    this.id == other.id && this.vector == other.vector && payload_eq(&this.payload, &other.payload)
}

fn scored_point_eq(this: &ScoredPoint, other: &ScoredPoint) -> bool {
    this.id == other.id
        && this.score == other.score
        && this.vector == other.vector
        && payload_eq(&this.payload, &other.payload)
}

fn payload_eq(this: &Option<Payload>, other: &Option<Payload>) -> bool {
    match (this, other) {
        (Some(payload), None) | (None, Some(payload)) => payload.is_empty(),
        (this, other) => this == other,
    }
}

pub fn resolve(
    items: Vec<Vec<Item>>,
    identify: Ident,
    compare: Cmp,
    condition: ResolveCondition,
) -> Vec<Item> {
    let resolution_count = match condition {
        ResolveCondition::All => items.len(),
        ResolveCondition::Majority => items.len() / 2 + 1,
    };

    let mut resolver = Resolver::new(items.first().map_or(0, Vec::len), identify, compare);
    resolver.add_all(&items);

    // Select coordinates of accepted items, avoiding copying
    let resolved_items: HashSet<_> = resolver
        .items
        .into_iter()
        .filter_map(|(_, points)| {
            points
                .into_iter()
                .find(|point| point.count >= resolution_count)
                .map(|point| (point.row, point.index))
        })
        .collect();

    // Shortcut if everything is consistent: return first items, avoiding filtering
    let is_consistent = resolved_items.len() == items.first().map_or(0, Vec::len)
        && resolved_items.iter().all(|&(row, _)| row == 0);

    if is_consistent {
        items.into_iter().next().unwrap_or_default()
    } else {
        items
            .into_iter()
            .enumerate()
            .flat_map(|(row, items)| {
                items
                    .into_iter()
                    .enumerate()
                    .map(move |(index, item)| (row, index, item))
            })
            .filter_map(|(row, index, item)| {
                if resolved_items.contains(&(row, index)) {
                    Some(item)
                } else {
                    None
                }
            })
            .collect()
    }
}

fn new(capacity: usize, identify: Ident, compare: Cmp) -> Self {
    Self {
        items: HashMap::with_capacity(capacity),
        identify,
        compare,
    }
}

fn add_all<I>(&mut self, items: I)
where
    I: IntoIterator,
    I::Item: IntoIterator<Item = &'a Item>,
{
    for (row, items) in items.into_iter().enumerate() {
        for (index, item) in items.into_iter().enumerate() {
            self.add((self.identify)(item), item, row, index);
        }
    }
}

fn add(&mut self, id: Id, item: &'a Item, row: usize, index: usize) {
    let points = self.items.entry(id).or_default();

    for point in points.iter_mut() {
        if (self.compare)(item, point.item.unwrap()) {
            point.count += 1;
            return;
        }
    }

    points.push(ResolverRecord::new(item, row, index));
}

fn clone(&self) -> Self {
    *self
}

fn default() -> Self {
    Self {
        item: None,
        row: 0,
        index: 0,
        count: 0,
    }
}

fn new(item: &'a T, row: usize, index: usize) -> Self {
    Self {
        item: Some(item),
        row,
        index,
        count: 1,
    }
}

pub async fn create_shard_key(
    &self,
    shard_key: ShardKey,
    placement: ShardsPlacement,
) -> Result<(), CollectionError> {
    let state = self.state().await;
    match state.config.params.sharding_method.unwrap_or_default() {
        ShardingMethod::Auto => {
            return Err(CollectionError::bad_request(format!(
                "Shard Key {} cannot be created with Auto sharding method",
                shard_key
            )));
        }
        ShardingMethod::Custom => {}
    }

    if state.shards_key_mapping.contains_key(&shard_key) {
        return Err(CollectionError::bad_request(format!(
            "Shard key {} already exists",
            shard_key
        )));
    }

    let all_peers: HashSet<_> = self
        .channel_service
        .id_to_address
        .read()
        .keys()
        .cloned()
        .collect();

    let unknown_peers: Vec<_> = placement
        .iter()
        .flatten()
        .filter(|peer_id| !all_peers.contains(peer_id))
        .collect();

    if !unknown_peers.is_empty() {
        return Err(CollectionError::bad_request(format!(
            "Shard Key {} placement contains unknown peers: {:?}",
            shard_key, unknown_peers
        )));
    }

    let max_shard_id = state.max_shard_id();

    let payload_schema = self.payload_index_schema.read().schema.clone();

    for (idx, shard_replicas_placement) in placement.iter().enumerate() {
        let shard_id = max_shard_id + idx as ShardId + 1;

        let replica_set = self
            .create_replica_set(shard_id, shard_replicas_placement)
            .await?;

        for (field_name, field_schema) in payload_schema.iter() {
            let create_index_op = CollectionUpdateOperations::FieldIndexOperation(
                FieldIndexOperations::CreateIndex(CreateIndex {
                    field_name: field_name.clone(),
                    field_schema: Some(field_schema.clone()),
                }),
            );

            replica_set.update_local(create_index_op, true).await?;
        }

        self.shards_holder.write().await.add_shard(
            shard_id,
            replica_set,
            Some(shard_key.clone()),
        )?;
    }
    Ok(())
}

pub async fn drop_shard_key(&self, shard_key: ShardKey) -> Result<(), CollectionError> {
    let state = self.state().await;

    match state.config.params.sharding_method.unwrap_or_default() {
        ShardingMethod::Auto => {
            return Err(CollectionError::bad_request(format!(
                "Shard Key {} cannot be removed with Auto sharding method",
                shard_key
            )));
        }
        ShardingMethod::Custom => {}
    }

    self.shards_holder
        .write()
        .await
        .remove_shard_key(&shard_key)
        .await
}

#[allow(clippy::too_many_arguments)]
pub async fn new(
    name: CollectionId,
    this_peer_id: PeerId,
    path: &Path,
    snapshots_path: &Path,
    collection_config: &CollectionConfig,
    shared_storage_config: Arc<SharedStorageConfig>,
    shard_distribution: CollectionShardDistribution,
    channel_service: ChannelService,
    on_replica_failure: ChangePeerState,
    request_shard_transfer: RequestShardTransfer,
    abort_shard_transfer: replica_set::AbortShardTransfer,
    search_runtime: Option<Handle>,
    update_runtime: Option<Handle>,
) -> Result<Self, CollectionError> {
    let start_time = std::time::Instant::now();

    let mut shard_holder = ShardHolder::new(path)?;

    let shared_collection_config = Arc::new(RwLock::new(collection_config.clone()));
    for (shard_id, mut peers) in shard_distribution.shards {
        let is_local = peers.remove(&this_peer_id);

        let replica_set = ShardReplicaSet::build(
            shard_id,
            name.clone(),
            this_peer_id,
            is_local,
            peers,
            on_replica_failure.clone(),
            abort_shard_transfer.clone(),
            path,
            shared_collection_config.clone(),
            shared_storage_config.clone(),
            channel_service.clone(),
            update_runtime.clone().unwrap_or_else(Handle::current),
            search_runtime.clone().unwrap_or_else(Handle::current),
            None,
        )
        .await?;

        shard_holder.add_shard(shard_id, replica_set, None)?;
    }

    let locked_shard_holder = Arc::new(LockedShardHolder::new(shard_holder));

    // Once the config is persisted - the collection is considered to be successfully created.
    CollectionVersion::save(path)?;
    collection_config.save(path)?;

    let payload_index_schema = Self::load_payload_index_schema(path)?;

    Ok(Self {
        id: name.clone(),
        shards_holder: locked_shard_holder,
        collection_config: shared_collection_config,
        payload_index_schema,
        shared_storage_config,
        this_peer_id,
        path: path.to_owned(),
        snapshots_path: snapshots_path.to_owned(),
        channel_service,
        transfer_tasks: Mutex::new(TransferTasksPool::new(name.clone())),
        request_shard_transfer_cb: request_shard_transfer.clone(),
        notify_peer_failure_cb: on_replica_failure.clone(),
        abort_shard_transfer_cb: abort_shard_transfer,
        init_time: start_time.elapsed(),
        is_initialized: Arc::new(Default::default()),
        updates_lock: RwLock::new(()),
        update_runtime: update_runtime.unwrap_or_else(Handle::current),
        search_runtime: search_runtime.unwrap_or_else(Handle::current),
    })
}

#[allow(clippy::too_many_arguments)]
pub async fn load(
    collection_id: CollectionId,
    this_peer_id: PeerId,
    path: &Path,
    snapshots_path: &Path,
    shared_storage_config: Arc<SharedStorageConfig>,
    channel_service: ChannelService,
    on_replica_failure: replica_set::ChangePeerState,
    request_shard_transfer: RequestShardTransfer,
    abort_shard_transfer: replica_set::AbortShardTransfer,
    search_runtime: Option<Handle>,
    update_runtime: Option<Handle>,
) -> Self {
    let start_time = std::time::Instant::now();
    let stored_version = CollectionVersion::load(path)
        .expect("Can't read collection version")
        .parse()
        .expect("Failed to parse stored collection version as semver");

    let app_version: Version = CollectionVersion::current()
        .parse()
        .expect("Failed to parse current collection version as semver");

    if stored_version > app_version {
        panic!("Collection version is greater than application version");
    }

    if stored_version != app_version {
        if Self::can_upgrade_storage(&stored_version, &app_version) {
            log::info!("Migrating collection {stored_version} -> {app_version}");
            CollectionVersion::save(path)
                .unwrap_or_else(|err| panic!("Can't save collection version {err}"));
        } else {
            log::error!("Cannot upgrade version {stored_version} to {app_version}.");
            panic!("Cannot upgrade version {stored_version} to {app_version}. Try to use older version of Qdrant first.");
        }
    }

    let collection_config = CollectionConfig::load(path).unwrap_or_else(|err| {
        panic!(
            "Can't read collection config due to {}\nat {}",
            err,
            path.to_str().unwrap(),
        )
    });
    collection_config.validate_and_warn();

    let mut shard_holder = ShardHolder::new(path).expect("Can not create shard holder");

    let shared_collection_config = Arc::new(RwLock::new(collection_config.clone()));

    shard_holder
        .load_shards(
            path,
            &collection_id,
            shared_collection_config.clone(),
            shared_storage_config.clone(),
            channel_service.clone(),
            on_replica_failure.clone(),
            abort_shard_transfer.clone(),
            this_peer_id,
            update_runtime.clone().unwrap_or_else(Handle::current),
            search_runtime.clone().unwrap_or_else(Handle::current),
        )
        .await;

    let locked_shard_holder = Arc::new(LockedShardHolder::new(shard_holder));

    let payload_index_schema = Self::load_payload_index_schema(path)
        .expect("Can't load or initialize payload index schema");

    Self {
        id: collection_id.clone(),
        shards_holder: locked_shard_holder,
        collection_config: shared_collection_config,
        payload_index_schema,
        shared_storage_config,
        this_peer_id,
        path: path.to_owned(),
        snapshots_path: snapshots_path.to_owned(),
        channel_service,
        transfer_tasks: Mutex::new(TransferTasksPool::new(collection_id.clone())),
        request_shard_transfer_cb: request_shard_transfer.clone(),
        notify_peer_failure_cb: on_replica_failure,
        abort_shard_transfer_cb: abort_shard_transfer,
        init_time: start_time.elapsed(),
        is_initialized: Arc::new(Default::default()),
        updates_lock: RwLock::new(()),
        update_runtime: update_runtime.unwrap_or_else(Handle::current),
        search_runtime: search_runtime.unwrap_or_else(Handle::current),
    }
}

/// Check if stored version have consequent version.
/// If major version is different, then it is not compatible.
/// If the difference in consecutive versions is greater than 1 in patch,
/// then the collection is not compatible with the current version.
///
/// Example:
///   0.4.0 -> 0.4.1 = true
///   0.4.0 -> 0.4.2 = false
///   0.4.0 -> 0.5.0 = false
///   0.4.0 -> 0.5.1 = false
pub fn can_upgrade_storage(stored: &Version, app: &Version) -> bool {
    if stored.major != app.major {
        return false;
    }
    if stored.minor != app.minor {
        return false;
    }
    if stored.patch + 1 < app.patch {
        return false;
    }
    true
}

