/// Updates quantization config:
/// Saves new params on disk
///
/// After this, `recreate_optimizers_blocking` must be called to create new optimizers using
/// the updated configuration.
pub async fn update_quantization_config_from_diff(
    &self,
    quantization_config_diff: QuantizationConfigDiff,
) -> CollectionResult<()> {
    {
        let mut config = self.collection_config.write().await;
        match quantization_config_diff {
            QuantizationConfigDiff::Scalar(scalar) => {
                config
                    .quantization_config
                    .replace(QuantizationConfig::Scalar(scalar));
            }
            QuantizationConfigDiff::Product(product) => {
                config
                    .quantization_config
                    .replace(QuantizationConfig::Product(product));
            }
            QuantizationConfigDiff::Binary(binary) => {
                config
                    .quantization_config
                    .replace(QuantizationConfig::Binary(binary));
            }
            QuantizationConfigDiff::Disabled(_) => {
                config.quantization_config = None;
            }
        }
    }
    self.collection_config.read().await.save(&self.path)?;
    Ok(())
}

/// Handle replica changes
///
/// add and remove replicas from replica set
pub async fn handle_replica_changes(
    &self,
    replica_changes: Vec<Change>,
) -> CollectionResult<()> {
    if replica_changes.is_empty() {
        return Ok(());
    }
    let read_shard_holder = self.shards_holder.read().await;

    for change in replica_changes {
        match change {
            Change::Remove(shard_id, peer_id) => {
                let replica_set_opt = read_shard_holder.get_shard(&shard_id);
                let replica_set = if let Some(replica_set) = replica_set_opt {
                    replica_set
                } else {
                    return Err(CollectionError::BadRequest {
                        description: format!("Shard {} of {} not found", shard_id, self.name()),
                    });
                };

                let peers = replica_set.peers();

                if !peers.contains_key(&peer_id) {
                    return Err(CollectionError::BadRequest {
                        description: format!(
                            "Peer {peer_id} has no replica of shard {shard_id}"
                        ),
                    });
                }

                if peers.len() == 1 {
                    return Err(CollectionError::BadRequest {
                        description: format!("Shard {shard_id} must have at least one replica"),
                    });
                }

                replica_set.remove_peer(peer_id).await?;
            }
        }
    }
    Ok(())
}

/// Recreate the optimizers on all shards for this collection
///
/// This will stop existing optimizers, and start new ones with new configurations.
///
/// # Blocking
///
/// Partially blocking. Stopping existing optimizers is blocking. Starting new optimizers is
/// not blocking.
pub async fn recreate_optimizers_blocking(&self) -> CollectionResult<()> {
    let shard_holder = self.shards_holder.read().await;
    let updates = shard_holder
        .all_shards()
        .map(|replica_set| replica_set.on_optimizer_config_update());
    future::try_join_all(updates).await?;
    Ok(())
}

pub async fn info(
    &self,
    shard_selection: &ShardSelectorInternal,
) -> CollectionResult<CollectionInfo> {
    let shards_holder = self.shards_holder.read().await;
    let shards = shards_holder.select_shards(shard_selection)?;
    let mut requests: futures::stream::FuturesUnordered<_> = shards
        .into_iter()
        // `info` requests received through internal gRPC *always* have `shard_selection`
        .map(|(shard, _shard_key)| shard.info(shard_selection.is_shard_id()))
        .collect();

    let mut info = match requests.try_next().await? {
        Some(info) => info,
        None => CollectionInfo::empty(self.collection_config.read().await.clone()),
    };

    while let Some(response) = requests.try_next().await? {
        info.status = cmp::max(info.status, response.status);
        info.optimizer_status = cmp::max(info.optimizer_status, response.optimizer_status);
        info.vectors_count = info
            .vectors_count
            .zip(response.vectors_count)
            .map(|(a, b)| a + b);
        info.indexed_vectors_count = info
            .indexed_vectors_count
            .zip(response.indexed_vectors_count)
            .map(|(a, b)| a + b);
        info.points_count = info
            .points_count
            .zip(response.points_count)
            .map(|(a, b)| a + b);
        info.segments_count += response.segments_count;

        for (key, response_schema) in response.payload_schema {
            info.payload_schema
                .entry(key)
                .and_modify(|info_schema| info_schema.points += response_schema.points)
                .or_insert(response_schema);
        }
    }

    Ok(info)
}

pub async fn cluster_info(&self, peer_id: PeerId) -> CollectionResult<CollectionClusterInfo> {
    let shards_holder = self.shards_holder.read().await;
    let shard_count = shards_holder.len();
    let mut local_shards = Vec::new();
    let mut remote_shards = Vec::new();
    let count_request = Arc::new(CountRequestInternal {
        filter: None,
        exact: false, // Don't need exact count of unique ids here, only size estimation
    });
    let shard_to_key = shards_holder.get_shard_id_to_key_mapping();

    // extract shards info
    for (shard_id, replica_set) in shards_holder.get_shards() {
        let shard_id = *shard_id;
        let peers = replica_set.peers();

        if replica_set.has_local_shard().await {
            let state = peers
                .get(&replica_set.this_peer_id())
                .copied()
                .unwrap_or(ReplicaState::Dead);
            let count_result = replica_set
                .count_local(count_request.clone())
                .await
                .unwrap_or_default();
            let points_count = count_result.map(|x| x.count).unwrap_or(0);
            local_shards.push(LocalShardInfo {
                shard_id,
                points_count,
                state,
                shard_key: shard_to_key.get(&shard_id).cloned(),
            })
        }
        for (peer_id, state) in replica_set.peers().into_iter() {
            if peer_id == replica_set.this_peer_id() {
                continue;
            }
            remote_shards.push(RemoteShardInfo {
                shard_id,
                peer_id,
                state,
                shard_key: shard_to_key.get(&shard_id).cloned(),
            });
        }
    }
    let shard_transfers = shards_holder.get_shard_transfer_info();

    // sort by shard_id
    local_shards.sort_by_key(|k| k.shard_id);
    remote_shards.sort_by_key(|k| k.shard_id);

    let info = CollectionClusterInfo {
        peer_id,
        shard_count,
        local_shards,
        remote_shards,
        shard_transfers,
    };
    Ok(info)
}

pub(crate) fn payload_index_file(collection_path: &Path) -> PathBuf {
    collection_path.join(PAYLOAD_INDEX_CONFIG_FILE)
}

pub(crate) fn load_payload_index_schema(
    collection_path: &Path,
) -> CollectionResult<SaveOnDisk<PayloadIndexSchema>> {
    let payload_index_file = Self::payload_index_file(collection_path);
    let schema: SaveOnDisk<PayloadIndexSchema> = SaveOnDisk::load_or_init(payload_index_file)?;
    Ok(schema)
}

pub async fn create_payload_index(
    &self,
    field_name: String,
    field_schema: PayloadFieldSchema,
) -> CollectionResult<Option<UpdateResult>> {
    self.payload_index_schema.write(|schema| {
        schema
            .schema
            .insert(field_name.clone(), field_schema.clone());
    })?;

    // This operation might be redundant, if we also create index as a regular collection op,
    // but it looks better in long term to also have it here, so
    // the creation of payload index may be eventually completely converted
    // into the consensus operation
    let create_index_operation = CollectionUpdateOperations::FieldIndexOperation(
        FieldIndexOperations::CreateIndex(CreateIndex {
            field_name,
            field_schema: Some(field_schema),
        }),
    );

    // This function is called from consensus, so we can't afford to wait for the result
    // as indexation may take a long time
    let wait = false;

    let result = self.update_all_local(create_index_operation, wait).await?;

    Ok(result)
}

pub async fn drop_payload_index(
    &self,
    field_name: String,
) -> CollectionResult<Option<UpdateResult>> {
    self.payload_index_schema.write(|schema| {
        schema.schema.remove(&field_name);
    })?;

    let delete_index_operation = CollectionUpdateOperations::FieldIndexOperation(
        FieldIndexOperations::DeleteIndex(field_name),
    );

    let result = self.update_all_local(delete_index_operation, false).await?;

    Ok(result)
}

pub async fn apply_state(
    &self,
    state: State,
    this_peer_id: PeerId,
    abort_transfer: impl FnMut(ShardTransfer),
) -> CollectionResult<()> {
    self.apply_config(state.config).await?;
    self.apply_shard_transfers(state.transfers, this_peer_id, abort_transfer)
        .await?;
    self.apply_shard_info(state.shards, state.shards_key_mapping)
        .await?;
    self.apply_payload_index_schema(state.payload_index_schema)
        .await?;
    Ok(())
}

async fn apply_shard_transfers(
    &self,
    shard_transfers: HashSet<ShardTransfer>,
    this_peer_id: PeerId,
    mut abort_transfer: impl FnMut(ShardTransfer),
) -> CollectionResult<()> {
    let old_transfers = self
        .shards_holder
        .read()
        .await
        .shard_transfers
        .read()
        .clone();
    for transfer in shard_transfers.difference(&old_transfers) {
        if transfer.from == this_peer_id {
            // Abort transfer as sender should not learn about the transfer from snapshot
            // If this happens it mean the sender is probably outdated and it is safer to abort
            abort_transfer(transfer.clone())
        }
    }
    self.shards_holder
        .write()
        .await
        .shard_transfers
        .write(|transfers| *transfers = shard_transfers)?;
    Ok(())
}

async fn apply_config(&self, new_config: CollectionConfig) -> CollectionResult<()> {
    log::warn!("Applying only optimizers config snapshot. Other config updates are not yet implemented.");
    self.update_optimizer_params(new_config.optimizer_config)
        .await?;

    // Update replication factor
    {
        let mut config = self.collection_config.write().await;
        config.params.replication_factor = new_config.params.replication_factor;
        config.params.write_consistency_factor = new_config.params.write_consistency_factor;
    }

    self.recreate_optimizers_blocking().await?;

    Ok(())
}

async fn apply_shard_info(
    &self,
    shards: HashMap<ShardId, ShardInfo>,
    shards_key_mapping: ShardKeyMapping,
) -> CollectionResult<()> {
    let mut extra_shards: HashMap<ShardId, ShardReplicaSet> = HashMap::new();

    let shard_ids = shards.keys().copied().collect::<HashSet<_>>();

    // There are two components, where shard-related info is stored:
    // Shard objects themselves and shard_holder, that maps shard_keys to shards.

    // On the first state of the update, we update state of shards themselves
    // and create new shards if needed

    for (shard_id, shard_info) in shards {
        match self.shards_holder.read().await.get_shard(&shard_id) {
            Some(replica_set) => replica_set.apply_state(shard_info.replicas).await?,
            None => {
                let shard_replicas: Vec<_> = shard_info.replicas.keys().copied().collect();
                let replica_set = self.create_replica_set(shard_id, &shard_replicas).await?;
                replica_set.apply_state(shard_info.replicas).await?;
                extra_shards.insert(shard_id, replica_set);
            }
        }
    }

    // On the second step, we register missing shards and remove extra shards

    self.shards_holder
        .write()
        .await
        .apply_shards_state(shard_ids, shards_key_mapping, extra_shards)
        .await
}

async fn apply_payload_index_schema(
    &self,
    payload_index_schema: PayloadIndexSchema,
) -> CollectionResult<()> {
    let state = self.state().await;

    for field_name in state.payload_index_schema.schema.keys() {
        if !payload_index_schema.schema.contains_key(field_name) {
            self.drop_payload_index(field_name.clone()).await?;
        }
    }

    for (field_name, field_schema) in payload_index_schema.schema {
        self.create_payload_index(field_name, field_schema).await?;
    }
    Ok(())
}

pub async fn search(
    &self,
    request: CoreSearchRequest,
    read_consistency: Option<ReadConsistency>,
    shard_selection: &ShardSelectorInternal,
    timeout: Option<Duration>,
) -> CollectionResult<Vec<ScoredPoint>> {
    if request.limit == 0 {
        return Ok(vec![]);
    }
    // search is a special case of search_batch with a single batch
    let request_batch = CoreSearchRequestBatch {
        searches: vec![request],
    };
    let results = self
        .do_core_search_batch(request_batch, read_consistency, shard_selection, timeout)
        .await?;
    Ok(results.into_iter().next().unwrap())
}

pub async fn core_search_batch(
    &self,
    request: CoreSearchRequestBatch,
    read_consistency: Option<ReadConsistency>,
    shard_selection: ShardSelectorInternal,
    timeout: Option<Duration>,
) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
    // shortcuts batch if all requests with limit=0
    if request.searches.iter().all(|s| s.limit == 0) {
        return Ok(vec![]);
    }
    // A factor which determines if we need to use the 2-step search or not
    // Should be adjusted based on usage statistics.
    const PAYLOAD_TRANSFERS_FACTOR_THRESHOLD: usize = 10;

    let is_payload_required = request.searches.iter().all(|s| {
        s.with_payload
            .clone()
            .map(|p| p.is_required())
            .unwrap_or_default()
    });
    let with_vectors = request.searches.iter().all(|s| {
        s.with_vector
            .as_ref()
            .map(|wv| wv.is_some())
            .unwrap_or(false)
    });

    let metadata_required = is_payload_required || with_vectors;

    let sum_limits: usize = request.searches.iter().map(|s| s.limit).sum();
    let sum_offsets: usize = request.searches.iter().map(|s| s.offset).sum();

    // Number of records we need to retrieve to fill the search result.
    let require_transfers = self.shards_holder.read().await.len() * (sum_limits + sum_offsets);
    // Actually used number of records.
    let used_transfers = sum_limits;

    let is_required_transfer_large_enough =
        require_transfers > used_transfers * PAYLOAD_TRANSFERS_FACTOR_THRESHOLD;

    if metadata_required && is_required_transfer_large_enough {
        // If there is a significant offset, we need to retrieve the whole result
        // set without payload first and then retrieve the payload.
        // It is required to do this because the payload might be too large to send over the
        // network.
        let mut without_payload_requests = Vec::with_capacity(request.searches.len());
        for search in &request.searches {
            let mut without_payload_request = search.clone();
            without_payload_request.with_payload = None;
            without_payload_request.with_vector = None;
            without_payload_requests.push(without_payload_request);
        }
        let without_payload_batch = CoreSearchRequestBatch {
            searches: without_payload_requests,
        };
        let without_payload_results = self
            .do_core_search_batch(
                without_payload_batch,
                read_consistency,
                &shard_selection,
                timeout,
            )
            .await?;
        let filled_results = without_payload_results
            .into_iter()
            .zip(request.clone().searches.into_iter())
            .map(|(without_payload_result, req)| {
                self.fill_search_result_with_payload(
                    without_payload_result,
                    req.with_payload.clone(),
                    req.with_vector.unwrap_or_default(),
                    read_consistency,
                    &shard_selection,
                )
            });
        future::try_join_all(filled_results).await
    } else {
        let result = self
            .do_core_search_batch(request, read_consistency, &shard_selection, timeout)
            .await?;
        Ok(result)
    }
}

async fn do_core_search_batch(
    &self,
    request: CoreSearchRequestBatch,
    read_consistency: Option<ReadConsistency>,
    shard_selection: &ShardSelectorInternal,
    timeout: Option<Duration>,
) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
    let request = Arc::new(request);

    // query all shards concurrently
    let all_searches_res = {
        let shard_holder = self.shards_holder.read().await;
        let target_shards = shard_holder.select_shards(shard_selection)?;
        let all_searches = target_shards.iter().map(|(shard, shard_key)| {
            let shard_key = shard_key.cloned();
            shard
                .core_search(
                    Arc::clone(&request),
                    read_consistency,
                    shard_selection.is_shard_id(),
                    timeout,
                )
                .and_then(move |mut records| async move {
                    if shard_key.is_none() {
                        return Ok(records);
                    }
                    for batch in &mut records {
                        for point in batch {
                            point.shard_key = shard_key.clone();
                        }
                    }
                    Ok(records)
                })
        });
        future::try_join_all(all_searches).await?
    };

    self.merge_from_shards(all_searches_res, request, !shard_selection.is_shard_id())
        .await
}

pub(crate) async fn fill_search_result_with_payload(
    &self,
    search_result: Vec<ScoredPoint>,
    with_payload: Option<WithPayloadInterface>,
    with_vector: WithVector,
    read_consistency: Option<ReadConsistency>,
    shard_selection: &ShardSelectorInternal,
) -> CollectionResult<Vec<ScoredPoint>> {
    // short-circuit if not needed
    if let (&Some(WithPayloadInterface::Bool(false)), &WithVector::Bool(false)) =
        (&with_payload, &with_vector)
    {
        return Ok(search_result
            .into_iter()
            .map(|point| ScoredPoint {
                payload: None,
                vector: None,
                ..point
            })
            .collect());
    };

    let retrieve_request = PointRequestInternal {
        ids: search_result.iter().map(|x| x.id).collect(),
        with_payload,
        with_vector,
    };
    let retrieved_records = self
        .retrieve(retrieve_request, read_consistency, shard_selection)
        .await?;
    let mut records_map: HashMap<ExtendedPointId, Record> = retrieved_records
        .into_iter()
        .map(|rec| (rec.id, rec))
        .collect();
    let enriched_result = search_result
        .into_iter()
        .filter_map(|mut scored_point| {
            // Points might get deleted between search and retrieve.
            // But it's not a problem, because we don't want to return deleted points.
            // So we just filter out them.
            records_map.remove(&scored_point.id).map(|record| {
                scored_point.payload = record.payload;
                scored_point.vector = record.vector;
                scored_point
            })
        })
        .collect();
    Ok(enriched_result)
}

async fn merge_from_shards(
    &self,
    mut all_searches_res: Vec<Vec<Vec<ScoredPoint>>>,
    request: Arc<CoreSearchRequestBatch>,
    is_client_request: bool,
) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
    let batch_size = request.searches.len();

    // merge results from shards in order
    let mut merged_results: Vec<Vec<ScoredPoint>> = vec![vec![]; batch_size];
    for shard_searches_results in all_searches_res.iter_mut() {
        for (index, shard_searches_result) in shard_searches_results.iter_mut().enumerate() {
            merged_results[index].append(shard_searches_result)
        }
    }
    let collection_params = self.collection_config.read().await.params.clone();
    let top_results: Vec<_> = merged_results
        .into_iter()
        .zip(request.searches.iter())
        .map(|(res, request)| {
            let order = match &request.query {
                QueryEnum::Nearest(_) => collection_params
                    .get_distance(request.query.get_vector_name())?
                    .distance_order(),

                // Score comes from special handling of the distances in a way that it doesn't
                // directly represent distance anymore, so the order is always `LargeBetter`
                QueryEnum::Discover(_)
                | QueryEnum::Context(_)
                | QueryEnum::RecommendBestScore(_) => Order::LargeBetter,
            };

            let mut top_res = match order {
                Order::LargeBetter => {
                    tools::peek_top_largest_iterable(res, request.limit + request.offset)
                }
                Order::SmallBetter => {
                    tools::peek_top_smallest_iterable(res, request.limit + request.offset)
                }
            };
            // Remove `offset` from top result only for client requests
            // to avoid applying `offset` twice in distributed mode.
            if is_client_request && request.offset > 0 {
                if top_res.len() >= request.offset {
                    // Panics if the end point > length of the vector.
                    top_res.drain(..request.offset);
                } else {
                    top_res.clear()
                }
            }
            Ok(top_res)
        })
        .collect::<CollectionResult<Vec<_>>>()?;

    Ok(top_results)
}

pub async fn list_snapshots(&self) -> CollectionResult<Vec<SnapshotDescription>> {
    snapshot_ops::list_snapshots_in_directory(&self.snapshots_path).await
}

/// Creates a snapshot of the collection.
///
/// The snapshot is created in three steps:
/// 1. Create a temporary directory and create a snapshot of each shard in it.
/// 2. Archive the temporary directory into a single file.
/// 3. Move the archive to the final location.
///
/// # Arguments
///
/// * `global_temp_dir`: directory used to host snapshots while they are being created
/// * `this_peer_id`: current peer id
///
/// returns: Result<SnapshotDescription, CollectionError>
pub async fn create_snapshot(
    &self,
    global_temp_dir: &Path,
    this_peer_id: PeerId,
) -> CollectionResult<SnapshotDescription> {
    let snapshot_name = format!(
        "{}-{}-{}.snapshot",
        self.name(),
        this_peer_id,
        chrono::Utc::now().format("%Y-%m-%d-%H-%M-%S")
    );

    // Final location of snapshot
    let snapshot_path = self.snapshots_path.join(&snapshot_name);
    log::info!(
        "Creating collection snapshot {} into {:?}",
        snapshot_name,
        snapshot_path
    );

    // Dedicated temporary directory for this snapshot (deleted on drop)
    let snapshot_temp_target_dir = tempfile::Builder::new()
        .prefix(&format!("{snapshot_name}-target-"))
        .tempdir_in(global_temp_dir)?;

    let snapshot_temp_target_dir_path = snapshot_temp_target_dir.path().to_path_buf();
    // Create snapshot of each shard
    {
        let snapshot_temp_temp_dir = tempfile::Builder::new()
            .prefix(&format!("{snapshot_name}-temp-"))
            .tempdir_in(global_temp_dir)?;
        let shards_holder = self.shards_holder.read().await;
        // Create snapshot of each shard
        for (shard_id, replica_set) in shards_holder.get_shards() {
            let shard_snapshot_path = shard_versioning::versioned_shard_path(
                &snapshot_temp_target_dir_path,
                *shard_id,
                0,
            );
            fs::create_dir_all(&shard_snapshot_path).await?;
            // If node is listener, we can save whatever currently is in the storage
            let save_wal = self.shared_storage_config.node_type != NodeType::Listener;
            replica_set
                .create_snapshot(
                    snapshot_temp_temp_dir.path(),
                    &shard_snapshot_path,
                    save_wal,
                )
                .await?;
        }
    }

    // Save collection config and version
    CollectionVersion::save(&snapshot_temp_target_dir_path)?;
    self.collection_config
        .read()
        .await
        .save(&snapshot_temp_target_dir_path)?;

    self.shards_holder
        .read()
        .await
        .save_key_mapping_to_dir(&snapshot_temp_target_dir_path)?;

    let payload_index_schema_tmp_path =
        Self::payload_index_file(&snapshot_temp_target_dir_path);
    self.payload_index_schema
        .save_to(&payload_index_schema_tmp_path)?;

    // Dedicated temporary file for archiving this snapshot (deleted on drop)
    let mut snapshot_temp_arc_file = tempfile::Builder::new()
        .prefix(&format!("{snapshot_name}-arc-"))
        .tempfile_in(global_temp_dir)?;

    // Archive snapshot folder into a single file
    log::debug!("Archiving snapshot {:?}", &snapshot_temp_target_dir_path);
    let archiving = tokio::task::spawn_blocking(move || -> CollectionResult<_> {
        let mut builder = tar::Builder::new(snapshot_temp_arc_file.as_file_mut());
        // archive recursively collection directory `snapshot_path_with_arc_extension` into `snapshot_path`
        builder.append_dir_all(".", &snapshot_temp_target_dir_path)?;
        builder.finish()?;
        drop(builder);
        // return ownership of the file
        Ok(snapshot_temp_arc_file)
    });
    snapshot_temp_arc_file = archiving.await??;

    // Move snapshot to permanent location.
    // We can't move right away, because snapshot folder can be on another mounting point.
    // We can't copy to the target location directly, because copy is not atomic.
    // So we copy to the final location with a temporary name and then rename atomically.
    let snapshot_path_tmp_move = snapshot_path.with_extension("tmp");

    // Ensure that the temporary file is deleted on error
    let _temp_path = TempPath::from_path(&snapshot_path_tmp_move);
    fs::copy(&snapshot_temp_arc_file.path(), &snapshot_path_tmp_move).await?;
    fs::rename(&snapshot_path_tmp_move, &snapshot_path).await?;

    log::info!(
        "Collection snapshot {} completed into {:?}",
        snapshot_name,
        snapshot_path
    );
    snapshot_ops::get_snapshot_description(&snapshot_path).await
}

/// Restore collection from snapshot
///
/// This method performs blocking IO.
pub fn restore_snapshot(
    snapshot_path: &Path,
    target_dir: &Path,
    this_peer_id: PeerId,
    is_distributed: bool,
) -> CollectionResult<()> {
    // decompress archive
    let archive_file = std::fs::File::open(snapshot_path)?;
    let mut ar = tar::Archive::new(archive_file);
    ar.unpack(target_dir)?;

    let config = CollectionConfig::load(target_dir)?;
    config.validate_and_warn();
    let configured_shards = config.params.shard_number.get();

    let shard_ids_list: Vec<_> = match config.params.sharding_method.unwrap_or_default() {
        ShardingMethod::Auto => (0..configured_shards).collect(),
        ShardingMethod::Custom => {
            // Load shard mapping from disk
            let mapping_path = target_dir.join(SHARD_KEY_MAPPING_FILE);
            debug_assert!(
                mapping_path.exists(),
                "Shard mapping file must exist once custom sharding is used"
            );
            if !mapping_path.exists() {
                Vec::new()
            } else {
                let shard_key_mapping: ShardKeyMapping = read_json(&mapping_path)?;
                shard_key_mapping
                    .values()
                    .flat_map(|v| v.iter())
                    .copied()
                    .collect()
            }
        }
    };

    // Check that all shard ids are unique
    debug_assert_eq!(
        shard_ids_list.len(),
        shard_ids_list.iter().collect::<HashSet<_>>().len(),
        "Shard mapping must contain all shards",
    );

    for shard_id in shard_ids_list {
        let shard_path = shard_versioning::versioned_shard_path(target_dir, shard_id, 0);
        let shard_config_opt = ShardConfig::load(&shard_path)?;
        if let Some(shard_config) = shard_config_opt {
            match shard_config.r#type {
                shard_config::ShardType::Local => LocalShard::restore_snapshot(&shard_path)?,
                shard_config::ShardType::Remote { .. } => {
                    RemoteShard::restore_snapshot(&shard_path)
                }
                shard_config::ShardType::Temporary => {}
                shard_config::ShardType::ReplicaSet { .. } => {
                    ShardReplicaSet::restore_snapshot(
                        &shard_path,
                        this_peer_id,
                        is_distributed,
                    )?
                }
            }
        } else {
            return Err(CollectionError::service_error(format!(
                "Can't read shard config at {}",
                shard_path.display()
            )));
        }
    }

    Ok(())
}

