pub fn new(dir: &str, wal_options: WalOptions) -> Result<SerdeWal<R>> {
    let wal = Wal::with_options(dir, &wal_options)
        .map_err(|err| WalError::InitWalError(format!("{err:?}")))?;

    let first_index_path = Path::new(dir).join(FIRST_INDEX_FILE);

    let first_index = if first_index_path.exists() {
        let wal_state: WalState = read_json(&first_index_path).map_err(|err| {
            WalError::InitWalError(format!("failed to read first-index file: {err}"))
        })?;

        let first_index = wal_state
            .ack_index
            .max(wal.first_index())
            .min(wal.last_index());
        Some(first_index)
    } else {
        None
    };

    Ok(SerdeWal {
        record: PhantomData,
        wal,
        options: wal_options,
        first_index,
    })
}

/// Write a record to the WAL but does guarantee durability.
pub fn write(&mut self, entity: &R) -> Result<u64> {
    // ToDo: Replace back to faster rmp, once this https://github.com/serde-rs/serde/issues/2055 solved
    let binary_entity = serde_cbor::to_vec(&entity).unwrap();
    self.wal
        .append(&binary_entity)
        .map_err(|err| WalError::WriteWalError(format!("{err:?}")))
}

pub fn read_all(&'s self) -> impl Iterator<Item = (u64, R)> + 's {
    self.read(self.first_index())
}

pub fn is_empty(&self) -> bool {
    self.len() == 0
}

pub fn len(&self) -> u64 {
    self.wal
        .num_entries()
        .saturating_sub(self.truncated_prefix_entries_num())
}

fn truncated_prefix_entries_num(&self) -> u64 {
    self.first_index().saturating_sub(self.wal.first_index())
}

pub fn read(&'s self, start_from: u64) -> impl Iterator<Item = (u64, R)> + 's {
    let first_index = self.first_index();
    let len = self.len();

    (start_from..(first_index + len)).map(move |idx| {
        let record_bin = self.wal.entry(idx).expect("Can't read entry from WAL");
        let record: R = serde_cbor::from_slice(&record_bin)
            .or_else(|_err| rmp_serde::from_slice(&record_bin))
            .expect("Can't deserialize entry, probably corrupted WAL on version mismatch");
        (idx, record)
    })
}

/// Inform WAL, that records older than `until_index` are no longer required.
/// If it is possible, WAL will remove unused files.
///
/// # Arguments
///
/// * `until_index` - the newest no longer required record sequence number
///
pub fn ack(&mut self, until_index: u64) -> Result<()> {
    // Truncate WAL
    self.wal
        .prefix_truncate(until_index)
        .map_err(|err| WalError::TruncateWalError(format!("{err:?}")))?;

    // Acknowledge index should not decrease
    let minimal_first_index = self.first_index.unwrap_or(self.wal.first_index());
    let new_first_index = Some(
        until_index
            .max(minimal_first_index)
            .min(self.wal.last_index()),
    );
    // Update current `first_index`
    if self.first_index != new_first_index {
        self.first_index = new_first_index;
        // Persist current `first_index` value on disk
        // TODO: Should we log this error and continue instead of failing?
        self.flush_first_index()?;
    }

    Ok(())
}

fn flush_first_index(&self) -> Result<()> {
    let Some(first_index) = self.first_index else {
        return Ok(());
    };

    atomic_save_json(
        &self.path().join(FIRST_INDEX_FILE),
        &WalState::new(first_index),
    )
    .map_err(|err| {
        WalError::TruncateWalError(format!("failed to write first-index file: {err:?}"))
    })?;

    Ok(())
}

pub fn flush(&mut self) -> Result<()> {
    self.wal
        .flush_open_segment()
        .map_err(|err| WalError::WriteWalError(format!("{err:?}")))
}

pub fn flush_async(&mut self) -> JoinHandle<std::io::Result<()>> {
    self.wal.flush_open_segment_async()
}

pub fn path(&self) -> &Path {
    self.wal.path()
}

pub fn first_index(&self) -> u64 {
    self.first_index.unwrap_or_else(|| self.wal.first_index())
}

pub fn last_index(&self) -> u64 {
    self.wal.last_index()
}

pub fn segment_capacity(&self) -> usize {
    self.options.segment_capacity
}

pub fn run_workers(&mut self, update_receiver: Receiver<UpdateSignal>) {
    let (tx, rx) = mpsc::channel(self.shared_storage_config.update_queue_size);
    self.optimizer_worker = Some(self.runtime_handle.spawn(Self::optimization_worker_fn(
        self.optimizers.clone(),
        tx.clone(),
        rx,
        self.segments.clone(),
        self.wal.clone(),
        self.optimization_handles.clone(),
        self.optimizers_log.clone(),
        self.max_optimization_threads,
    )));
    self.update_worker = Some(self.runtime_handle.spawn(Self::update_worker_fn(
        update_receiver,
        tx,
        self.wal.clone(),
        self.segments.clone(),
    )));
    let (flush_tx, flush_rx) = oneshot::channel();
    self.flush_worker = Some(self.runtime_handle.spawn(Self::flush_worker(
        self.segments.clone(),
        self.wal.clone(),
        self.max_ack_version.clone(),
        self.flush_interval_sec,
        flush_rx,
    )));
    self.flush_stop = Some(flush_tx);
}

pub fn stop_flush_worker(&mut self) {
    if let Some(flush_stop) = self.flush_stop.take() {
        if let Err(()) = flush_stop.send(()) {
            warn!("Failed to stop flush worker as it is already stopped.");
        }
    }
}

/// Gracefully wait before all optimizations stop
/// If some optimization is in progress - it will be finished before shutdown.
pub async fn wait_workers_stops(&mut self) -> CollectionResult<()> {
    let maybe_handle = self.update_worker.take();
    if let Some(handle) = maybe_handle {
        handle.await?;
    }
    let maybe_handle = self.optimizer_worker.take();
    if let Some(handle) = maybe_handle {
        handle.await?;
    }
    let maybe_handle = self.flush_worker.take();
    if let Some(handle) = maybe_handle {
        handle.await?;
    }

    let mut opt_handles_guard = self.optimization_handles.lock().await;
    let opt_handles = std::mem::take(&mut *opt_handles_guard);
    let stopping_handles = opt_handles
        .into_iter()
        .filter_map(|h| h.stop())
        .collect_vec();

    for res in stopping_handles {
        res.await?;
    }

    Ok(())
}

/// Checks if there are any failed operations.
/// If so - attempts to re-apply all failed operations.
async fn try_recover(segments: LockedSegmentHolder, wal: LockedWal) -> CollectionResult<usize> {
    // Try to re-apply everything starting from the first failed operation
    let first_failed_operation_option = segments.read().failed_operation.iter().cloned().min();
    match first_failed_operation_option {
        None => {}
        Some(first_failed_op) => {
            let wal_lock = wal.lock();
            for (op_num, operation) in wal_lock.read(first_failed_op) {
                CollectionUpdater::update(&segments, op_num, operation)?;
            }
        }
    };
    Ok(0)
}

/// Checks conditions for all optimizers until there is no suggested segment
/// Starts a task for each optimization
/// Returns handles for started tasks
pub(crate) fn launch_optimization<F>(
    optimizers: Arc<Vec<Arc<Optimizer>>>,
    optimizers_log: Arc<Mutex<TrackerLog>>,
    segments: LockedSegmentHolder,
    callback: F,
) -> Vec<StoppableTaskHandle<bool>>
where
    F: FnOnce(bool),
    F: Send + 'static,
    F: Clone,
{
    let mut scheduled_segment_ids: HashSet<_> = Default::default();
    let mut handles = vec![];
    for optimizer in optimizers.iter() {
        loop {
            let nonoptimal_segment_ids =
                optimizer.check_condition(segments.clone(), &scheduled_segment_ids);
            if nonoptimal_segment_ids.is_empty() {
                break;
            }

            let optimizer = optimizer.clone();
            let optimizers_log = optimizers_log.clone();
            let segments = segments.clone();
            let nsi = nonoptimal_segment_ids.clone();
            scheduled_segment_ids.extend(&nsi);
            let callback = callback.clone();

            let handle = spawn_stoppable(
                // Stoppable task
                {
                    let segments = segments.clone();
                    move |stopped| {
                        // Track optimizer status
                        let tracker = Tracker::start(optimizer.as_ref().name(), nsi.clone());
                        let tracker_handle = tracker.handle();
                        optimizers_log.lock().register(tracker);

                        // Optimize and handle result
                        match optimizer.as_ref().optimize(segments.clone(), nsi, stopped) {
                            // Perform some actions when optimization if finished
                            Ok(result) => {
                                tracker_handle.update(TrackerStatus::Done);
                                callback(result);
                                result
                            }
                            // Handle and report errors
                            Err(error) => match error {
                                CollectionError::Cancelled { description } => {
                                    debug!("Optimization cancelled - {}", description);
                                    tracker_handle
                                        .update(TrackerStatus::Cancelled(description));
                                    false
                                }
                                _ => {
                                    segments.write().report_optimizer_error(error.clone());

                                    // Error of the optimization can not be handled by API user
                                    // It is only possible to fix after full restart,
                                    // so the best available action here is to stop whole
                                    // optimization thread and log the error
                                    log::error!("Optimization error: {}", error);

                                    tracker_handle
                                        .update(TrackerStatus::Error(error.to_string()));

                                    panic!("Optimization error: {error}");
                                }
                            },
                        }
                    }
                },
                // Panic handler
                Some(Box::new(move |panic_payload| {
                    let message = panic::downcast_str(&panic_payload).unwrap_or("");
                    let separator = if !message.is_empty() { ": " } else { "" };

                    warn!(
                        "Optimization task panicked, collection may be in unstable state\
                         {separator}{message}"
                    );

                    segments
                        .write()
                        .report_optimizer_error(CollectionError::service_error(format!(
                            "Optimization task panicked{separator}{message}"
                        )));
                })),
            );
            handles.push(handle);
        }
    }
    handles
}

pub(crate) async fn process_optimization(
    optimizers: Arc<Vec<Arc<Optimizer>>>,
    segments: LockedSegmentHolder,
    optimization_handles: Arc<TokioMutex<Vec<StoppableTaskHandle<bool>>>>,
    optimizers_log: Arc<Mutex<TrackerLog>>,
    sender: Sender<OptimizerSignal>,
) {
    let mut new_handles = Self::launch_optimization(
        optimizers.clone(),
        optimizers_log,
        segments.clone(),
        move |_optimization_result| {
            // After optimization is finished, we still need to check if there are
            // some further optimizations possible.
            // If receiver is already dead - we do not care.
            // If channel is full - optimization will be triggered by some other signal
            let _ = sender.try_send(OptimizerSignal::Nop);
        },
    );
    let mut handles = optimization_handles.lock().await;
    handles.append(&mut new_handles);
}

/// Cleanup finalized optimization task handles
///
/// This finds and removes completed tasks from our list of optimization handles.
/// It also propagates any panics (and unknown errors) so we properly handle them if desired.
///
/// It is essential to call this every once in a while for handling panics in time.
async fn cleanup_optimization_handles(
    optimization_handles: Arc<TokioMutex<Vec<StoppableTaskHandle<bool>>>>,
) {
    // Remove finished handles
    let finished_handles: Vec<_> = {
        let mut handles = optimization_handles.lock().await;
        (0..handles.len())
            .filter(|i| handles[*i].is_finished())
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .map(|i| handles.remove(i))
            .collect()
    };

    // Finalize all finished handles to propagate panics
    for handle in finished_handles {
        handle.join_and_handle_panic().await;
    }
}

#[allow(clippy::too_many_arguments)]
async fn optimization_worker_fn(
    optimizers: Arc<Vec<Arc<Optimizer>>>,
    sender: Sender<OptimizerSignal>,
    mut receiver: Receiver<OptimizerSignal>,
    segments: LockedSegmentHolder,
    wal: LockedWal,
    optimization_handles: Arc<TokioMutex<Vec<StoppableTaskHandle<bool>>>>,
    optimizers_log: Arc<Mutex<TrackerLog>>,
    max_handles: usize,
) {
    loop {
        let receiver = timeout(OPTIMIZER_CLEANUP_INTERVAL, receiver.recv());
        let result = receiver.await;

        // Always clean up on any signal
        Self::cleanup_optimization_handles(optimization_handles.clone()).await;

        match result {
            // Channel closed or stop signal
            Ok(None | Some(OptimizerSignal::Stop)) => break,
            // Clean up interval
            Err(Elapsed { .. }) => continue,
            // Optimizer signal
            Ok(Some(signal @ (OptimizerSignal::Nop | OptimizerSignal::Operation(_)))) => {
                // If not forcing with Nop, wait on next signal if we have too many handles
                if signal != OptimizerSignal::Nop
                    && optimization_handles.lock().await.len() >= max_handles
                {
                    continue;
                }

                if Self::try_recover(segments.clone(), wal.clone())
                    .await
                    .is_err()
                {
                    continue;
                }
                Self::process_optimization(
                    optimizers.clone(),
                    segments.clone(),
                    optimization_handles.clone(),
                    optimizers_log.clone(),
                    sender.clone(),
                )
                .await;
            }
        }
    }
}

async fn update_worker_fn(
    mut receiver: Receiver<UpdateSignal>,
    optimize_sender: Sender<OptimizerSignal>,
    wal: LockedWal,
    segments: LockedSegmentHolder,
) {
    while let Some(signal) = receiver.recv().await {
        match signal {
            UpdateSignal::Operation(OperationData {
                op_num,
                operation,
                sender,
                wait,
            }) => {
                let flush_res = if wait {
                    wal.lock().flush().map_err(|err| {
                        CollectionError::service_error(format!(
                            "Can't flush WAL before operation {} - {}",
                            op_num, err
                        ))
                    })
                } else {
                    Ok(())
                };

                let operation_result = flush_res
                    .and_then(|_| CollectionUpdater::update(&segments, op_num, operation));

                let res = match operation_result {
                    Ok(update_res) => optimize_sender
                        .send(OptimizerSignal::Operation(op_num))
                        .await
                        .and(Ok(update_res))
                        .map_err(|send_err| send_err.into()),
                    Err(err) => Err(err),
                };

                if let Some(feedback) = sender {
                    feedback.send(res).unwrap_or_else(|_| {
                        info!(
                            "Can't report operation {} result. Assume already not required",
                            op_num
                        );
                    });
                };
            }
            UpdateSignal::Stop => {
                optimize_sender
                    .send(OptimizerSignal::Stop)
                    .await
                    .unwrap_or_else(|_| debug!("Optimizer already stopped"));
                break;
            }
            UpdateSignal::Nop => optimize_sender
                .send(OptimizerSignal::Nop)
                .await
                .unwrap_or_else(|_| {
                    info!(
                        "Can't notify optimizers, assume process is dead. Restart is required"
                    );
                }),
            UpdateSignal::Plunger(callback_sender) => {
                callback_sender.send(()).unwrap_or_else(|_| {
                    debug!("Can't notify sender, assume nobody is waiting anymore");
                });
            }
        }
    }
    // Transmitter was destroyed
    optimize_sender
        .send(OptimizerSignal::Stop)
        .await
        .unwrap_or_else(|_| debug!("Optimizer already stopped"));
}

async fn flush_worker(
    segments: LockedSegmentHolder,
    wal: LockedWal,
    max_ack: Arc<AtomicU64>,
    flush_interval_sec: u64,
    mut stop_receiver: oneshot::Receiver<()>,
) {
    loop {
        // Stop flush worker on signal or if sender was dropped
        // Even if timer did not finish
        tokio::select! {
            _ = tokio::time::sleep(Duration::from_secs(flush_interval_sec)) => {},
            _ = &mut stop_receiver => {
                debug!("Stopping flush worker.");
                return;
            }
        }

        trace!("Attempting flushing");
        let wal_flash_job = wal.lock().flush_async();

        if let Err(err) = wal_flash_job.join() {
            error!("Failed to flush wal: {:?}", err);
            segments
                .write()
                .report_optimizer_error(WalError::WriteWalError(format!(
                    "WAL flush error: {err:?}"
                )));
            continue;
        }

        let confirmed_version = Self::flush_segments(segments.clone());
        let confirmed_version = match confirmed_version {
            Ok(version) => version,
            Err(err) => {
                error!("Failed to flush: {err}");
                segments.write().report_optimizer_error(err);
                continue;
            }
        };

        // Acknowledge confirmed version in WAL, but don't exceed specified maximum
        // This is to prevent truncating WAL entries that may still be used by other things
        // such as the queue proxy shard.
        // Default maximum ack version is `u64::MAX` to allow acknowledging all confirmed.
        let max_ack = max_ack.load(std::sync::atomic::Ordering::Relaxed);
        if confirmed_version > max_ack {
            trace!("Acknowledging message {max_ack} in WAL, {confirmed_version} is already confirmed but max_ack_version is set");
        }
        let ack = confirmed_version.min(max_ack);

        if let Err(err) = wal.lock().ack(ack) {
            segments.write().report_optimizer_error(err);
        }
    }
}

/// Returns confirmed version after flush of all segments
///
/// # Errors
/// Returns an error on flush failure
fn flush_segments(segments: LockedSegmentHolder) -> OperationResult<SeqNumberType> {
    let read_segments = segments.read();
    let flushed_version = read_segments.flush_all(false)?;
    Ok(match read_segments.failed_operation.iter().cloned().min() {
        None => flushed_version,
        Some(failed_operation) => min(failed_operation, flushed_version),
    })
}

pub fn load_or_init(path: impl Into<PathBuf>) -> Result<Self, Error> {
    let path: PathBuf = path.into();
    let data = if path.exists() {
        let file = File::open(&path)?;
        serde_json::from_reader(&file)?
    } else {
        Default::default()
    };
    Ok(Self {
        change_notification: Condvar::new(),
        notification_lock: Default::default(),
        data: RwLock::new(data),
        path,
    })
}

/// Wait for a condition on data to be true.
///
/// Returns `true` if condition is true, `false` if timed out.
#[must_use]
pub fn wait_for<F>(&self, check: F, timeout: Duration) -> bool
where
    F: Fn(&T) -> bool,
{
    let start = std::time::Instant::now();
    while start.elapsed() < timeout {
        let mut data_read_guard = self.data.read();
        if check(&data_read_guard) {
            return true;
        }
        let notification_guard = self.notification_lock.lock();
        // Based on https://github.com/Amanieu/parking_lot/issues/165
        RwLockReadGuard::unlocked(&mut data_read_guard, || {
            // Move the guard in so it gets unlocked before we re-lock g
            let mut guard = notification_guard;
            self.change_notification.wait_for(&mut guard, timeout);
        });
    }
    false
}

/// Perform an operation over the stored data,
/// persisting the result to disk if the operation returns `Some`.
///
/// If the operation returns `None`, assumes that data has not changed
pub fn write_optional(&self, f: impl FnOnce(&T) -> Option<T>) -> Result<bool, Error> {
    let read_data = self.data.upgradable_read();
    let output_opt = f(&read_data);
    if let Some(output) = output_opt {
        Self::save_data_to(&self.path, &output)?;
        let mut write_data = RwLockUpgradableReadGuard::upgrade(read_data);
        *write_data = output;
        self.change_notification.notify_all();
        Ok(true)
    } else {
        Ok(false)
    }
}

pub fn write<O>(&self, f: impl FnOnce(&mut T) -> O) -> Result<O, Error> {
    let read_data = self.data.upgradable_read();
    let mut data_copy = (*read_data).clone();
    let output = f(&mut data_copy);
    Self::save_data_to(&self.path, &data_copy)?;

    let mut write_data = RwLockUpgradableReadGuard::upgrade(read_data);

    *write_data = data_copy;
    self.change_notification.notify_all();
    Ok(output)
}

fn save_data_to(path: impl Into<PathBuf>, data: &T) -> Result<(), Error> {
    let path: PathBuf = path.into();
    AtomicFile::new(path, AllowOverwrite).write(|file| {
        let writer = BufWriter::new(file);
        serde_json::to_writer(writer, data)
    })?;
    Ok(())
}

pub fn save(&self) -> Result<(), Error> {
    self.save_to(&self.path)
}

pub fn save_to(&self, path: impl Into<PathBuf>) -> Result<(), Error> {
    Self::save_data_to(path, &self.data.read())
}

fn deref(&self) -> &Self::Target {
    &self.data
}

fn deref_mut(&mut self) -> &mut Self::Target {
    &mut self.data
}

#[tokio::test]
async fn test_optimization_process() {
    let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
    let temp_dir = Builder::new().prefix("segment_temp_dir").tempdir().unwrap();

    let dim = 256;
    let mut holder = SegmentHolder::default();

    let segments_to_merge = vec![
        holder.add(random_segment(dir.path(), 100, 3, dim)),
        holder.add(random_segment(dir.path(), 100, 3, dim)),
        holder.add(random_segment(dir.path(), 100, 3, dim)),
    ];

    let segment_to_index = holder.add(random_segment(dir.path(), 100, 110, dim));

    let _other_segment_ids: Vec<SegmentId> = vec![
        holder.add(random_segment(dir.path(), 100, 20, dim)),
        holder.add(random_segment(dir.path(), 100, 20, dim)),
    ];

    let merge_optimizer: Arc<Optimizer> =
        Arc::new(get_merge_optimizer(dir.path(), temp_dir.path(), dim));
    let indexing_optimizer: Arc<Optimizer> =
        Arc::new(get_indexing_optimizer(dir.path(), temp_dir.path(), dim));

    let optimizers = Arc::new(vec![merge_optimizer, indexing_optimizer]);

    let optimizers_log = Arc::new(Mutex::new(Default::default()));
    let segments: Arc<RwLock<_>> = Arc::new(RwLock::new(holder));
    let handles = UpdateHandler::launch_optimization(
        optimizers.clone(),
        optimizers_log.clone(),
        segments.clone(),
        |_| {},
    );

    assert_eq!(handles.len(), 2);

    let join_res = join_all(handles.into_iter().map(|x| x.join_handle).collect_vec()).await;

    // Assert optimizer statuses are tracked properly
    {
        let log = optimizers_log.lock().to_telemetry();
        assert_eq!(log.len(), 2);
        assert!(["indexing", "merge"].contains(&log[0].name.as_str()));
        assert_eq!(log[0].status, TrackerStatus::Done);
        assert!(["indexing", "merge"].contains(&log[1].name.as_str()));
        assert_eq!(log[1].status, TrackerStatus::Done);
    }

    let handles_2 = UpdateHandler::launch_optimization(
        optimizers.clone(),
        optimizers_log.clone(),
        segments.clone(),
        |_| {},
    );

    assert_eq!(handles_2.len(), 0);

    for res in join_res {
        assert!(res.is_ok());
        assert_eq!(res.unwrap(), Some(true));
    }

    assert_eq!(segments.read().len(), 4);

    assert!(segments.read().get(segment_to_index).is_none());

    for sid in segments_to_merge {
        assert!(segments.read().get(sid).is_none());
    }
}

#[tokio::test]
async fn test_cancel_optimization() {
    let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
    let temp_dir = Builder::new().prefix("segment_temp_dir").tempdir().unwrap();

    let mut holder = SegmentHolder::default();
    let dim = 256;

    for _ in 0..5 {
        holder.add(random_segment(dir.path(), 100, 1000, dim));
    }

    let indexing_optimizer: Arc<Optimizer> =
        Arc::new(get_indexing_optimizer(dir.path(), temp_dir.path(), dim));

    let optimizers = Arc::new(vec![indexing_optimizer]);

    let now = Instant::now();

    let optimizers_log = Arc::new(Mutex::new(Default::default()));
    let segments: Arc<RwLock<_>> = Arc::new(RwLock::new(holder));
    let handles = UpdateHandler::launch_optimization(
        optimizers.clone(),
        optimizers_log.clone(),
        segments.clone(),
        |_| {},
    );

    sleep(Duration::from_millis(100)).await;

    let join_handles = handles.into_iter().filter_map(|h| h.stop()).collect_vec();

    let optimization_res = join_all(join_handles).await;

    let actual_optimization_duration = now.elapsed().as_millis();
    eprintln!("actual_optimization_duration = {actual_optimization_duration:#?} ms");

    for res in optimization_res {
        let was_finished = res.expect("Should be no errors during optimization");
        assert_ne!(was_finished, Some(true));
    }

    // Assert optimizer statuses are tracked properly
    {
        let log = optimizers_log.lock().to_telemetry();
        assert_eq!(log.len(), 3);
        for status in log {
            assert_eq!(status.name, "indexing");
            assert!(matches!(status.status, TrackerStatus::Cancelled(_)));
        }
    }

    for (_idx, segment) in segments.read().iter() {
        match segment {
            LockedSegment::Original(_) => {}
            LockedSegment::Proxy(_) => panic!("segment is not restored"),
        }
    }
}

#[test]
fn check_version_upgrade() {
    assert!(!Collection::can_upgrade_storage(
        &"0.3.1".parse().unwrap(),
        &"0.4.0".parse().unwrap()
    ));
    assert!(!Collection::can_upgrade_storage(
        &"0.4.0".parse().unwrap(),
        &"0.5.0".parse().unwrap()
    ));
    assert!(!Collection::can_upgrade_storage(
        &"0.4.0".parse().unwrap(),
        &"0.4.2".parse().unwrap()
    ));
    assert!(Collection::can_upgrade_storage(
        &"0.4.0".parse().unwrap(),
        &"0.4.1".parse().unwrap()
    ));
    assert!(Collection::can_upgrade_storage(
        &"0.4.1".parse().unwrap(),
        &"0.4.2".parse().unwrap()
    ));
}

