            let mut res = true;
            for key in keys {
                res &= write_segment.delete_payload(op_num, id, key)?;
            }
            Ok(res)
        })?;

    check_unprocessed_points(points, &updated_points)?;
    Ok(updated_points.len())
}

pub(crate) fn delete_payload_by_filter(
