pub fn optimize_segment(segment: Segment) -> LockedSegment {
    let dir = Builder::new().prefix("segment_dir_tmp").tempdir().unwrap();

    let segments_dir = segment.current_path.parent().unwrap().to_owned();

    let dim = segment.segment_config.vector_data.get("").unwrap().size;

    let mut holder = SegmentHolder::default();

    let segment_id = holder.add(segment);

    let optimizer = get_indexing_optimizer(&segments_dir, dir.path(), dim);

    let locked_holder: Arc<parking_lot::lock_api::RwLock<_, _>> = Arc::new(RwLock::new(holder));

    optimizer
        .optimize(
            locked_holder.clone(),
            vec![segment_id],
            &AtomicBool::new(false),
        )
        .unwrap();

    let mut holder = locked_holder.write();

    let segment_id = *holder.non_appendable_segments().first().unwrap();

    let mut segments = holder.remove(&[segment_id]);

    segments.pop().unwrap()
}

pub fn new(limit: usize) -> Self {
    SearchResultAggregator {
        queue: FixedLengthPriorityQueue::new(limit),
        seen: HashSet::new(),
    }
}

pub fn push(&mut self, point: ScoredPoint) {
    let point_id = point.id;
    if !self.seen.contains(&point_id) {
        self.seen.insert(point_id);
        self.queue.push(point);
    }
}

pub fn into_vec(self) -> Vec<ScoredPoint> {
    self.queue.into_vec()
}

pub fn lowest(&self) -> Option<&ScoredPoint> {
    self.queue.top()
}

pub fn new(tops: impl Iterator<Item = usize>) -> Self {
    let mut merged_results_per_batch = vec![];
    for top in tops {
        merged_results_per_batch.push(SearchResultAggregator::new(top));
    }

    BatchResultAggregator {
        batch_aggregators: merged_results_per_batch,
        point_versions: HashMap::new(),
    }
}

pub fn update_point_versions(&mut self, search_results: &Vec<Vec<Vec<ScoredPoint>>>) {
    for segment_result in search_results {
        for segment_batch_result in segment_result {
            for point in segment_batch_result {
                let point_id = point.id;
                let point_version =
                    self.point_versions.entry(point_id).or_insert(point.version);
                *point_version = max(*point_version, point.version);
            }
        }
    }
}

/// Updates the specific batch result aggregator with the new points
/// Point must be:
/// - not seen before
/// - not outdated (not less than the version stored in point_versions)
///
/// WARN: Must be called after `update_point_versions`, so that `point_versions` is up to date
pub fn update_batch_results(
    &mut self,
    batch_id: usize,
    search_results: impl Iterator<Item = ScoredPoint>,
) {
    let aggregator = &mut self.batch_aggregators[batch_id];
    for scored_point in search_results {
        debug_assert!(self.point_versions.contains_key(&scored_point.id));
        let point_max_version = self
            .point_versions
            .get(&scored_point.id)
            .copied()
            .unwrap_or(0);
        if scored_point.version >= point_max_version {
            aggregator.push(scored_point);
        }
    }
}

/// Return lowest acceptable score for given batch id
pub fn batch_lowest_scores(&self, batch_id: usize) -> Option<ScoreType> {
    let batch_scores = &self.batch_aggregators[batch_id];
    batch_scores.lowest().map(|x| x.score)
}

pub fn into_topk(self) -> Vec<Vec<ScoredPoint>> {
    self.batch_aggregators
        .into_iter()
        .map(|x| x.into_vec())
        .collect()
}

async fn execute_searches(
    searches: Vec<JoinHandle<SegmentSearchExecutedResult>>,
) -> CollectionResult<(BatchSearchResult, Vec<Vec<bool>>)> {
    let searches = try_join_all(searches);
    let search_results_per_segment_res = searches.await?;

    let mut search_results_per_segment = vec![];
    let mut further_searches_per_segment = vec![];
    for search_result in search_results_per_segment_res {
        let (search_results, further_searches) = search_result?;
        debug_assert!(search_results.len() == further_searches.len());
        search_results_per_segment.push(search_results);
        further_searches_per_segment.push(further_searches);
    }
    Ok((search_results_per_segment, further_searches_per_segment))
}

/// Processes search result of [segment_size x batch_size]
///
/// # Arguments
/// * search_result - [segment_size x batch_size]
/// * limits - [batch_size] - how many results to return for each batched request
/// * further_searches - [segment_size x batch_size] - whether we can search further in the segment
///
/// Returns batch results aggregated by [batch_size] and list of queries, grouped by segment to re-run
pub(crate) fn process_search_result_step1(
    search_result: BatchSearchResult,
    limits: Vec<usize>,
    further_results: Vec<Vec<bool>>,
) -> (
    BatchResultAggregator,
    HashMap<SegmentOffset, Vec<BatchOffset>>,
) {
    let number_segments = search_result.len();
    let batch_size = limits.len();

    // The lowest scored element must be larger or equal to the worst scored element in each segment.
    // Otherwise, the sampling is invalid and some points might be missing.
    // e.g. with 3 segments with the following sampled ranges:
    // s1 - [0.91 -> 0.87]
    // s2 - [0.92 -> 0.86]
    // s3 - [0.93 -> 0.85]
    // If the top merged scores result range is [0.93 -> 0.86] then we do not know if s1 could have contributed more points at the lower part between [0.87 -> 0.86]
    // In that case, we need to re-run the search without sampling on that segment.

    // Initialize result aggregators for each batched request
    let mut result_aggregator = BatchResultAggregator::new(limits.iter().copied());
    result_aggregator.update_point_versions(&search_result);

    // Therefore we need to track the lowest scored element per segment for each batch
    let mut lowest_scores_per_request: Vec<Vec<ScoreType>> = vec![
        vec![f32::max_value(); batch_size]; // initial max score value for each batch
        number_segments
    ];

    let mut retrieved_points_per_request: Vec<Vec<BatchOffset>> = vec![
        vec![0; batch_size]; // initial max score value for each batch
        number_segments
    ];

    // Batch results merged from all segments
    for (segment_idx, segment_result) in search_result.into_iter().enumerate() {
        // merge results for each batch search request across segments
        for (batch_req_idx, query_res) in segment_result.into_iter().enumerate() {
            retrieved_points_per_request[segment_idx][batch_req_idx] = query_res.len();
            lowest_scores_per_request[segment_idx][batch_req_idx] = query_res
                .last()
                .map(|x| x.score)
                .unwrap_or_else(f32::min_value);
            result_aggregator.update_batch_results(batch_req_idx, query_res.into_iter());
        }
    }

    // segment id -> list of batch ids
    let mut searches_to_rerun: HashMap<SegmentOffset, Vec<BatchOffset>> = HashMap::new();

    // Check if we want to re-run the search without sampling on some segments
    for (batch_id, required_limit) in limits.iter().copied().enumerate() {
        let lowest_batch_score_opt = result_aggregator.batch_lowest_scores(batch_id);

        // If there are no results, we do not need to re-run the search
        if let Some(lowest_batch_score) = lowest_batch_score_opt {
            for segment_id in 0..number_segments {
                let segment_lowest_score = lowest_scores_per_request[segment_id][batch_id];
                let retrieved_points = retrieved_points_per_request[segment_id][batch_id];
                let have_further_results = further_results[segment_id][batch_id];

                if have_further_results
                    && retrieved_points < required_limit
                    && segment_lowest_score >= lowest_batch_score
                {
                    log::debug!("Search to re-run without sampling on segment_id: {segment_id} segment_lowest_score: {segment_lowest_score}, lowest_batch_score: {lowest_batch_score}, retrieved_points: {retrieved_points}, required_limit: {required_limit}");
                    // It is possible, that current segment can have better results than
                    // the lowest score in the batch. In that case, we need to re-run the search
                    // without sampling on that segment.
                    searches_to_rerun
                        .entry(segment_id)
                        .or_default()
                        .push(batch_id);
                }
            }
        }
    }

    (result_aggregator, searches_to_rerun)
}

pub async fn search(
    segments: Arc<RwLock<SegmentHolder>>,
    batch_request: Arc<CoreSearchRequestBatch>,
    runtime_handle: &Handle,
    sampling_enabled: bool,
    is_stopped: Arc<AtomicBool>,
    search_optimized_threshold_kb: usize,
) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
    // Do blocking calls in a blocking task: `segment.get().read()` calls might block async runtime
    let task = {
        let segments = segments.clone();

        tokio::task::spawn_blocking(move || {
            let segments = segments.read();

            if !segments.is_empty() {
                let available_point_count = segments
                    .iter()
                    .map(|(_, segment)| segment.get().read().available_point_count())
                    .sum();

                Some(available_point_count)
            } else {
                None
            }
        })
    };

    let Some(available_point_count) = task.await? else {
        return Ok(Vec::new());
    };

    // Using block to ensure `segments` variable is dropped in the end of it
    let (locked_segments, searches): (Vec<_>, Vec<_>) = {
        // Unfortunately, we have to do `segments.read()` twice, once in blocking task
        // and once here, due to `Send` bounds :/
        let segments = segments.read();

        // Probabilistic sampling for the `limit` parameter avoids over-fetching points from segments.
        // e.g. 10 segments with limit 1000 would fetch 10000 points in total and discard 9000 points.
        // With probabilistic sampling we determine a smaller sampling limit for each segment.
        // Use probabilistic sampling if:
        // - sampling is enabled
        // - more than 1 segment
        // - segments are not empty
        let use_sampling = sampling_enabled && segments.len() > 1 && available_point_count > 0;

        segments
            .iter()
            .map(|(_id, segment)| {
                let search = runtime_handle.spawn_blocking({
                    let (segment, batch_request) = (segment.clone(), batch_request.clone());
                    let is_stopped_clone = is_stopped.clone();
                    move || {
                        search_in_segment(
                            segment,
                            batch_request,
                            available_point_count,
                            use_sampling,
                            &is_stopped_clone,
                            search_optimized_threshold_kb,
                        )
                    }
                });
                (segment.clone(), search)
            })
            .unzip()
    };

    // perform search on all segments concurrently
    // the resulting Vec is in the same order as the segment searches were provided.
    let (all_search_results_per_segment, further_results) =
        Self::execute_searches(searches).await?;
    debug_assert!(all_search_results_per_segment.len() == locked_segments.len());

    let (mut result_aggregator, searches_to_rerun) = Self::process_search_result_step1(
        all_search_results_per_segment,
        batch_request
            .searches
            .iter()
            .map(|request| request.limit + request.offset)
            .collect(),
        further_results,
    );
    // The second step of the search is to re-run the search without sampling on some segments
    // Expected that this stage will be executed rarely
    if !searches_to_rerun.is_empty() {
        // TODO notify telemetry of failing sampling
        // Ensure consistent order of segment ids
        let searches_to_rerun: Vec<(SegmentOffset, Vec<BatchOffset>)> =
            searches_to_rerun.into_iter().collect();

        let secondary_searches: Vec<_> = {
            let mut res = vec![];
            for (segment_id, batch_ids) in searches_to_rerun.iter() {
                let segment = locked_segments[*segment_id].clone();
                let partial_batch_request = Arc::new(CoreSearchRequestBatch {
                    searches: batch_ids
                        .iter()
                        .map(|batch_id| batch_request.searches[*batch_id].clone())
                        .collect(),
                });
                let is_stopped_clone = is_stopped.clone();
                res.push(runtime_handle.spawn_blocking(move || {
                    search_in_segment(
                        segment,
                        partial_batch_request,
                        0,
                        false,
                        &is_stopped_clone,
                        search_optimized_threshold_kb,
                    )
                }))
            }
            res
        };

        let (secondary_search_results_per_segment, _) =
            Self::execute_searches(secondary_searches).await?;

        result_aggregator.update_point_versions(&secondary_search_results_per_segment);

        for ((_segment_id, batch_ids), segments_result) in searches_to_rerun
            .into_iter()
            .zip(secondary_search_results_per_segment.into_iter())
        {
            for (batch_id, secondary_batch_result) in
                batch_ids.into_iter().zip(segments_result.into_iter())
            {
                result_aggregator
                    .update_batch_results(batch_id, secondary_batch_result.into_iter());
            }
        }
    }

    let top_scores: Vec<_> = result_aggregator.into_topk();
    Ok(top_scores)
}

pub fn retrieve(
    segments: &RwLock<SegmentHolder>,
    points: &[PointIdType],
    with_payload: &WithPayload,
    with_vector: &WithVector,
) -> CollectionResult<Vec<Record>> {
    let mut point_version: HashMap<PointIdType, SeqNumberType> = Default::default();
    let mut point_records: HashMap<PointIdType, Record> = Default::default();

    segments.read().read_points(points, |id, segment| {
        let version = segment.point_version(id).ok_or_else(|| {
            OperationError::service_error(format!("No version for point {id}"))
        })?;
        // If this point was not found yet or this segment have later version
        if !point_version.contains_key(&id) || point_version[&id] < version {
            point_records.insert(
                id,
                Record {
                    id,
                    payload: if with_payload.enable {
                        if let Some(selector) = &with_payload.payload_selector {
                            Some(selector.process(segment.payload(id)?))
                        } else {
                            Some(segment.payload(id)?)
                        }
                    } else {
                        None
                    },
                    vector: match with_vector {
                        WithVector::Bool(true) => Some(segment.all_vectors(id)?.into()),
                        WithVector::Bool(false) => None,
                        WithVector::Selector(vector_names) => {
                            let mut selected_vectors = NamedVectors::default();
                            for vector_name in vector_names {
                                if let Some(vector) = segment.vector(vector_name, id)? {
                                    selected_vectors.insert(vector_name.into(), vector);
                                }
                            }
                            Some(selected_vectors.into())
                        }
                    },
                    shard_key: None,
                },
            );
            point_version.insert(id, version);
        }
        Ok(true)
    })?;
    Ok(point_records.into_values().collect())
}

fn from(query: &QueryEnum) -> Self {
    match query {
        QueryEnum::Nearest(_) => Self::Nearest,
        QueryEnum::RecommendBestScore(_) => Self::RecommendBestScore,
        QueryEnum::Discover(_) => Self::Discover,
        QueryEnum::Context(_) => Self::Context,
    }
}

/// Returns suggested search sampling size for a given number of points and required limit.
fn sampling_limit(
    limit: usize,
    ef_limit: Option<usize>,
    segment_points: usize,
    total_points: usize,
) -> usize {
    // shortcut empty segment
    if segment_points == 0 {
        return 0;
    }
    let segment_probability = segment_points as f64 / total_points as f64;
    let poisson_sampling =
        find_search_sampling_over_point_distribution(limit as f64, segment_probability)
            .unwrap_or(limit);
    let effective = effective_limit(limit, ef_limit.unwrap_or(0), poisson_sampling);
    log::trace!("sampling: {effective}, poisson: {poisson_sampling} segment_probability: {segment_probability}, segment_points: {segment_points}, total_points: {total_points}");
    effective
}

/// Determines the effective ef limit value for the given parameters.
fn effective_limit(limit: usize, ef_limit: usize, poisson_sampling: usize) -> usize {
    // Prefer the highest of poisson_sampling/ef_limit, but never be higher than limit
    poisson_sampling.max(ef_limit).min(limit)
}

/// Process sequentially contiguous batches
///
/// # Arguments
///
/// * `segment` - Locked segment to search in
/// * `request` - Batch of search requests
/// * `total_points` - Number of points in all segments combined
/// * `use_sampling` - If true, try to use probabilistic sampling
/// * `is_stopped` - Atomic bool to check if search is stopped
/// * `indexing_threshold` - If `indexed_only` is enabled, the search will skip
///                          segments with more than this number Kb of un-indexed vectors
///
/// # Returns
///
/// Collection Result of:
/// * Vector of ScoredPoints for each request in the batch
/// * Vector of boolean indicating if the segment have further points to search
fn search_in_segment(
    segment: LockedSegment,
    request: Arc<CoreSearchRequestBatch>,
    total_points: usize,
    use_sampling: bool,
    is_stopped: &AtomicBool,
    search_optimized_threshold_kb: usize,
) -> CollectionResult<(Vec<Vec<ScoredPoint>>, Vec<bool>)> {
    let batch_size = request.searches.len();

    let mut result: Vec<Vec<ScoredPoint>> = Vec::with_capacity(batch_size);
    let mut further_results: Vec<bool> = Vec::with_capacity(batch_size); // if segment have more points to return
    let mut vectors_batch: Vec<QueryVector> = vec![];
    let mut prev_params = BatchSearchParams::default();

    for search_query in &request.searches {
        let with_payload_interface = search_query
            .with_payload
            .as_ref()
            .unwrap_or(&WithPayloadInterface::Bool(false));

        let params = BatchSearchParams {
            search_type: search_query.query.as_ref().into(),
            vector_name: search_query.query.get_vector_name(),
            filter: search_query.filter.as_ref(),
            with_payload: WithPayload::from(with_payload_interface),
            with_vector: search_query.with_vector.clone().unwrap_or_default(),
            top: search_query.limit + search_query.offset,
            params: search_query.params.as_ref(),
        };

        let query = search_query.query.clone().into();

        // same params enables batching
        if params == prev_params {
            vectors_batch.push(query);
        } else {
            // different params means different batches
            // execute what has been batched so far
            if !vectors_batch.is_empty() {
                let (mut res, mut further) = execute_batch_search(
                    &segment,
                    &vectors_batch,
                    &prev_params,
                    use_sampling,
                    total_points,
                    is_stopped,
                    search_optimized_threshold_kb,
                )?;
                further_results.append(&mut further);
                result.append(&mut res);
                vectors_batch.clear()
            }
            // start new batch for current search query
            vectors_batch.push(query);
            prev_params = params;
        }
    }

    // run last batch if any
    if !vectors_batch.is_empty() {
        let (mut res, mut further) = execute_batch_search(
            &segment,
            &vectors_batch,
            &prev_params,
            use_sampling,
            total_points,
            is_stopped,
            search_optimized_threshold_kb,
        )?;
        further_results.append(&mut further);
        result.append(&mut res);
    }

    Ok((result, further_results))
}

fn execute_batch_search(
    segment: &LockedSegment,
    vectors_batch: &Vec<QueryVector>,
    search_params: &BatchSearchParams,
    use_sampling: bool,
    total_points: usize,
    is_stopped: &AtomicBool,
    search_optimized_threshold_kb: usize,
) -> CollectionResult<(Vec<Vec<ScoredPoint>>, Vec<bool>)> {
    let locked_segment = segment.get();
    let read_segment = locked_segment.read();

    let segment_points = read_segment.available_point_count();
    let segment_config = read_segment.config();

    let top = if use_sampling {
        let ef_limit = search_params
            .params
            .and_then(|p| p.hnsw_ef)
            .or_else(|| get_hnsw_ef_construct(segment_config, search_params.vector_name));
        sampling_limit(search_params.top, ef_limit, segment_points, total_points)
    } else {
        search_params.top
    };

    let ignore_plain_index = search_params
        .params
        .map(|p| p.indexed_only)
        .unwrap_or(false);
    if ignore_plain_index
        && !is_search_optimized(
            read_segment.deref(),
            search_optimized_threshold_kb,
            search_params.vector_name,
        )?
    {
        let batch_len = vectors_batch.len();
        return Ok((vec![vec![]; batch_len], vec![false; batch_len]));
    }
    let vectors_batch = &vectors_batch.iter().collect_vec();
    let res = read_segment.search_batch(
        search_params.vector_name,
        vectors_batch,
        &search_params.with_payload,
        &search_params.with_vector,
        search_params.filter,
        top,
        search_params.params,
        is_stopped,
    )?;

    let further_results = res
        .iter()
        .map(|batch_result| batch_result.len() == top)
        .collect();

    Ok((res, further_results))
}

/// Check if the segment is indexed enough to be searched with `indexed_only` parameter
fn is_search_optimized(
    segment: &dyn SegmentEntry,
    search_optimized_threshold_kb: usize,
    vector_name: &str,
) -> CollectionResult<bool> {
    let segment_info = segment.info();
    let vector_name_error =
        || CollectionError::bad_request(format!("Vector {} doesn't exist", vector_name));

    let vector_data_info = segment_info
        .vector_data
        .get(vector_name)
        .ok_or_else(vector_name_error)?;

    // check only dense vectors because sparse vectors are always indexed
    let vector_size = segment
        .config()
        .vector_data
        .get(vector_name)
        .ok_or_else(vector_name_error)?
        .size;

    let vector_size_bytes = vector_size * VECTOR_ELEMENT_SIZE;

    let unindexed_vectors = vector_data_info
        .num_vectors
        .saturating_sub(vector_data_info.num_indexed_vectors);

    let unindexed_volume = vector_size_bytes.saturating_mul(unindexed_vectors);

    let indexing_threshold_bytes = search_optimized_threshold_kb * BYTES_IN_KB;

    // Examples:
    // Threshold = 20_000 Kb
    // Indexed vectors: 100000
    // Total vectors: 100010
    // unindexed_volume = 100010 - 100000 = 10
    // Result: true

    // Threshold = 20_000 Kb
    // Indexed vectors: 0
    // Total vectors: 100000
    // unindexed_volume = 100000
    // Result: false
    Ok(unindexed_volume < indexing_threshold_bytes)
}

/// Find the HNSW ef_construct for a named vector
///
/// If the given named vector has no HNSW index, `None` is returned.
fn get_hnsw_ef_construct(config: &SegmentConfig, vector_name: &str) -> Option<usize> {
    config
        .vector_data
        .get(vector_name)
        .and_then(|config| match &config.index {
            Indexes::Plain {} => None,
            Indexes::Hnsw(hnsw) => Some(hnsw),
        })
        .map(|hnsw| hnsw.ef_construct)
}

fn cmp(&self, other: &Self) -> std::cmp::Ordering {
    self.point_id.cmp(&other.point_id).reverse()
}

fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
    Some(self.cmp(other))
}

fn try_unwrap_with_timeout<T>(
    mut arc: Arc<T>,
    spin: Duration,
    timeout: Duration,
) -> Result<T, Arc<T>> {
    if timeout.is_zero() {
        return Err(arc);
    }

    loop {
        match Arc::try_unwrap(arc) {
            inner @ Ok(_) => return inner,
            Err(inner) => {
                arc = inner;
                sleep(spin);
            }
        }
    }
}

pub fn new<T>(segment: T) -> Self
where
    T: Into<LockedSegment>,
{
    segment.into()
}

pub fn get(&self) -> Arc<RwLock<dyn SegmentEntry>> {
    match self {
        LockedSegment::Original(segment) => segment.clone(),
        LockedSegment::Proxy(proxy) => proxy.clone(),
    }
}

/// Consume the LockedSegment and drop the underlying segment data.
/// Operation fails if the segment is used by other thread for longer than `timeout`.
pub fn drop_data(self) -> OperationResult<()> {
    match self {
        LockedSegment::Original(segment) => {
            match try_unwrap_with_timeout(segment, DROP_SPIN_TIMEOUT, DROP_DATA_TIMEOUT) {
                Ok(raw_locked_segment) => raw_locked_segment.into_inner().drop_data(),
                Err(locked_segment) => Err(OperationError::service_error(format!(
                    "Removing segment which is still in use: {:?}",
                    locked_segment.read().data_path()
                ))),
            }
        }
        LockedSegment::Proxy(proxy) => {
            match try_unwrap_with_timeout(proxy, DROP_SPIN_TIMEOUT, DROP_DATA_TIMEOUT) {
                Ok(raw_locked_segment) => raw_locked_segment.into_inner().drop_data(),
                Err(locked_segment) => Err(OperationError::service_error(format!(
                    "Removing proxy segment which is still in use: {:?}",
                    locked_segment.read().data_path()
                ))),
            }
        }
    }
}

fn clone(&self) -> Self {
    match self {
        LockedSegment::Original(x) => LockedSegment::Original(x.clone()),
        LockedSegment::Proxy(x) => LockedSegment::Proxy(x.clone()),
    }
}

fn clone_from(&mut self, source: &Self) {
    *self = source.clone();
}

fn from(s: Segment) -> Self {
    LockedSegment::Original(Arc::new(RwLock::new(s)))
}

fn from(s: ProxySegment) -> Self {
    LockedSegment::Proxy(Arc::new(RwLock::new(s)))
}

pub fn iter(&'s self) -> impl Iterator<Item = (&SegmentId, &LockedSegment)> + 's {
    self.segments.iter()
}

pub fn len(&self) -> usize {
    self.segments.len()
}

pub fn is_empty(&self) -> bool {
    self.segments.is_empty()
}

pub fn update_tracker(&self) -> UpdateTracker {
    self.update_tracker.clone()
}

fn generate_new_key(&self) -> SegmentId {
    let key = thread_rng().gen::<SegmentId>();
    if self.segments.contains_key(&key) {
        self.generate_new_key()
    } else {
        key
    }
}

/// Add new segment to storage
pub fn add<T>(&mut self, segment: T) -> SegmentId
where
    T: Into<LockedSegment>,
{
    let key = self.generate_new_key();
    self.segments.insert(key, segment.into());
    key
}

/// Add new segment to storage which is already LockedSegment
pub fn add_locked(&mut self, segment: LockedSegment) -> SegmentId {
    let key = self.generate_new_key();
    self.segments.insert(key, segment);
    key
}

pub fn remove(&mut self, remove_ids: &[SegmentId]) -> Vec<LockedSegment> {
    let mut removed_segments = vec![];
    for remove_id in remove_ids {
        let removed_segment = self.segments.remove(remove_id);
        if let Some(segment) = removed_segment {
            removed_segments.push(segment);
        }
    }
    removed_segments
}

/// Replace old segments with a new one
///
/// # Arguments
///
/// * `segment` - segment to insert
/// * `remove_ids` - ids of segments to replace
///
/// # Result
///
/// Pair of (id of newly inserted segment, Vector of replaced segments)
///
pub fn swap<T>(
    &mut self,
    segment: T,
    remove_ids: &[SegmentId],
) -> (SegmentId, Vec<LockedSegment>)
where
    T: Into<LockedSegment>,
{
    let new_id = self.add(segment);
    (new_id, self.remove(remove_ids))
}

pub fn get(&self, id: SegmentId) -> Option<&LockedSegment> {
    self.segments.get(&id)
}

pub fn random_appendable_segment(&self) -> Option<LockedSegment> {
    let segment_ids: Vec<_> = self.appendable_segments();
    segment_ids
        .choose(&mut rand::thread_rng())
        .and_then(|idx| self.segments.get(idx).cloned())
}

/// Selects point ids, which is stored in this segment
fn segment_points(&self, ids: &[PointIdType], segment: &dyn SegmentEntry) -> Vec<PointIdType> {
    ids.iter()
        .cloned()
        .filter(|id| segment.has_point(*id))
        .collect()
}

pub fn for_each_segment<F>(&self, mut f: F) -> OperationResult<usize>
where
    F: FnMut(&RwLockReadGuard<dyn SegmentEntry + 'static>) -> OperationResult<bool>,
{
    let mut processed_segments = 0;
    for segment in self.segments.values() {
        let is_applied = f(&segment.get().read())?;
        processed_segments += is_applied as usize;
    }
    Ok(processed_segments)
}

pub fn apply_segments<F>(&self, mut f: F) -> OperationResult<usize>
where
    F: FnMut(&mut RwLockWriteGuard<dyn SegmentEntry + 'static>) -> OperationResult<bool>,
{
    let _update_guard = self.update_tracker.update();

    let mut processed_segments = 0;
    for segment in self.segments.values() {
        let is_applied = f(&mut segment.get().write())?;
        processed_segments += is_applied as usize;
    }
    Ok(processed_segments)
}

pub fn apply_points<F>(&self, ids: &[PointIdType], mut f: F) -> OperationResult<usize>
where
    F: FnMut(
        PointIdType,
        SegmentId,
        &mut RwLockWriteGuard<dyn SegmentEntry>,
    ) -> OperationResult<bool>,
{
    let _update_guard = self.update_tracker.update();

    let mut applied_points = 0;
    for (idx, segment) in &self.segments {
        // Collect affected points first, we want to lock segment for writing as rare as possible
        let segment_arc = segment.get();
        let segment_lock = segment_arc.upgradable_read();
        let segment_points = self.segment_points(ids, segment_lock.deref());
        if !segment_points.is_empty() {
            let mut write_segment = RwLockUpgradableReadGuard::upgrade(segment_lock);
            for point_id in segment_points {
                let is_applied = f(point_id, *idx, &mut write_segment)?;
                applied_points += is_applied as usize;
            }
        }
    }
    Ok(applied_points)
}

/// Try to acquire read lock over the given segment with increasing wait time.
/// Should prevent deadlock in case if multiple threads tries to lock segments sequentially.
fn aloha_lock_segment_read<'a>(
    &'a self,
    segment: &'a Arc<RwLock<dyn SegmentEntry>>,
) -> RwLockReadGuard<dyn SegmentEntry> {
    let mut interval = Duration::from_nanos(100);
    loop {
        if let Some(guard) = segment.try_read_for(interval) {
            return guard;
        }

        interval = interval.saturating_mul(2);
        if interval.as_secs() >= 10 {
            log::warn!("Trying to read-lock all collection segments is taking a long time. This could be a deadlock and may block new updates.");
        }
    }
}

/// Try to acquire write lock over random segment with increasing wait time.
/// Should prevent deadlock in case if multiple threads tries to lock segments sequentially.
pub fn aloha_random_write<F>(
    &self,
    segment_ids: &[SegmentId],
    mut apply: F,
) -> OperationResult<bool>
where
    F: FnMut(SegmentId, &mut RwLockWriteGuard<dyn SegmentEntry>) -> OperationResult<bool>,
{
    if segment_ids.is_empty() {
        return Err(OperationError::service_error(
            "No appendable segments exists, expected at least one",
        ));
    }

    let mut entries: Vec<_> = Default::default();

    // Try to access each segment first without any timeout (fast)
    for segment_id in segment_ids {
        let segment_opt = self.segments.get(segment_id).map(|x| x.get());
        match segment_opt {
            None => {}
            Some(segment_lock) => {
                match segment_lock.try_write() {
                    None => {}
                    Some(mut lock) => return apply(*segment_id, &mut lock),
                }
                // save segments for further lock attempts
                entries.push((*segment_id, segment_lock))
            }
        };
    }

    let mut rng = rand::thread_rng();
    let (segment_id, segment_lock) = entries.choose(&mut rng).unwrap();
    let mut segment_write = segment_lock.write();
    apply(*segment_id, &mut segment_write)
}

/// Update function wrapper, which ensures that updates are not applied written to un-appendable segment.
/// In case of such attempt, this function will move data into a mutable segment and remove data from un-appendable.
/// Returns: Set of point ids which were successfully(already) applied to segments
pub fn apply_points_to_appendable<F>(
    &self,
    op_num: SeqNumberType,
    ids: &[PointIdType],
    mut f: F,
) -> OperationResult<HashSet<PointIdType>>
where
    F: FnMut(PointIdType, &mut RwLockWriteGuard<dyn SegmentEntry>) -> OperationResult<bool>,
{
    let _update_guard = self.update_tracker.update();

    // Choose random appendable segment from this
    let appendable_segments = self.appendable_segments();

    let mut applied_points: HashSet<PointIdType> = Default::default();

    let _applied_points_count = self.apply_points(ids, |point_id, _idx, write_segment| {
        if let Some(point_version) = write_segment.point_version(point_id) {
            if point_version >= op_num {
                applied_points.insert(point_id);
                return Ok(false);
            }
        }

        let is_applied = if write_segment.is_appendable() {
            f(point_id, write_segment)?
        } else {
            self.aloha_random_write(
                &appendable_segments,
                |_appendable_idx, appendable_write_segment| {
                    let all_vectors = write_segment.all_vectors(point_id)?;
                    let payload = write_segment.payload(point_id)?;

                    appendable_write_segment.upsert_point(op_num, point_id, all_vectors)?;
                    appendable_write_segment.set_full_payload(op_num, point_id, &payload)?;

                    write_segment.delete_point(op_num, point_id)?;

                    f(point_id, appendable_write_segment)
                },
            )?
        };
        applied_points.insert(point_id);
        Ok(is_applied)
    })?;
    Ok(applied_points)
}

pub fn read_points<F>(&self, ids: &[PointIdType], mut f: F) -> OperationResult<usize>
where
    F: FnMut(PointIdType, &RwLockReadGuard<dyn SegmentEntry>) -> OperationResult<bool>,
{
    let mut read_points = 0;
    for segment in self.segments.values() {
        let segment_arc = segment.get();
        let read_segment = segment_arc.read();
        for point in ids.iter().cloned().filter(|id| read_segment.has_point(*id)) {
            let is_ok = f(point, &read_segment)?;
            read_points += is_ok as usize;
        }
    }
    Ok(read_points)
}

/// Defines flush ordering for segments.
///
/// Flush appendable segments first, then non-appendable.
/// This is done to ensure that all data, transferred from non-appendable segments to appendable segments
/// is persisted, before marking records in non-appendable segments as removed.
fn segment_flush_ordering(&self) -> impl Iterator<Item = SegmentId> {
    let appendable_segments = self.appendable_segments();
    let non_appendable_segments = self.non_appendable_segments();

    appendable_segments
        .into_iter()
        .chain(non_appendable_segments)
}

/// Flushes all segments and returns maximum version to persist
///
/// Before flushing, this read-locks all segments. It prevents writes to all not-yet-flushed
/// segments during flushing. All locked segments are flushed and released one by one.
///
/// If there are unsaved changes after flush - detects lowest unsaved change version.
/// If all changes are saved - returns max version.
pub fn flush_all(&self, sync: bool) -> OperationResult<SeqNumberType> {
    // Grab and keep to segment RwLock's until the end of this function
    let segments = self.segment_locks(self.segment_flush_ordering())?;

    // Read-lock all segments before flushing any, must prevent any writes to any segment
    // That is to prevent any copy-on-write operation on two segments from occurring in between
    // flushing the two segments. If that would happen, segments could end up in an
    // inconsistent state on disk that is not recoverable after a crash.
    //
    // E.g.: we have a point on an immutable segment. If we use a set-payload operation, we do
    // copy-on-write. The point from immutable segment A is deleted, the updated point is
    // stored on appendable segment B.
    // Because of flush ordering segment B (appendable) is flushed before segment A
    // (not-appendable). If the copy-on-write operation happens in between, the point is
    // deleted from A but the new point in B is not persisted. We cannot recover this by
    // replaying the WAL in case of a crash because the point in A does not exist anymore,
    // making copy-on-write impossible.
    // Locking all segments prevents copy-on-write operations from occurring in between
    // flushes.
    //
    // WARNING: Ordering is very important here. Specifically:
    // - We MUST lock non-appendable first, then appendable.
    // - We MUST flush appendable first, then non-appendable
    // Because of this, two rev(erse) calls are used below here.
    //
    // Locking must happen in this order because `apply_points_to_appendable` can take two
    // write locks, also in this order. If we'd use different ordering we will eventually end
    // up with a deadlock.
    let mut segment_reads: Vec<_> = segments
        .iter()
        .rev()
        .map(|segment| self.aloha_lock_segment_read(segment))
        .collect();
    segment_reads.reverse();

    // Assert we flush appendable segments first
    debug_assert!(
        segment_reads
            .windows(2)
            .all(|s| s[0].is_appendable() || !s[1].is_appendable()),
        "Must flush appendable segments first",
    );

    let mut max_persisted_version: SeqNumberType = SeqNumberType::MIN;
    let mut min_unsaved_version: SeqNumberType = SeqNumberType::MAX;
    let mut has_unsaved = false;

    // Flush and release each segment
    for read_segment in segment_reads {
        let segment_version = read_segment.version();
        let segment_persisted_version = read_segment.flush(sync)?;

        if segment_version > segment_persisted_version {
            has_unsaved = true;
            min_unsaved_version = min(min_unsaved_version, segment_persisted_version);
        }

        max_persisted_version = max(max_persisted_version, segment_persisted_version);

        // Release read-lock immediately after flush, explicit to make this more clear
        drop(read_segment);
    }

    if has_unsaved {
        Ok(min_unsaved_version)
    } else {
        Ok(max_persisted_version)
    }
}

/// Grab the RwLock's for all the given segment IDs.
fn segment_locks(
    &self,
    segment_ids: impl IntoIterator<Item = SegmentId>,
) -> OperationResult<Vec<Arc<RwLock<dyn SegmentEntry>>>> {
    segment_ids
        .into_iter()
        .map(|segment_id| {
            self.segments
                .get(&segment_id)
                .ok_or_else(|| {
                    OperationError::service_error(format!("No segment with ID {segment_id}"))
                })
                .map(LockedSegment::get)
        })
        .collect()
}

/// Take a snapshot of all segments into `snapshot_dir_path`
///
/// Shortcuts at the first failing segment snapshot
pub fn snapshot_all_segments(
    &self,
    temp_dir: &Path,
    snapshot_dir_path: &Path,
) -> OperationResult<()> {
    for segment in self.segments.values() {
        let segment_lock = segment.get();
        let read_segment = segment_lock.read();
        read_segment.take_snapshot(temp_dir, snapshot_dir_path)?;
    }
    Ok(())
}

pub fn report_optimizer_error<E: Into<CollectionError>>(&mut self, error: E) {
    // Save only the first error
    // If is more likely to be the real cause of all further problems
    if self.optimizer_errors.is_none() {
        self.optimizer_errors = Some(error.into());
    }
}

/// Duplicated points can appear in case of interrupted optimization.
/// LocalShard can still work with duplicated points, but it is better to remove them.
/// Duplicated points should not affect the search results.
///
/// Checks all segments and removes duplicated and outdated points.
/// If two points have the same id, the point with the highest version is kept.
/// If two points have the same id and version, one of them is kept.
///
/// Deduplication works with plain segments only.
pub fn deduplicate_points(&self) -> OperationResult<usize> {
    let points_to_remove = self.find_duplicated_points()?;

    let mut removed_points = 0;
    for (segment_id, points) in points_to_remove {
        let locked_segment = self.segments.get(&segment_id).unwrap();
        let segment_arc = locked_segment.get();
        let mut write_segment = segment_arc.write();
        for point_id in points {
            if let Some(point_version) = write_segment.point_version(point_id) {
                removed_points += 1;
                write_segment.delete_point(point_version, point_id)?;
            }
        }
    }
    Ok(removed_points)
}

fn find_duplicated_points(&self) -> OperationResult<HashMap<SegmentId, Vec<PointIdType>>> {
    let segments = self
        .segments
        .iter()
        .map(|(&segment_id, locked_segment)| (segment_id, locked_segment.get()))
        .collect_vec();
    let locked_segments = BTreeMap::from_iter(
        segments
            .iter()
            .map(|(segment_id, locked_segment)| (*segment_id, locked_segment.read())),
    );
    let mut iterators = BTreeMap::from_iter(
        locked_segments
            .iter()
            .map(|(segment_id, locked_segment)| (*segment_id, locked_segment.iter_points())),
    );

    // heap contains the current iterable point id from each segment
    let mut heap = iterators
        .iter_mut()
        .filter_map(|(&segment_id, iter)| {
            iter.next().map(|point_id| DedupPoint {
                segment_id,
                point_id,
            })
        })
        .collect::<BinaryHeap<_>>();

    let mut last_point_id_opt = None;
    let mut last_segment_id_opt = None;
    let mut last_point_version_opt = None;
    let mut points_to_remove: HashMap<SegmentId, Vec<PointIdType>> = Default::default();

    while let Some(entry) = heap.pop() {
        let point_id = entry.point_id;
        let segment_id = entry.segment_id;
        if let Some(next_point_id) = iterators.get_mut(&segment_id).and_then(|i| i.next()) {
            heap.push(DedupPoint {
                segment_id,
                point_id: next_point_id,
            });
        }

        if last_point_id_opt == Some(point_id) {
            let last_point_id = last_point_id_opt.unwrap();
            let last_segment_id = last_segment_id_opt.unwrap();

            let point_version = locked_segments[&segment_id].point_version(point_id);
            let last_point_version = if let Some(last_point_version) = last_point_version_opt {
                last_point_version
            } else {
                let version = locked_segments[&last_segment_id].point_version(last_point_id);
                last_point_version_opt = Some(version);
                version
            };

            // choose newer version between point_id and last_point_id
            if point_version < last_point_version {
                points_to_remove
                    .entry(segment_id)
                    .or_default()
                    .push(point_id);
            } else {
                last_point_id_opt = Some(point_id);
                last_segment_id_opt = Some(segment_id);
                last_point_version_opt = Some(point_version);
                points_to_remove
                    .entry(last_segment_id)
                    .or_default()
                    .push(last_point_id);
            }
        } else {
            last_point_id_opt = Some(point_id);
            last_segment_id_opt = Some(segment_id);
        }
    }

    Ok(points_to_remove)
}

pub fn new(
    segment: LockedSegment,
    write_segment: LockedSegment,
    deleted_points: LockedRmSet,
    created_indexes: LockedFieldsMap,
    deleted_indexes: LockedFieldsSet,
) -> Self {
    let wrapped_config = segment.get().read().config().clone();
    ProxySegment {
        write_segment,
        wrapped_segment: segment,
        deleted_points,
        created_indexes,
        deleted_indexes,
        last_flushed_version: Arc::new(RwLock::new(None)),
        wrapped_config,
    }
}

/// Ensure that write segment have same indexes as wrapped segment
pub fn replicate_field_indexes(&mut self, op_num: SeqNumberType) -> OperationResult<()> {
    let existing_indexes = self.write_segment.get().read().get_indexed_fields();
    let expected_indexes = self.wrapped_segment.get().read().get_indexed_fields();
    // create missing indexes
    for (expected_field, expected_schema) in &expected_indexes {
        let existing_schema = existing_indexes.get(expected_field);

        if existing_schema != Some(expected_schema) {
            if existing_schema.is_some() {
                self.write_segment
                    .get()
                    .write()
                    .delete_field_index(op_num, expected_field)?;
            }
            self.write_segment.get().write().create_field_index(
                op_num,
                expected_field,
                Some(expected_schema),
            )?;
        }
    }
    // remove extra indexes
    for existing_field in existing_indexes.keys() {
        if !expected_indexes.contains_key(existing_field) {
            self.write_segment
                .get()
                .write()
                .delete_field_index(op_num, existing_field)?;
        }
    }
    Ok(())
}

fn move_if_exists(
    &self,
    op_num: SeqNumberType,
    point_id: PointIdType,
) -> OperationResult<bool> {
    let deleted_points_guard = self.deleted_points.upgradable_read();
    if deleted_points_guard.contains(&point_id) {
        // Point is already removed from wrapped segment
        return Ok(false);
    }
    let wrapped_segment = self.wrapped_segment.get();
    let wrapped_segment_guard = wrapped_segment.read();
    if !wrapped_segment_guard.has_point(point_id) {
        // Point is not in wrapped segment
        return Ok(false);
    }

    let (all_vectors, payload) = (
        wrapped_segment_guard.all_vectors(point_id)?,
        wrapped_segment_guard.payload(point_id)?,
    );

    {
        let mut deleted_points_write = RwLockUpgradableReadGuard::upgrade(deleted_points_guard);
        deleted_points_write.insert(point_id);
    }

    let segment_arc = self.write_segment.get();
    let mut write_segment = segment_arc.write();

    write_segment.upsert_point(op_num, point_id, all_vectors)?;
    write_segment.set_full_payload(op_num, point_id, &payload)?;

    Ok(true)
}

fn add_deleted_points_condition_to_filter(
    &self,
    filter: Option<&Filter>,
    deleted_points: &HashSet<PointIdType>,
) -> Filter {
    let wrapper_condition = Condition::HasId(deleted_points.clone().into());
    match filter {
        None => Filter::new_must_not(wrapper_condition),
        Some(f) => {
            let mut new_filter = f.clone();
            let must_not = new_filter.must_not;

            let new_must_not = match must_not {
                None => Some(vec![wrapper_condition]),
                Some(mut conditions) => {
                    conditions.push(wrapper_condition);
                    Some(conditions)
                }
            };
            new_filter.must_not = new_must_not;
            new_filter
        }
    }
}

fn version(&self) -> SeqNumberType {
    max(
        self.wrapped_segment.get().read().version(),
        self.write_segment.get().read().version(),
    )
}

fn point_version(&self, point_id: PointIdType) -> Option<SeqNumberType> {
    // Write version is always higher if presence
    self.write_segment
        .get()
        .read()
        .point_version(point_id)
        .or_else(|| self.wrapped_segment.get().read().point_version(point_id))
}

fn search(
    &self,
    vector_name: &str,
    vector: &QueryVector,
    with_payload: &WithPayload,
    with_vector: &WithVector,
    filter: Option<&Filter>,
    top: usize,
    params: Option<&SearchParams>,
    is_stopped: &AtomicBool,
) -> OperationResult<Vec<ScoredPoint>> {
    let deleted_points = self.deleted_points.read();

    // Some point might be deleted after temporary segment creation
    // We need to prevent them from being found by search request
    // That is why we need to pass additional filter for deleted points
    let do_update_filter = !deleted_points.is_empty();
    let mut wrapped_result = if do_update_filter {
        // ToDo: Come up with better way to pass deleted points into Filter
        // e.g. implement AtomicRefCell for Serializer.
        // This copy might slow process down if there will be a lot of deleted points
        let wrapped_filter =
            self.add_deleted_points_condition_to_filter(filter, &deleted_points);

        self.wrapped_segment.get().read().search(
            vector_name,
            vector,
            with_payload,
            with_vector,
            Some(&wrapped_filter),
            top,
            params,
            is_stopped,
        )?
    } else {
        self.wrapped_segment.get().read().search(
            vector_name,
            vector,
            with_payload,
            with_vector,
            filter,
            top,
            params,
            is_stopped,
        )?
    };

    let mut write_result = self.write_segment.get().read().search(
        vector_name,
        vector,
        with_payload,
        with_vector,
        filter,
        top,
        params,
        is_stopped,
    )?;

    wrapped_result.append(&mut write_result);
    Ok(wrapped_result)
}

fn search_batch(
    &self,
    vector_name: &str,
    vectors: &[&QueryVector],
    with_payload: &WithPayload,
    with_vector: &WithVector,
    filter: Option<&Filter>,
    top: usize,
    params: Option<&SearchParams>,
    is_stopped: &AtomicBool,
) -> OperationResult<Vec<Vec<ScoredPoint>>> {
    let deleted_points = self.deleted_points.read();

    // Some point might be deleted after temporary segment creation
    // We need to prevent them from being found by search request
    // That is why we need to pass additional filter for deleted points
    let do_update_filter = !deleted_points.is_empty();
    let mut wrapped_results = if do_update_filter {
        // ToDo: Come up with better way to pass deleted points into Filter
        // e.g. implement AtomicRefCell for Serializer.
        // This copy might slow process down if there will be a lot of deleted points
        let wrapped_filter =
            self.add_deleted_points_condition_to_filter(filter, &deleted_points);

        self.wrapped_segment.get().read().search_batch(
            vector_name,
            vectors,
            with_payload,
            with_vector,
            Some(&wrapped_filter),
            top,
            params,
            is_stopped,
        )?
    } else {
        self.wrapped_segment.get().read().search_batch(
            vector_name,
            vectors,
            with_payload,
            with_vector,
            filter,
            top,
            params,
            is_stopped,
        )?
    };
    let mut write_results = self.write_segment.get().read().search_batch(
        vector_name,
        vectors,
        with_payload,
        with_vector,
        filter,
        top,
        params,
        is_stopped,
    )?;
    for (index, write_result) in write_results.iter_mut().enumerate() {
        wrapped_results[index].append(write_result)
    }
    Ok(wrapped_results)
}

fn upsert_point(
    &mut self,
    op_num: SeqNumberType,
    point_id: PointIdType,
    vectors: NamedVectors,
) -> OperationResult<bool> {
    self.move_if_exists(op_num, point_id)?;
    self.write_segment
        .get()
        .write()
        .upsert_point(op_num, point_id, vectors)
}

fn delete_point(
    &mut self,
    op_num: SeqNumberType,
    point_id: PointIdType,
) -> OperationResult<bool> {
    let mut was_deleted = false;
    if self.wrapped_segment.get().read().has_point(point_id) {
        was_deleted = self.deleted_points.write().insert(point_id);
    }
    let was_deleted_in_writable = self
        .write_segment
        .get()
        .write()
        .delete_point(op_num, point_id)?;

    Ok(was_deleted || was_deleted_in_writable)
}

fn update_vectors(
    &mut self,
