}

fn validate(&self) -> Result<(), validator::ValidationErrors> {
    match self {
        CollectionUpdateOperations::PointOperation(operation) => operation.validate(),
        CollectionUpdateOperations::VectorOperation(operation) => operation.validate(),
        CollectionUpdateOperations::PayloadOperation(operation) => operation.validate(),
        CollectionUpdateOperations::FieldIndexOperation(operation) => operation.validate(),
    }
}

fn point_to_shard(point_id: ExtendedPointId, ring: &HashRing<ShardId>) -> ShardId {
    *ring
        .get(&point_id)
        .expect("Hash ring is guaranteed to be non-empty")
}

/// Split iterator of items that have point ids by shard
fn split_iter_by_shard<I, F, O>(
    iter: I,
    id_extractor: F,
    ring: &HashRing<ShardId>,
) -> OperationToShard<Vec<O>>
where
    I: IntoIterator<Item = O>,
    F: Fn(&O) -> ExtendedPointId,
{
    let mut op_vec_by_shard: HashMap<ShardId, Vec<O>> = HashMap::new();
    for operation in iter {
        let shard_id = point_to_shard(id_extractor(&operation), ring);
        op_vec_by_shard.entry(shard_id).or_default().push(operation);
    }
    OperationToShard::by_shard(op_vec_by_shard)
}

fn split_by_shard(self, ring: &HashRing<ShardId>) -> OperationToShard<Self> {
    match self {
        CollectionUpdateOperations::PointOperation(operation) => operation
            .split_by_shard(ring)
            .map(CollectionUpdateOperations::PointOperation),
        CollectionUpdateOperations::VectorOperation(operation) => operation
            .split_by_shard(ring)
            .map(CollectionUpdateOperations::VectorOperation),
        CollectionUpdateOperations::PayloadOperation(operation) => operation
            .split_by_shard(ring)
            .map(CollectionUpdateOperations::PayloadOperation),
        operation @ CollectionUpdateOperations::FieldIndexOperation(_) => {
            OperationToShard::to_all(operation)
        }
    }
}

pub fn is_write_operation(&self) -> bool {
    match self {
        CollectionUpdateOperations::PointOperation(operation) => operation.is_write_operation(),
        CollectionUpdateOperations::VectorOperation(operation) => {
            operation.is_write_operation()
        }
        CollectionUpdateOperations::PayloadOperation(operation) => {
            operation.is_write_operation()
        }
        CollectionUpdateOperations::FieldIndexOperation(operation) => {
            operation.is_write_operation()
        }
    }
}

fn estimate_effect_area(&self) -> OperationEffectArea {
    match self {
        CollectionUpdateOperations::PointOperation(point_operation) => {
            point_operation.estimate_effect_area()
        }
        CollectionUpdateOperations::VectorOperation(vector_operation) => {
            vector_operation.estimate_effect_area()
        }
        CollectionUpdateOperations::PayloadOperation(payload_operation) => {
            payload_operation.estimate_effect_area()
        }
        CollectionUpdateOperations::FieldIndexOperation(_) => OperationEffectArea::Empty,
    }
}

fn estimate_effect_area(&self) -> OperationEffectArea {
    match self {
        point_ops::PointOperations::UpsertPoints(insert_operations) => {
            insert_operations.estimate_effect_area()
        }
        point_ops::PointOperations::DeletePoints { ids } => {
            OperationEffectArea::Points(ids.clone())
        }
        point_ops::PointOperations::DeletePointsByFilter(filter) => {
            OperationEffectArea::Filter(filter.clone())
        }
        point_ops::PointOperations::SyncPoints(sync_op) => {
            debug_assert!(
                false,
                "SyncPoints operation should not be used during transfer"
            );
            OperationEffectArea::Points(sync_op.points.iter().map(|x| x.id).collect())
        }
    }
}

fn estimate_effect_area(&self) -> OperationEffectArea {
    match self {
        vector_ops::VectorOperations::UpdateVectors(update_operation) => {
            let ids = update_operation.points.iter().map(|p| p.id).collect();
            OperationEffectArea::Points(ids)
        }
        vector_ops::VectorOperations::DeleteVectors(ids, _) => {
            OperationEffectArea::Points(ids.points.clone())
        }
        vector_ops::VectorOperations::DeleteVectorsByFilter(filter, _) => {
            OperationEffectArea::Filter(filter.clone())
        }
    }
}

fn estimate_effect_area(&self) -> OperationEffectArea {
    match self {
        point_ops::PointInsertOperationsInternal::PointsBatch(batch) => {
            OperationEffectArea::Points(batch.ids.clone())
        }
        point_ops::PointInsertOperationsInternal::PointsList(list) => {
            OperationEffectArea::Points(list.iter().map(|x| x.id).collect())
        }
    }
}

fn estimate_effect_area(&self) -> OperationEffectArea {
    match self {
        PayloadOps::SetPayload(set_payload) => {
            if let Some(points) = &set_payload.points {
                OperationEffectArea::Points(points.clone())
            } else if let Some(filter) = &set_payload.filter {
                OperationEffectArea::Filter(filter.clone())
            } else {
                OperationEffectArea::Empty
            }
        }
        PayloadOps::DeletePayload(delete_payload) => {
            if let Some(points) = &delete_payload.points {
                OperationEffectArea::Points(points.clone())
            } else if let Some(filter) = &delete_payload.filter {
                OperationEffectArea::Filter(filter.clone())
            } else {
                OperationEffectArea::Empty
            }
        }
        PayloadOps::ClearPayload { points } => OperationEffectArea::Points(points.clone()),
        PayloadOps::ClearPayloadByFilter(filter) => OperationEffectArea::Filter(filter.clone()),
        PayloadOps::OverwritePayload(set_payload) => {
            if let Some(points) = &set_payload.points {
                OperationEffectArea::Points(points.clone())
            } else if let Some(filter) = &set_payload.filter {
                OperationEffectArea::Filter(filter.clone())
            } else {
                OperationEffectArea::Empty
            }
        }
    }
}

fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
