/// Validate that GeoLineString has at least 4 points and is closed.
pub fn validate_geo_polygon_line_helper(line: &GeoLineString) -> Result<(), ValidationError> {
    let points = &line.points;
    let min_length = 4;
    if points.len() < min_length {
        let mut err: ValidationError = ValidationError::new("min_line_length");
        err.add_param(Cow::from("length"), &points.len());
        err.add_param(Cow::from("min_length"), &min_length);
        return Err(err);
    }

    let first_point = &points[0];
    let last_point = &points[points.len() - 1];
    if first_point != last_point {
        return Err(ValidationError::new("closed_line"));
    }

    Ok(())
}

pub fn validate_geo_polygon_exterior(line: &Option<GeoLineString>) -> Result<(), ValidationError> {
    match line {
        Some(l) => {
            if l.points.is_empty() {
                return Err(ValidationError::new("not_empty"));
            }
            validate_geo_polygon_line_helper(l)?;
            Ok(())
        }
        _ => Err(ValidationError::new("not_empty")),
    }
}

pub fn validate_geo_polygon_interiors(lines: &Vec<GeoLineString>) -> Result<(), ValidationError> {
    for line in lines {
        validate_geo_polygon_line_helper(line)?;
    }
    Ok(())
}

pub async fn make_grpc_channel(
    timeout: Duration,
    connection_timeout: Duration,
    uri: Uri,
    tls_config: Option<ClientTlsConfig>,
) -> Result<Channel, TonicError> {
    let mut endpoint = Channel::builder(uri)
        .timeout(timeout)
        .connect_timeout(connection_timeout);
    if let Some(config) = tls_config {
        endpoint = endpoint.tls_config(config)?;
    }
    // `connect` is using the `Reconnect` network service internally to handle dropped connections
    endpoint.connect().await
}

pub async fn new(
    uri: Uri,
    timeout: Duration,
    connection_timeout: Duration,
    tls_config: Option<ClientTlsConfig>,
    usage_per_channel: usize,
    min_channels: usize,
) -> Result<Self, TonicError> {
    let mut channels = Vec::with_capacity(min_channels);
    for _ in 0..min_channels {
        let channel =
            make_grpc_channel(timeout, connection_timeout, uri.clone(), tls_config.clone())
                .await?;
        channels.push(channel);
    }

    let init_at = Instant::now();

    let pool = DynamicPool::new(channels, usage_per_channel, min_channels);
    Ok(Self {
        pool: Mutex::new(pool),
        init_at,
        uri,
        timeout,
        connection_timeout,
        tls_config,
    })
}

pub fn init_at(&self) -> Instant {
    self.init_at
}

pub async fn choose(&self) -> Result<CountedItem<Channel>, TonicError> {
    let channel = self.pool.lock().choose();
    let channel = match channel {
        None => {
            let channel = make_grpc_channel(
                self.timeout,
                self.connection_timeout,
                self.uri.clone(),
                self.tls_config.clone(),
            )
            .await?;
            self.pool.lock().add(channel)
        }
        Some(channel) => channel,
    };
    Ok(channel)
}

pub fn drop_channel(&self, channel: CountedItem<Channel>) {
    self.pool.lock().drop_item(channel);
}

