/// If `wait_timeout` is not supplied - then default duration will be used.
/// This function needs to be called from a runtime with timers enabled.
pub async fn submit_collection_meta_op(
    &self,
    operation: CollectionMetaOperations,
    wait_timeout: Option<Duration>,
) -> Result<bool, StorageError> {
    // if distributed deployment is enabled
    if let Some(state) = self.consensus_state.as_ref() {
        let start = Instant::now();

        // List of operations to await for collection to be operational
        let mut expect_operations: Vec<ConsensusOperations> = vec![];

        let op = match operation {
            CollectionMetaOperations::CreateCollection(mut op) => {
                self.toc.check_write_lock()?;
                if !op.is_distribution_set() {
                    match op.create_collection.sharding_method.unwrap_or_default() {
                        ShardingMethod::Auto => {
                            // Suggest even distribution of shards across nodes
                            let number_of_peers = state.0.peer_count();
                            let shard_distribution = self
                                .toc
                                .suggest_shard_distribution(
                                    &op,
                                    NonZeroU32::new(number_of_peers as u32)
                                        .expect("Peer count should be always >= 1"),
                                )
                                .await;

                            // Expect all replicas to become active eventually
                            for (shard_id, peer_ids) in &shard_distribution.distribution {
                                for peer_id in peer_ids {
                                    expect_operations.push(
                                        ConsensusOperations::initialize_replica(
                                            op.collection_name.clone(),
                                            *shard_id,
                                            *peer_id,
                                        ),
                                    );
                                }
                            }

                            op.set_distribution(shard_distribution);
                        }
                        ShardingMethod::Custom => {
                            // If custom sharding is used - we don't create any shards in advance
                            let empty_distribution = ShardDistributionProposal::empty();
                            op.set_distribution(empty_distribution);
                        }
                    }
                }
                CollectionMetaOperations::CreateCollection(op)
            }
            CollectionMetaOperations::CreateShardKey(op) => {
                self.toc.check_write_lock()?;
                CollectionMetaOperations::CreateShardKey(op)
            }

            op => op,
        };

        let operation_awaiter =
            // If explicit timeout is set - then we need to wait for all expected operations.
            // E.g. in case of `CreateCollection` we will explicitly wait for all replicas to be activated.
            // We need to register receivers(by calling the function) before submitting the operation.
            if !expect_operations.is_empty() {
                Some(state.await_for_multiple_operations(expect_operations, wait_timeout))
            } else {
                None
            };

        let do_sync_nodes = match &op {
            // Sync nodes after collection or shard key creation
            CollectionMetaOperations::CreateCollection(_)
            | CollectionMetaOperations::CreateShardKey(_) => true,
            // Sync nodes when creating or renaming collection aliases
            CollectionMetaOperations::ChangeAliases(changes) => {
                changes.actions.iter().any(|change| match change {
                    AliasOperations::CreateAlias(_) | AliasOperations::RenameAlias(_) => true,
                    AliasOperations::DeleteAlias(_) => false,
                })
            }
            // No need to sync nodes for other operations
            CollectionMetaOperations::UpdateCollection(_)
            | CollectionMetaOperations::DeleteCollection(_)
            | CollectionMetaOperations::TransferShard(_, _)
            | CollectionMetaOperations::SetShardReplicaState(_)
            | CollectionMetaOperations::DropShardKey(_)
            | CollectionMetaOperations::CreatePayloadIndex(_)
            | CollectionMetaOperations::DropPayloadIndex(_)
            | CollectionMetaOperations::Nop { .. } => false,
        };

        let res = state
            .propose_consensus_op_with_await(
                ConsensusOperations::CollectionMeta(Box::new(op)),
                wait_timeout,
            )
            .await?;

        if let Some(operation_awaiter) = operation_awaiter {
            // Actually await for expected operations to complete on the consensus
            match operation_awaiter.await {
                Ok(Ok(())) => {} // all good
                Ok(Err(err)) => {
                    log::warn!("Not all expected operations were completed: {}", err)
                }
                Err(err) => log::warn!("Awaiting for expected operations timed out: {}", err),
            }
        }

        // On some operations, synchronize all nodes to ensure all are ready for point operations
        if do_sync_nodes {
            let remaining_timeout =
                wait_timeout.map(|timeout| timeout.saturating_sub(start.elapsed()));
            if let Err(err) = self.await_consensus_sync(remaining_timeout).await {
                log::warn!("Failed to synchronize all nodes after collection operation in time, some nodes may not be ready: {err}");
            }
        }

        Ok(res)
    } else {
        if let CollectionMetaOperations::CreateCollection(_) = &operation {
            self.toc.check_write_lock()?;
        }
        self.toc.perform_collection_meta_op(operation).await
    }
}

pub fn cluster_status(&self) -> ClusterStatus {
    match self.consensus_state.as_ref() {
        Some(state) => state.cluster_status(),
        None => ClusterStatus::Disabled,
    }
}

pub async fn await_consensus_sync(
    &self,
    timeout: Option<Duration>,
) -> Result<(), StorageError> {
    let timeout = timeout.unwrap_or(CONSENSUS_META_OP_WAIT);

    if let Some(state) = self.consensus_state.as_ref() {
        let state = state.hard_state();
        let term = state.term;
        let commit = state.commit;
        let channel_service = self.toc.get_channel_service();
        let this_peer_id = self.toc.this_peer_id;

        channel_service
            .await_commit_on_all_peers(this_peer_id, commit, term, timeout)
            .await?;

        log::debug!(
            "Consensus is synchronized with term: {}, commit: {}",
            term,
            commit
        );

        Ok(())
    } else {
        Ok(())
    }
}

fn deref(&self) -> &Self::Target {
    self.toc.deref()
}

fn search_points(criterion: &mut Criterion) {
    let config = Config::parse();

    let runtime = runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();

    let client = client(&config, &runtime).unwrap();
    let vector_size = vector_size(&config, &runtime, &client).unwrap();

    let request = config.search_points(vector_size);
    let mut rng = config.rng();

    criterion.bench_function("search_points", move |bench| {
        bench.to_async(&runtime).iter_batched(
            || (client.clone(), randomize(&request, &mut rng)),
            |(client, request)| async move { client.search_points(&request).await.unwrap() },
            BatchSize::SmallInput,
        )
    });
}

pub fn parse() -> Self {
    let uri = env_var("URI").unwrap_or_else(|| "http://127.0.0.1:6334".into());

    let timeout = time::Duration::from_secs_f32(parse_or(
        env_var("REQUEST_TIMEOUT").or_else(|| env_var("REQUEST")),
        10.,
    ));

    let connection_timeout =
        time::Duration::from_secs_f32(parse_or(env_var("CONNECTION_TIMEOUT"), 5.));

    let api_key = env_var("API_KEY");

    let collection_name = env_var("COLLECTION_NAME")
        .or_else(|| env_var("COLLECTION"))
        .unwrap_or_else(|| "benchmark".into());

    let limit = parse_or(env_var("LIMIT"), 10);
    let seed = parse_or(env_var("SEED"), 42);

    Self {
        uri,
        timeout,
        connection_timeout,
        api_key,
        collection_name,
        limit,
        seed,
    }
}

pub async fn client(&self) -> Result<QdrantClient> {
    let config = QdrantClientConfig {
        uri: self.uri.clone(),
        timeout: self.timeout,
        connect_timeout: self.connection_timeout,
        keep_alive_while_idle: false,
        api_key: self.api_key.clone(),
    };

    let client = QdrantClient::new(Some(config)).await?;

    Ok(client)
}

pub fn search_points(&self, vector_size: usize) -> SearchPoints {
    SearchPoints {
        collection_name: self.collection_name.clone(),
        vector: vec![0.; vector_size],
        limit: self.limit,
        ..Default::default()
    }
}

pub fn rng(&self) -> StdRng {
    StdRng::seed_from_u64(self.seed)
}

fn env_var(name: &str) -> Option<String> {
    match env::var(name) {
        Ok(var) => Some(var),
        Err(env::VarError::NotPresent) => None,
        Err(err) => panic!("failed to get `{}` env-var: {}", name, err),
    }
}

fn client(config: &Config, runtime: &Runtime) -> Result<Arc<QdrantClient>> {
    let client = runtime.block_on(config.client())?;
    Ok(Arc::new(client))
}

fn vector_size(config: &Config, runtime: &Runtime, client: &QdrantClient) -> Result<usize> {
    let response = runtime.block_on(client.collection_info(&config.collection_name))?;

    let vectors_config = response
        .result
        .context("`GetCollectionInfoResponse::result` is `None`")?
        .config
        .context("`CollectionInfo::config` is `None`")?
        .params
        .context("`CollectionConfig::params` is `None`")?
        .vectors_config
        .context("`CollectionParams::vectors_config` is `None`")?
        .config
        .context("`VectorsConfig::config` is `None`")?;

    let vector_params = match vectors_config {
        vectors_config::Config::Params(params) => params,
        _ => {
            return Err(anyhow::format_err!(
                "`search_points` only supports collections with a single vector per point"
            ));
        }
    };

    let vector_size = vector_params
        .size
        .try_into()
        .context("failed to convert `VectorParams::size` to `usize`")?;

    Ok(vector_size)
}

fn randomize(request: &SearchPoints, rng: &mut StdRng) -> SearchPoints {
    let mut request = request.clone();
    request.vector = (0..request.vector.len()).map(|_| rng.gen()).collect();
    request
}

fn get_init_file_path() -> PathBuf {
    std::env::var("QDRANT_INIT_FILE_PATH")
        .map(PathBuf::from)
        .unwrap_or_else(|_| DEFAULT_INITIALIZED_FILE.into())
}

pub fn setup_panic_hook(reporting_enabled: bool, reporting_id: String) {
    panic::set_hook(Box::new(move |panic_info| {
        let backtrace = Backtrace::force_capture().to_string();
        let loc = if let Some(loc) = panic_info.location() {
            format!(" in file {} at line {}", loc.file(), loc.line())
        } else {
            String::new()
        };
        let message = if let Some(s) = panic_info.payload().downcast_ref::<&str>() {
            s
        } else if let Some(s) = panic_info.payload().downcast_ref::<String>() {
            s
        } else {
            "Payload not captured as it is not a string."
        };

        log::error!("Panic backtrace: \n{}", backtrace);
        log::error!("Panic occurred{loc}: {message}");

        if reporting_enabled {
            ErrorReporter::report(message, &reporting_id, Some(&loc));
        }
    }));
}

/// Creates a file that indicates that the server has been started.
/// This file is used to check if the server has been successfully started before potential kill.
pub fn touch_started_file_indicator() {
    if let Err(err) = std::fs::write(get_init_file_path(), "") {
        log::warn!("Failed to create init file indicator: {}", err);
    }
}

/// Removes a file that indicates that the server has been started.
/// Use before server initialization to avoid false positives.
pub fn remove_started_file_indicator() {
    let path = get_init_file_path();
    if path.exists() {
        if let Err(err) = std::fs::remove_file(path) {
            log::warn!("Failed to remove init file indicator: {}", err);
        }
    }
}

/// Executable to inspect the content of a write ahead log folder (collection OR consensus WAL).
/// e.g:
/// `cargo run --bin wal_inspector storage/collections/test-collection/0/wal/ collection`
/// `cargo run --bin wal_inspector -- storage/node4/wal/ consensus` (expects `collections_meta_wal` folder as first child)
fn main() {
    let args: Vec<String> = env::args().collect();
    let wal_path = Path::new(&args[1]);
    let wal_type = args[2].as_str();
    match wal_type {
        "collection" => print_collection_wal(wal_path),
        "consensus" => print_consensus_wal(wal_path),
        _ => eprintln!("Unknown wal type: {}", wal_type),
    }
}

fn print_consensus_wal(wal_path: &Path) {
    // must live within a folder named `collections_meta_wal`
    let wal = ConsensusOpWal::new(wal_path.to_str().unwrap());
    println!("==========================");
    let first_index = wal.first_entry().unwrap();
    println!("First entry: {:?}", first_index);
    let last_index = wal.last_entry().unwrap();
    println!("Last entry: {:?}", last_index);
    println!("Offset of first entry: {:?}", wal.index_offset().unwrap());
    let entries = wal
        .entries(
            first_index.map(|f| f.index).unwrap_or(1),
            last_index.map(|f| f.index).unwrap_or(0) + 1,
            None,
        )
        .unwrap();
    for entry in entries {
        println!("==========================");
        let command = ConsensusOperations::try_from(&entry);
        let data = match command {
            Ok(command) => format!("{:?}", command),
            Err(_) => format!("{:?}", entry.data),
        };
        println!(
            "Entry ID:{}\nterm:{}\nentry_type:{}\ndata:{:?}",
            entry.index, entry.term, entry.entry_type, data
        )
    }
}

fn print_collection_wal(wal_path: &Path) {
    let wal: Result<SerdeWal<CollectionUpdateOperations>, _> =
        SerdeWal::new(wal_path.to_str().unwrap(), WalOptions::default());

    match wal {
        Err(error) => {
            eprintln!("Unable to open write ahead log in directory {wal_path:?}: {error}.");
        }
        Ok(wal) => {
            // print all entries
            let mut count = 0;
            for (idx, op) in wal.read_all() {
                println!("==========================");
                println!("Entry {}", idx);
                println!("{:?}", op);
                count += 1;
            }
            println!("==========================");
            println!("End of WAL.");
            println!("Found {} entries.", count);
        }
    }
}

async fn health_check(
    &self,
    _request: Request<HealthCheckRequest>,
) -> Result<Response<HealthCheckReply>, Status> {
    Ok(Response::new(VersionInfo::default().into()))
}

async fn check(
    &self,
    _request: Request<ProtocolHealthCheckRequest>,
) -> Result<Response<ProtocolHealthCheckResponse>, Status> {
    let response = ProtocolHealthCheckResponse {
